import "@testing-library/jest-dom/vitest";
import { render, screen, fireEvent, cleanup, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { LabelsPrintButton, labelsPrintBlockReason } from "../labels-print-button";

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("labelsPrintBlockReason", () => {
  it("explains an unreleased week in kitchen language, not a raw ISO date", () => {
    expect(
      labelsPrintBlockReason({ menuReleased: false, labelCount: 0, weekStart: "2026-09-14" }),
    ).toMatch(/week of Sep 14 – Sep 20/i);
  });

  it("explains an empty day when the menu is released", () => {
    expect(
      labelsPrintBlockReason({ menuReleased: true, labelCount: 0, weekStart: "2026-09-14" }),
    ).toMatch(/no tiffin deliveries/i);
  });

  it("is silent when there is something to print", () => {
    expect(
      labelsPrintBlockReason({ menuReleased: true, labelCount: 3, weekStart: "2026-09-14" }),
    ).toBeNull();
  });
});

describe("LabelsPrintButton", () => {
  it("pops the unreleased-week message instead of navigating to the PDF route", async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);

    render(
      <LabelsPrintButton
        dateIso="2026-09-17"
        weekStart="2026-09-14"
        menuReleased={false}
        labelCount={0}
      />,
    );

    fireEvent.click(screen.getByRole("button", { name: /print labels/i }));

    expect(screen.queryByRole("link")).not.toBeInTheDocument();
    expect(await screen.findByRole("dialog")).toHaveTextContent(/no menu is released/i);
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("shows the PDF route's message when the server refuses after the page loaded", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: false,
        status: 409,
        text: async () => "No menu is released for the week of Sep 14 – Sep 20. Release that week first.",
      }),
    );

    render(
      <LabelsPrintButton
        dateIso="2026-09-17"
        weekStart="2026-09-14"
        menuReleased={true}
        labelCount={2}
      />,
    );

    fireEvent.click(screen.getByRole("button", { name: /print labels/i }));

    expect(await screen.findByRole("dialog")).toHaveTextContent(/no menu is released/i);
  });
});

"use client";

import { useState, useTransition } from "react";
import { PrinterIcon } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@foundry/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@foundry/ui/dialog";
import { formatMenuWeekRange } from "@/lib/format/datetime";

export function labelsPrintBlockReason({
  menuReleased,
  labelCount,
  weekStart,
}: {
  menuReleased: boolean;
  labelCount: number;
  weekStart: string;
}): string | null {
  if (!menuReleased) {
    return `No menu is released for the week of ${formatMenuWeekRange(weekStart)}. Release that week first — labels must show the same meal the customer sees.`;
  }
  if (labelCount === 0) {
    return "No tiffin deliveries scheduled for this date.";
  }
  return null;
}

/**
 * Print used to be a <Link> to the PDF route. Button-as-child does not disable an
 * <a>, so staff still navigated into a text/plain 409 ("No menu week released…")
 * painted as a black page. Fetch the PDF here and pop the message instead.
 */
export function LabelsPrintButton({
  dateIso,
  weekStart,
  menuReleased,
  labelCount,
}: {
  dateIso: string;
  weekStart: string;
  menuReleased: boolean;
  labelCount: number;
}) {
  const [pending, start] = useTransition();
  const [message, setMessage] = useState<string | null>(null);

  const print = () => {
    const blocked = labelsPrintBlockReason({ menuReleased, labelCount, weekStart });
    if (blocked) {
      setMessage(blocked);
      return;
    }
    start(async () => {
      try {
        const res = await fetch(`/dashboard/labels/pdf?date=${dateIso}`);
        if (!res.ok) {
          const body = (await res.text()).trim();
          setMessage(body || "Could not print labels.");
          return;
        }
        const blob = await res.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `labels-${dateIso}.pdf`;
        a.click();
        URL.revokeObjectURL(url);
      } catch {
        toast.error("Could not print labels.");
      }
    });
  };

  return (
    <>
      <Button onClick={print} disabled={pending}>
        <PrinterIcon data-icon="inline-start" /> Print labels
      </Button>
      <Dialog open={message != null} onOpenChange={(open) => { if (!open) setMessage(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Can't print labels</DialogTitle>
            <DialogDescription>{message}</DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button onClick={() => setMessage(null)}>OK</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

