"use client";

import { useEffect, useState, useTransition } from "react";
import { Check, ChevronsUpDown } from "lucide-react";
import { Button } from "@foundry/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@foundry/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@foundry/ui/popover";
import { searchUsersByEmailAction } from "@/lib/services/organizations-actions";
import type { UserSearchRow } from "@/lib/services/organizations.service";

export function UserPicker({ onSelect }: { onSelect: (user: UserSearchRow) => void }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<UserSearchRow[]>([]);
  const [selected, setSelected] = useState<UserSearchRow | null>(null);
  const [pending, startTransition] = useTransition();

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    const handle = setTimeout(() => {
      startTransition(async () => {
        setResults(await searchUsersByEmailAction(query));
      });
    }, 250);
    return () => clearTimeout(handle);
  }, [query]);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" role="combobox" aria-expanded={open} className="justify-between">
          {selected ? selected.email : "Search by email…"}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="p-0" align="start">
        <Command shouldFilter={false}>
          <CommandInput placeholder="Type an email…" value={query} onValueChange={setQuery} />
          <CommandList>
            <CommandEmpty>{pending ? "Searching…" : "No matches."}</CommandEmpty>
            <CommandGroup>
              {results.map((user) => (
                <CommandItem
                  key={user.publicId}
                  value={user.publicId}
                  onSelect={() => {
                    setSelected(user);
                    onSelect(user);
                    setOpen(false);
                  }}
                >
                  <Check
                    className={`mr-2 h-4 w-4 ${selected?.publicId === user.publicId ? "opacity-100" : "opacity-0"}`}
                  />
                  {user.email}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { blockedBy, resolveStatuses } from "@foundry/crm/server";
import { requireAdmin } from "@/lib/auth/guards";
import { currentUserId, recordAudit } from "@/lib/services/session-service";
import { PLUGINS } from "@/lib/plugins.server";

function revalidatePluginPaths() {
  revalidatePath("/dashboard/settings/integrations");
  revalidatePath("/dashboard/settings/payments");
  revalidatePath("/dashboard/settings/clover");
  revalidatePath("/dashboard/settings");
}

/**
 * Install/uninstall any plugin in the app registry.
 * Returns errors rather than throwing — a thrown Server Action error reaches
 * the client as an opaque digest with no usable message.
 */
export async function setPluginInstalledAction(
  id: string,
  installed: boolean,
): Promise<{ error?: string }> {
  await requireAdmin();

  const plugin = PLUGINS.find((p) => p.id === id);
  if (!plugin) return { error: "Unknown plugin" };

  const statuses = await resolveStatuses(PLUGINS);

  if (installed) {
    const missing = blockedBy(PLUGINS, id, statuses);
    if (missing.length) {
      return { error: `Install ${missing.join(", ")} first` };
    }
  }

  // The store write can fail (DB down, constraint). Returning the message keeps
  // the constraint true end-to-end — an uncaught throw here would reach the
  // admin as an opaque digest with nothing actionable in it.
  try {
    installed ? await plugin.install() : await plugin.uninstall();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "Could not update plugin" };
  }

  await recordAudit({
    entity: "integrations",
    entityPublicId: id,
    operation: installed ? "create" : "delete",
    changes: { _action: installed ? `${id}_install` : `${id}_uninstall` },
    createdBy: await currentUserId(),
  });

  revalidatePluginPaths();
  return {};
}

import { eq } from "drizzle-orm";
import { notFound } from "next/navigation";
import { db } from "@/db/client";
import { orders, payments, users } from "@/db/schema";
import { CheckCircle2Icon, ClockIcon, HourglassIcon } from "lucide-react";
import { Card } from "@foundry/ui/card";
import { StaticMap } from "@foundry/design-system";
import { getSession } from "@/lib/auth/session";
import { getAppSettings } from "@/lib/services/app-settings.service";
import { getClaimPaymentContext } from "@/lib/services/orders.service";
import { ClaimPayment } from "@/components/customer/wallet/claim-payment";

// Looks up an order by deploymentId — render per request, never prerender.
export const dynamic = "force-dynamic";

export default async function ActivatePage({ params }: { params: Promise<{ deploymentId: string }> }) {
  const { deploymentId } = await params;
  const [sub] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId)).limit(1);
  if (!sub) notFound();

  const [pay] = await db
    .select({ publicId: payments.publicId, status: payments.status })
    .from(payments)
    .where(eq(payments.orderId, sub.id))
    .limit(1);

  const waitlisted = sub.status === "waitlisted";
  const inReview = pay?.status === "pending_verification";
  const needsPayment = pay != null && (pay.status === "awaiting_payment" || pay.status === "rejected");
  const claimable = inReview || needsPayment;

  const session = await getSession();
  let ownsOrder = false;
  if (session?.user?.id && sub.userId != null) {
    const [u] = await db
      .select({ publicId: users.publicId })
      .from(users)
      .where(eq(users.id, sub.userId))
      .limit(1);
    ownsOrder = u?.publicId === session.user.id;
  }

  const { currency } = await getAppSettings();
  const claimCtx =
    claimable && ownsOrder && pay ? await getClaimPaymentContext(pay.publicId) : null;

  const state = waitlisted
    ? {
        Icon: HourglassIcon,
        title: "You're on the waitlist",
        body: "Delivery isn't open in your area yet. We'll email you the moment it is.",
      }
    : inReview
      ? {
          Icon: ClockIcon,
          title: "Waiting for confirmation",
          body: "We're checking your payment. Your plan starts as soon as it's approved.",
        }
      : needsPayment
        ? {
            Icon: ClockIcon,
            title: "Almost there",
            body: "Your plan is reserved. Send your payment to get it started.",
          }
        : {
            Icon: CheckCircle2Icon,
            title: "You're subscribed",
            body: "Your plan is active. Welcome to Tiffin Grab.",
          };

  return (
    <main className="mx-auto flex min-h-[100dvh] max-w-md flex-col justify-center gap-4 px-4 py-10">
      <Card className="gap-0 rounded-3xl p-6 shadow-sm sm:p-8">
        <span className="bg-primary/15 text-primary grid size-12 place-items-center rounded-full">
          <state.Icon className="size-6" />
        </span>
        <h1 className="mt-5 text-[1.75rem] leading-tight font-semibold tracking-tight">{state.title}</h1>
        <p className="text-muted-foreground mt-2 text-[0.95rem] leading-relaxed">{state.body}</p>
        <p className="text-muted-foreground mt-4 text-xs">
          Order <span className="text-foreground font-medium tabular-nums">{sub.deploymentId}</span>
        </p>

        {claimable && !waitlisted && (
          <div className="bg-muted/40 mt-6 rounded-2xl p-4 text-sm">
            {claimCtx ? (
              <ClaimPayment ctx={claimCtx} currency={currency} />
            ) : (
              <p className="text-muted-foreground">
                Sign in to see payment details and confirm what you sent.{" "}
                <a className="text-primary font-medium underline-offset-4 hover:underline" href="/me/wallet?tab=bills">
                  Open Finances
                </a>
              </p>
            )}
          </div>
        )}

        {sub.latitude != null && sub.longitude != null && (
          <div className="mt-6 overflow-hidden rounded-2xl border">
            <StaticMap
              center={{ lat: sub.latitude, lng: sub.longitude }}
              markers={[{ lat: sub.latitude, lng: sub.longitude }]}
              heightPx={180}
            />
          </div>
        )}

        {waitlisted ? (
          <a
            className="border-border text-foreground mt-6 inline-flex h-12 items-center justify-center rounded-full border px-6 text-sm font-semibold transition-transform active:scale-[0.98]"
            href="/"
          >
            Back to home
          </a>
        ) : claimable ? (
          <a
            className="border-border text-foreground mt-6 inline-flex h-12 items-center justify-center rounded-full border px-6 text-sm font-semibold transition-transform active:scale-[0.98]"
            href="/me"
          >
            Back to home
          </a>
        ) : (
          <a
            className="bg-primary text-primary-foreground mt-6 inline-flex h-12 items-center justify-center rounded-full px-6 text-sm font-semibold transition-transform active:scale-[0.98]"
            href="/me"
          >
            View my deliveries
          </a>
        )}
      </Card>
    </main>
  );
}

