const ACTIONS: TripAction[] = ["pick", "swap", "move"];
const WEEK = new Intl.DateTimeFormat("en-CA", { month: "short", day: "numeric", timeZone: "UTC" });
const weekTitle = (m: string) => `${WEEK.format(new Date(`${m}T00:00:00Z`))} – ${WEEK.format(new Date(`${addDays(m, 6)}T00:00:00Z`))}`;

interface Props {
  /** The ONE plan on screen; switching plans reloads the page for the other plan. */
  plan: PlanView;
  /** All the customer's plans, ordered by start date, for the tabs on top. */
  subs: Subscription[];
  windows: Record<string, SubscriptionWindow>;
  /** Trips of the selected week for this plan. */
  trips: Trip[];
  /** Eating-day agenda of this plan across the whole range. */
  agenda: Agenda;
  weekStart: string;
  firstWeek: string;
  lastWeek: string;
  now: number;
  /** Account name for the page heading. */
  customerName?: string | null;
  /** An e-Transfer is unconfirmed: calendar is hidden; claim form is shown instead. */
  locked?: boolean;
  /** Claim form for payment-review plans; null when settled or unavailable. */
  claimPayment?: ClaimPaymentContext | null;
  currency?: string;
  initialTrip: string | null;
  initialAction?: string | null;
}

function PlanTab({ selected, className, ...rest }: React.ButtonHTMLAttributes<HTMLButtonElement> & { selected: boolean }) {
  return <button type="button" aria-pressed={selected} {...rest} className={cn(FOCUS, "flex min-h-11 shrink-0 flex-col justify-center rounded-2xl border-[1.5px] px-4 py-1.5 text-left [touch-action:manipulation]", selected ? "border-[var(--primary)] bg-[var(--primary-wash,#FBE3D2)]" : "border-[var(--border)] bg-[var(--card,#fff)]", className)} />;
}
const rank = (t: Trip) => (t.status === "upcoming" ? 0 : t.status === "failed" ? 1 : 2);

export function DeliveriesView({ plan, subs, windows, trips, agenda, weekStart, firstWeek, lastWeek, now, customerName, locked = false, claimPayment = null, currency = "CAD", initialTrip, initialAction }: Props) {
  const router = useRouter();
  const [navigating, startNav] = useTransition();
  const multi = subs.length > 1;
  const color = PLAN_COLORS[Math.max(subs.findIndex((s) => s.publicId === plan.orderId), 0) % PLAN_COLORS.length]!;

  const [sel, setSel] = useState<string | null>(initialTrip);
  const [wk, setWk] = useState(weekStart);
  if (wk !== weekStart) {
    setWk(weekStart);
    setSel(initialTrip);
  }
  const [requested, setActive] = useState<TripAction | null>(() => ACTIONS.find((a) => a === initialAction) ?? null);
  // Payment unconfirmed: the plan is view-only, so no sheet opens from any entry point (buttons, ?action= links).
  const active = locked ? null : requested;
  const [info, setInfo] = useState<EatingRow | null>(null);
  const [toast, setToast] = useState<string | null>(null);
  const { ctx, sub, today } = plan;
  const tz = ctx.timezone;
  const weekEnd = addDays(weekStart, 6);

  const shown = useMemo(() => eatingRowsInWeek(trips, weekStart, weekEnd), [trips, weekStart, weekEnd]);
  const allRows = useMemo(() => buildEatingDays(trips), [trips]);
  const inWeek = !!sel && sel >= weekStart && sel <= weekEnd;
  // Tapping the truck day (the date a moved tiffin arrives) selects that meal even when its eat date is another week.
  const row: EatingRow | null = (sel ? shown.find((r) => r.date === sel) ?? shown.find((r) => r.trip.date === sel) : null) ?? (inWeek ? null : [...shown].sort((a, b) => rank(a.trip) - rank(b.trip) || a.date.localeCompare(b.date))[0] ?? null);
  const trip = row?.trip ?? null;
  const emptyDay = !row && inWeek ? sel : null;
  // Swap only when this eating day has a swap the customer can still make (same filter the swap sheet applies).
  const eatingSwaps = trip && row ? plan.days.find((d) => d.date === trip.date)?.eatingDays?.find((e) => e.date === row.date) : undefined;
  const left = plan.sub.categoryCounts ? applySwapsToCounts(plan.sub.categoryCounts, eatingSwaps?.appliedSwaps ?? []) : null;
  // Entry gate: at least one configured pair has an even-portion give count left.
  // Full Max TU / Meal Rules filtering still happens in listValidSwapOptionsForDelivery.
  const canSwap = (eatingSwaps?.swapPairs ?? []).some((p) => {
    const available = left ? (left[p.fromCategory] ?? 0) : 1;
    const cats = plan.swapCategories ?? {};
    return hasEvenPortionSwap(cats[p.fromCategory], cats[p.toCategory], available);
  });
  // The menu of this week isn't out: pick/swap are disabled, everything else (dates, move, info) still shows.
  const weekDays = plan.days.filter((d) => d.date >= weekStart && d.date <= weekEnd);
  const menuOut = weekDays.length > 0 && weekDays.every((d) => d.menuWeekId == null);
  const model = trip ? actionModel(trip, now, ctx, { canSwap, menuOut: menuOut && trip.date >= weekStart && trip.date <= weekEnd, locked, isDeliveryDay: row ? isAddressRow(allRows, row) : true, movedTo: row?.movedTo }) : null;

  const dots = useMemo(() => {
    const out: Record<string, { orderId: string; status: DeliveryStatus; truck: boolean }[]> = {};
    for (const [date, ds] of Object.entries(agenda)) out[date] = ds.map((d) => ({ orderId: d.orderId, status: dotStatus(d, now), truck: d.truck }));
    return out;
  }, [agenda, now]);

  const qs = (over: Record<string, string | null>) => {
    const p = new URLSearchParams(typeof window === "undefined" ? "" : window.location.search);
    for (const [k, v] of Object.entries(over)) (v === null ? p.delete(k) : p.set(k, v));
    const s = p.toString();
    return s ? `?${s}` : "";
  };
  const goWeek = (monday: string, over: Record<string, string | null> = {}) =>
    startNav(() => router.replace(`/me${qs({ week: monday, trip: null, action: null, ...over })}`, { scroll: false }));
  const select = (date: string) => {
    setSel(date);
    window.history.replaceState(null, "", qs({ trip: date, action: null }));
    if (window.innerWidth < 1024) window.scrollTo({ top: 0, behavior: "smooth" });
  };
  const goTo = (date: string) => {
    const mon = mondayOf(date);
    if (mon === weekStart) return select(date);
    setSel(date);
    goWeek(mon, { trip: date });
  };
  const pickDay = (iso: string) => (mondayOf(iso) === weekStart ? select(iso) : goTo(iso));
  // A plain replace can serve the previous plan's cached RSC render for the same path — refresh forces this plan's own ctx/counts.
  const switchPlan = (id: string) => startNav(() => (router.replace(`/me?sub=${id}`, { scroll: false }), router.refresh()));

  const closeToast = useCallback(() => setToast(null), []);
  const changed = (message: string) => (setToast(message), router.refresh());
  const done = (message?: string) => {
    setActive(null);
    if (message) changed(message);
  };
  const linkCls = "text-sm font-semibold text-[var(--muted-foreground,#6E6558)] underline underline-offset-4 [touch-action:manipulation]";

  const dates = Object.keys(agenda).sort();
  const next = dates.find((d) => d > weekEnd) ?? [...dates].reverse().find((d) => d < weekStart) ?? null;
  const upcoming = Object.values(agenda).flat().filter((d) => d.truck && d.status === "scheduled" && d.deliveryDate >= today).sort((a, b) => a.deliveryDate.localeCompare(b.deliveryDate))[0];
  const hasBar = !locked && !!(trip && model && (model.rows.length > 0 || model.goTo));

  return (
    <div className={`${FONT} ${hasBar ? "pb-[190px]" : "pb-8"} lg:pb-8`}>
      <PlanHeader
        name={customerName}
        sub={sub}
        counts={plan.counts}
        renew={renewDays(plan.counts.lastDeliveryDate, today)}
      />

      {multi && (
        <nav aria-label="Your plans" className="mb-4 flex gap-2 overflow-x-auto pb-1 [scrollbar-width:none] lg:flex-wrap">
          {subs.map((s) => (
            <PlanTab key={s.publicId} selected={s.publicId === plan.orderId} onClick={() => switchPlan(s.publicId)}>
              <span className="flex items-center gap-1.5 text-sm font-semibold leading-tight">
                {s.mealSizeName}
                <OrderStatusBadge status={s.displayStatus} />
              </span>
              <span className="text-xs leading-tight text-[var(--muted-foreground,#6E6558)]">{windowLabel(windows[s.publicId], today)}</span>
            </PlanTab>
          ))}
        </nav>
      )}

      {locked && claimPayment && (
        <Card className="mb-4 p-5" data-testid="payment-claim">
          <ClaimPayment ctx={claimPayment} currency={currency} />
        </Card>
      )}

      {locked && !claimPayment && (
        <Notice>We&apos;re confirming your payment. Your plan is view-only until then; editing meals and moves unlock once it&apos;s approved.</Notice>
      )}

      {!locked && (
      <>
      {upcoming && (
        <button
          type="button"
          data-testid="next-delivery"
          onClick={() => goTo(upcoming.deliveryDate)}
          className={cn(FOCUS, "mb-4 flex min-h-12 w-full items-center gap-3 rounded-2xl border-[1.5px] border-[var(--border)] bg-[var(--card,#fff)] px-4 py-2.5 text-left [touch-action:manipulation]")}
        >
          <Truck aria-hidden className="size-5 shrink-0 text-[var(--muted-foreground,#6E6558)]" />
          <span className="min-w-0">
            <span className="block text-[15px] font-semibold">Next delivery: {humanDate(upcoming.deliveryDate)}, {tiffins(upcoming.units)} ({upcoming.covers.map(weekdayShort).join(" + ")})</span>
            <span className="block text-[13px] text-[var(--muted-foreground,#6E6558)]">Changes close {formatCutoff(upcoming.cutoffAt, tz)}</span>
          </span>
        </button>
      )}

      <div className="mb-4">
        <WeekStrip
          firstWeek={firstWeek}
          lastWeek={lastWeek}
          week={weekStart}
          today={today}
          selectedDay={row?.date ?? sel}
          dots={dots}
          colorOf={() => color}
          onPickDay={pickDay}
          onWeek={(m) => goWeek(m)}
        />
      </div>

      <div className={navigating ? "opacity-60 transition-opacity" : undefined} aria-busy={navigating}>
        <h2 className="mb-2 px-1 text-xs font-semibold uppercase tracking-[0.25em] text-[var(--muted-foreground,#6E6558)]">{weekTitle(weekStart)}</h2>
        {shown.length === 0 && !emptyDay ? (
          <Card className="space-y-3 p-6">
            <p className="text-[15px] font-semibold">Nothing to eat this week.</p>
            {next ? (
              <>
                <p className="text-sm text-[var(--muted-foreground,#6E6558)]">{next > weekStart ? "Next" : "Last"} day: {humanDate(next)}.</p>
                <Button variant="primary" onClick={() => goTo(next)}>Go to {humanDate(next)}</Button>
              </>
            ) : (
              <p className="text-sm text-[var(--muted-foreground,#6E6558)]">Nothing else is scheduled.</p>
            )}
          </Card>
        ) : (
          <>
            {emptyDay && <Card className="mb-4 p-4"><p className="text-[15px] font-semibold">Nothing planned on {humanDate(emptyDay)}.</p></Card>}
            <div className="grid grid-cols-[minmax(0,1fr)] gap-6 lg:grid-cols-[minmax(280px,340px)_minmax(0,1fr)] lg:items-start lg:gap-8">
              <div className="space-y-0.5">
                {menuOut && <Card className="mb-2 p-4" data-testid="menu-not-released"><p className="text-[15px] font-semibold">Menu not released yet.</p><p className="text-sm text-[var(--muted-foreground,#6E6558)]">Meals appear below once the kitchen releases this week&apos;s menu. You can still move a day.</p></Card>}
                {shown.map((r) => (
                  <div key={r.date} className="flex items-center">
                    <div className="min-w-0 flex-1"><EatingRowButton row={r} selected={!!row && r.date === row.date} onSelect={(x) => select(x.date)} menuOut={menuOut} /></div>
                    <InfoButton label={`Details for ${humanDate(r.date)}`} onClick={() => setInfo(r)} />
                  </div>
                ))}
              </div>

              <div className="min-w-0 space-y-4">
                {row && trip && model ? (
                  <EatingCard row={row} tz={tz} reason={trip.status === "upcoming" ? null : model.closedReason ?? model.av.pick.why}>
                    <div className="mt-6 hidden lg:block">
                      <TripActions model={model} layout="card" onAction={setActive} onGoTo={goTo} />
                    </div>
                  </EatingCard>
                ) : null}
              </div>
            </div>

            {trip && model && (model.rows.length > 0 || model.goTo) && (
              <div className={`${FONT} fixed inset-x-0 bottom-[calc(57px+env(safe-area-inset-bottom))] z-30 border-t border-[var(--border)] bg-[color-mix(in_oklab,var(--card)_92%,transparent)] px-4 py-2 backdrop-blur-xl lg:hidden`}>
                <TripActions model={model} layout="bar" onAction={setActive} onGoTo={goTo} />
              </div>
            )}
          </>
        )}
      </div>
      </>
      )}

      {active && trip && <ActionSheet action={active} trip={trip} day={row?.date} plan={plan} open onDone={done} onChanged={changed} />}
      {info && <TripInfoSheet row={info} tz={tz} plan={plan} open onClose={() => setInfo(null)} />}
      <Toast open={toast !== null} onClose={closeToast}>{toast}</Toast>
    </div>
  );
}

"use client";
import { ChevronLeft, ChevronRight, Truck, Utensils } from "lucide-react";
import { useEffect, useRef } from "react";
import { STATUS_COLOR, STATUS_LABEL, type DeliveryStatus } from "@/components/customer/kit";
import { cn, FONT, FOCUS } from "@/components/customer/kit/cn";
import { addDays, weekDays } from "@/lib/deliveries-view/week";

export type StripDot = { orderId: string; status: DeliveryStatus; truck: boolean };

const WD = ["M", "T", "W", "T", "F", "S", "S"];
const MON = new Intl.DateTimeFormat("en-CA", { month: "short", timeZone: "UTC" });
const d = (iso: string) => new Date(`${iso}T00:00:00Z`);
/** Status bar: colour is the delivery status (delivered, upcoming, hold, vacation), not the plan. */
// Combined keeps StatusDot's dashed-outline shape so it isn't told apart by colour alone.
function Dot({ status }: { status: DeliveryStatus }) {
  const combined = status === "combined";
  return (
    <span
      className={cn("h-1.5 min-w-0 max-w-5 flex-1 rounded-full", combined && "border-[1.5px] border-dashed")}
      style={combined ? { borderColor: STATUS_COLOR.combined } : { background: STATUS_COLOR[status] }}
    />
  );
}

const label = (r: string) => `${MON.format(d(r))} ${d(r).getUTCDate()} – ${MON.format(d(addDays(r, 6))) === MON.format(d(r)) ? "" : `${MON.format(d(addDays(r, 6)))} `}${d(addDays(r, 6)).getUTCDate()}`;

interface Props {
  firstWeek: string;
  lastWeek: string;
  week: string;
  today: string;
  selectedDay: string | null;
  dots: Record<string, StripDot[]>;
  colorOf: (orderId: string) => string;
  onPickDay: (iso: string) => void;
  onWeek: (monday: string) => void;
  /** Picker mode (move sheet): one week per screen, arrows in the header, no meal dots, unpickable days greyed. */
  picker?: { isDisabled: (iso: string) => boolean; onDisabledTap?: (iso: string) => void };
}

export function WeekStrip({ firstWeek, lastWeek, week, today, selectedDay, dots, colorOf, onPickDay, onWeek, picker }: Props) {
  const box = useRef<HTMLDivElement>(null);
  const weeks: string[] = [];
  for (let w = firstWeek; w <= lastWeek; w = addDays(w, 7)) weeks.push(w);

  useEffect(() => {
    const el = box.current?.querySelector<HTMLElement>(`[data-week="${week}"]`);
    if (el && box.current?.scrollTo) box.current.scrollTo({ left: el.offsetLeft - box.current.offsetLeft, behavior: "smooth" });
  }, [week]);

  const arrow = "hidden size-11 shrink-0 place-items-center self-center rounded-full hover:bg-[var(--muted)] disabled:opacity-30 lg:grid [touch-action:manipulation]";
  return (
    <div className={cn(FONT, "flex gap-1")} data-testid="week-strip">
      {!picker && <button type="button" aria-label="Previous week" disabled={week <= firstWeek} onClick={() => onWeek(addDays(week, -7))} className={cn(arrow, FOCUS)}><ChevronLeft aria-hidden className="size-5" /></button>}
      <div ref={box} role="group" aria-label="Delivery days" className="flex min-w-0 flex-1 snap-x snap-mandatory gap-2 overflow-x-auto overscroll-x-contain pb-1 [scrollbar-width:none]">
        {weeks.map((w) => {
          const cur = w === week;
          return (
            <div
              key={w}
              data-week={w}
              aria-current={cur ? "true" : undefined}
              className={cn("w-full shrink-0 snap-start rounded-2xl border-[1.5px] p-2", !picker && "lg:w-[calc(50%-4px)]", cur ? "border-[var(--primary)] bg-[var(--muted)]/50" : "border-[var(--border)]")}
            >
              <div className="mb-1 flex items-center justify-between">
                <button type="button" onClick={() => onWeek(w)} className={cn(FOCUS, "min-h-8 px-1 text-xs font-semibold uppercase tracking-[0.15em] text-[var(--muted-foreground,#6E6558)] [touch-action:manipulation]")}>
                  {label(w)}{w === mondayOfToday(today) ? " · This week" : ""}
                </button>
                {cur && (
                  <span className={cn("flex", !picker && "lg:hidden")}>
                    <button type="button" aria-label="Previous week" disabled={week <= firstWeek} onClick={() => onWeek(addDays(week, -7))} className={cn(FOCUS, "grid size-9 place-items-center rounded-full disabled:opacity-30 [touch-action:manipulation]")}><ChevronLeft aria-hidden className="size-5" /></button>
                    <button type="button" aria-label="Next week" disabled={week >= lastWeek} onClick={() => onWeek(addDays(week, 7))} className={cn(FOCUS, "grid size-9 place-items-center rounded-full disabled:opacity-30 [touch-action:manipulation]")}><ChevronRight aria-hidden className="size-5" /></button>
                  </span>
                )}
              </div>
              <div className="grid grid-cols-7 gap-1">
                {weekDays(w).map((iso, i) => {
                  const ds = dots[iso] ?? [];
                  const sel = iso === selectedDay;
                  const off = picker?.isDisabled(iso) ?? false;
                  const text = `${d(iso).toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", timeZone: "UTC" })}${ds.length ? `, eating, ${ds.map((x) => STATUS_LABEL[x.status]).join(", ")}${ds.some((x) => x.truck) ? ", delivery arrives" : ""}` : ", nothing planned"}`;
                  return (
                    <button
                      key={iso}
                      type="button"
                      aria-label={picker ? `${text.replace(/, (eating|nothing planned).*$/, "")}${ds.some((x) => x.truck) ? ", delivery day" : ""}${off ? ", unavailable" : ""}` : text}
                      aria-pressed={sel}
                      aria-disabled={off || undefined}
                      data-day={iso}
                      onClick={() => (off ? picker?.onDisabledTap?.(iso) : onPickDay(iso))}
                      className={cn(FOCUS, "relative flex h-[76px] min-w-0 flex-col items-center justify-center gap-1 rounded-[14px] border-[1.5px] text-xs [touch-action:manipulation] motion-reduce:transition-none", sel ? "border-[var(--primary)] bg-[var(--primary-wash,#FBE3D2)] font-semibold text-[var(--foreground)]" : "border-transparent bg-[var(--card)]", (iso < today || off) && !sel && "opacity-40")}
                    >
                      <span aria-hidden className="grid w-full grid-cols-[1fr_auto_1fr] items-center px-1">
                        <span className="flex justify-end">{ds.length > 0 && <Utensils className="size-2.5 text-[var(--muted-foreground,#6E6558)]" />}</span>
                        <span className="px-1 opacity-80">{WD[i]}</span>
                        <span className="flex justify-start">{ds.some((x) => x.truck) && <Truck className="size-2.5 text-[var(--muted-foreground,#6E6558)]" />}</span>
                      </span>
                      <b aria-hidden className={cn("grid size-7 place-items-center rounded-full text-[16px] tabular-nums", iso === today && !sel && "border-2 border-[var(--primary)]")}>{d(iso).getUTCDate()}</b>
                      <span aria-hidden className="flex h-3 w-full items-center justify-center gap-0.5 px-1.5">
                        {!picker && ds.map((x, k) => <Dot key={k} status={x.status} />)}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
      {!picker && <button type="button" aria-label="Next week" disabled={week >= lastWeek} onClick={() => onWeek(addDays(week, 7))} className={cn(arrow, FOCUS)}><ChevronRight aria-hidden className="size-5" /></button>}
    </div>
  );
}

function mondayOfToday(today: string) {
  return addDays(today, -((d(today).getUTCDay() + 6) % 7));
}

"use client";

import { Skeleton } from "@/components/customer/kit";
import { cn } from "@/components/customer/kit/cn";
import { SectionCard } from "@/components/ds";
import { LottieEmptyState } from "@/components/motion";
import { formatMenuWeekRange } from "@/lib/format/datetime";
import { buildPosterColumns, type DayOfWeek } from "@/lib/menu/poster";
import type { menuService } from "@/lib/services/menu.service";

type Week = Awaited<ReturnType<typeof menuService.getPublishedWeek>>;

export function ThisWeekMenuSection({
  week,
  todayKey,
  scope = "this",
}: {
  week: Week;
  todayKey?: DayOfWeek;
  scope?: "this" | "next";
}) {
  const title = scope === "next" ? "Next week's menu" : "This week's menu";

  if (!week) {
    return (
      <SectionCard title={title}>
        <LottieEmptyState
          animation="empty-box"
          title="No menu released yet"
          body="When kitchen publishes a week, it shows up here."
        />
      </SectionCard>
    );
  }

  // Use the poster grouping: 6 columns (Mon-Fri, Weekends)
  const columns = buildPosterColumns(week.slots, week.items);

  // Split into left and right columns for the 2-column layout
  // Left: Mon (0), Wed (2), Fri (4)
  // Right: Tue (1), Thu (3), Weekends (5)
  const leftCol = [columns[0], columns[2], columns[4]].filter(Boolean);
  const rightCol = [columns[1], columns[3], columns[5]].filter(Boolean);

  return (
    <SectionCard title={title}>
      <div className="bg-card border-border relative overflow-hidden rounded-3xl border shadow-sm ring-1 ring-black/5">

        {/* Poster Header */}
        <div className="bg-primary/5 border-border flex flex-col items-center justify-center border-b p-6 text-center">
          <h2 className="text-primary text-xl font-bold tracking-tight uppercase">Tiffin Menu</h2>
          <p className="text-muted-foreground mt-1 text-sm font-medium">{formatMenuWeekRange(week.weekStart)}</p>
        </div>

        <div className="grid grid-cols-1 gap-x-12 gap-y-8 p-6 sm:grid-cols-2 sm:p-10">
          {/* Left Column */}
          <div className="space-y-8">
            {leftCol.map((col) => (
              <DayBlock key={col.label} col={col} />
            ))}
          </div>
          {/* Right Column */}
          <div className="space-y-8">
            {rightCol.map((col) => (
              <DayBlock key={col.label} col={col} />
            ))}
          </div>
        </div>
      </div>
    </SectionCard>
  );
}

function DayBlock({ col }: { col: any }) {
  return (
    <div className="flex flex-col items-center text-center">
      <div className="mb-4 flex w-full items-center gap-4">
        <div className="bg-primary/20 h-px flex-1" />
        <h3 className="text-primary text-sm font-bold tracking-widest uppercase">{col.label}</h3>
        <div className="bg-primary/20 h-px flex-1" />
      </div>

      {col.groups.length > 0 ? (
        <ul className="space-y-2.5">
          {col.groups.flatMap((g: any) => g.dishes).map((d: any, i: number) => (
            <li key={i}>
              <span className="text-foreground text-sm font-medium leading-relaxed">
                {d.name}
              </span>
            </li>
          ))}
        </ul>
      ) : (
        <p className="text-muted-foreground text-sm italic">Menu coming soon</p>
      )}
    </div>
  );
}

export function ThisWeekMenuSectionSkeleton() {
  return (
    <SectionCard title="This week's menu">
       <div className="bg-card border-border h-[600px] w-full rounded-3xl border" />
    </SectionCard>
  );
}

