"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useState, type ReactNode } from "react";
import { CalendarDays, LifeBuoy, LogOut, Menu as MenuIcon, Plus, RefreshCw, User, UtensilsCrossed } from "lucide-react";
import { useTheme } from "@foundry/themes";
import { signOut } from "@/lib/auth/client";
import { CoinChip, ListRow, MenuSection, NavPill, Segmented, Sheet, ThemeToggle } from "@/components/customer/kit";
import { cn, FONT, FOCUS } from "@/components/customer/kit/cn";

const ACCOUNT_PATHS = ["/me/account"];
const MENU_PATHS = ["/me/menu", "/me/renew", "/me/support"];
const under = (p: string, base: string) => p === base || p.startsWith(`${base}/`);

type Tab = "deliveries" | "menu" | "account";

function activeTab(p: string): Tab | null {
  if (MENU_PATHS.some((b) => under(p, b))) return "menu";
  if (ACCOUNT_PATHS.some((b) => under(p, b))) return "account";
  if (p === "/me" || under(p, "/me")) return "deliveries";
  return null;
}

const THEMES = [
  { id: "light", label: "Light" },
  { id: "system", label: "Auto" },
  { id: "dark", label: "Dark" },
];

/** Mark + wordmark. `compact` fits a 44px chrome bar (public subscribe and checkout). */
export function Brand({ href = "/me", compact = false }: { href?: string; compact?: boolean }) {
  return (
    <Link href={href} aria-label="TiffinGrab home" className={cn(FONT, FOCUS, "flex min-h-11 items-center gap-2 rounded-full")}>
      <span aria-hidden className={cn("grid place-items-center rounded-full bg-[var(--primary)] text-white", compact ? "size-8" : "size-9")}>
        <UtensilsCrossed className={compact ? "size-4" : "size-[18px]"} />
      </span>
      <span className={compact ? "text-[20px] leading-none font-bold tracking-[-0.03em]" : "c-title"}>
        Tiffin<em className="text-[var(--primary)]">Grab</em>
      </span>
    </Link>
  );
}

function MenuButton({ active, onClick, className, children }: { active: boolean; onClick: () => void; className: string; children: ReactNode }) {
  return (
    <button type="button" onClick={onClick} aria-haspopup="dialog" data-active={active || undefined} className={cn(FONT, FOCUS, "[touch-action:manipulation]", className)}>
      {children}
    </button>
  );
}

const tabCls = (on: boolean) =>
  cn("flex h-14 flex-1 flex-col items-center justify-center gap-0.5 text-[11px] font-semibold", on ? "text-[var(--primary)]" : "text-[var(--muted-foreground)]");

export function CustomerShell({ coinBalance, userPublicId, children }: { coinBalance: number; userPublicId: string; children: ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const { theme, setTheme } = useTheme();
  const tab = activeTab(pathname);

  useEffect(() => setOpen(false), [pathname]);

  useEffect(() => {
    const source = new EventSource(`/api/realtime?channel=${encodeURIComponent(`refresh:${userPublicId}`)}`);
    source.onmessage = () => {
      router.refresh();
    };
    return () => source.close();
  }, [userPublicId, router]);

  const menuPill = cn(
    "inline-flex h-11 items-center rounded-full px-4 text-sm font-semibold transition-colors",
    tab === "menu" ? "bg-[var(--primary-wash,#FBE3D2)] text-[#B5430B] dark:text-[#FFB877]" : "text-[var(--muted-foreground)] hover:bg-[var(--muted)]",
  );

  return (
    <div className={cn(FONT, "min-h-dvh bg-[var(--background)] text-[var(--foreground)]")}>
      <header className="c-glass sticky top-0 z-40 border-b border-[var(--border)] pt-[env(safe-area-inset-top)]">
        <div className="mx-auto grid h-16 max-w-[1280px] grid-cols-[1fr_auto] items-center gap-3 px-4 lg:grid-cols-[1fr_auto_1fr] lg:px-6">
          <Brand />
          <nav aria-label="Primary" className="hidden items-center gap-1 lg:flex">
            <NavPill href="/me" active={tab === "deliveries"}>Deliveries</NavPill>
            <MenuButton active={tab === "menu"} onClick={() => setOpen(true)} className={menuPill}>Menu</MenuButton>
            <NavPill href="/me/account" active={tab === "account"}>Account</NavPill>
          </nav>
          <div className="flex items-center justify-end gap-2">
            <CoinChip href="/me/wallet" balance={coinBalance} active={under(pathname, "/me/wallet")} />
            <ThemeToggle />
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1280px] px-4 pb-[calc(6rem+env(safe-area-inset-bottom))] pt-4 lg:px-6 lg:pb-10 lg:pt-6">{children}</main>

      <nav aria-label="Primary" className="c-glass fixed inset-x-0 bottom-0 z-40 border-t border-[var(--border)] pb-[env(safe-area-inset-bottom)] lg:hidden">
        <div className="relative mx-auto flex max-w-md items-stretch">
          <Link href="/me" aria-current={tab === "deliveries" ? "page" : undefined} className={cn(FOCUS, tabCls(tab === "deliveries"))}>
            <CalendarDays aria-hidden className="size-6" />Deliveries
          </Link>
          <MenuButton active={tab === "menu"} onClick={() => setOpen(true)} className={tabCls(tab === "menu")}>
            <MenuIcon aria-hidden className="size-6" />Menu
          </MenuButton>
          <Link href="/me/account" aria-current={tab === "account" ? "page" : undefined} className={cn(FOCUS, tabCls(tab === "account"))}>
            <User aria-hidden className="size-6" />Account
          </Link>
        </div>
      </nav>

      <Sheet open={open} onClose={() => setOpen(false)} title="Menu">
        <MenuSection title="Meals">
          <ListRow href="/subscribe" icon={<Plus className="size-[18px]" />} label="New order" sublabel="Start another plan" />
          <ListRow href="/me/menu" icon={<UtensilsCrossed className="size-[18px]" />} label="Weekly menu" sublabel="What is being served" />
          <ListRow href="/me/renew" icon={<RefreshCw className="size-[18px]" />} label="Renew plan" sublabel="Keep your meals coming" />
        </MenuSection>
        <MenuSection title="Appearance">
          <Segmented label="Theme" idPrefix="menu-theme" items={THEMES} value={theme ?? "system"} onChange={(t) => setTheme(t as "light" | "dark" | "system")} className="[&>button]:flex-1" />
        </MenuSection>
        <MenuSection title="Help">
          <ListRow href="/me/support" icon={<LifeBuoy className="size-[18px]" />} label="Support" sublabel="Ask us anything" />
        </MenuSection>
        <div className="py-2">
          <button
            type="button"
            onClick={async () => {
              await signOut();
              router.push("/login");
            }}
            className={cn(FOCUS, "flex min-h-14 w-full items-center gap-3 rounded-2xl px-4 text-left text-[15px] font-semibold [touch-action:manipulation] active:bg-[var(--muted)]")}
          >
            <span aria-hidden className="grid size-9 place-items-center rounded-xl bg-[var(--muted)]"><LogOut className="size-[18px]" /></span>
            Sign out
          </button>
        </div>
      </Sheet>
    </div>
  );
}

"use client";

import { Send } from "lucide-react";
import { usePresence, useTyping } from "@foundry/realtime/client";
import { Button, Notice, Pill, Skeleton, Textarea } from "@/components/customer/kit";
import { cn, FONT } from "@/components/customer/kit/cn";
import { ChatMessageList, useMessageComposer, type ChatMessage, type ChatUi } from "@foundry/design-system";
import { categoryLabel, subcategoryLabel } from "@/lib/support/ticket-taxonomy";
import { formatEpoch } from "@/lib/format/datetime";
import type { TicketStatus } from "@/lib/services/tickets.service";
import { replyTicket } from "@/app/(customer)/me/support/actions";
import { MAX_FILES, PhotoPicker, STATUS_LABEL, STATUS_TONE } from "./parts";

type ThreadTicket = {
  publicId: string;
  status: string;
  category: string;
  subcategory?: string | null;
  createdAt: number;
  subject?: string;
};

type ThreadMessage = {
  publicId: string;
  authorType: string;
  body: string;
  createdAt: number;
  attachments?: { thumbUrl: string; name: string; href: string }[] | null;
};

export function TicketThread({ ticket, messages, timezone }: { ticket: ThreadTicket; messages: ThreadMessage[]; timezone: string }) {
  const status = ticket.status as TicketStatus;
  const closed = status === "resolved" || status === "closed";
  const channel = `ticket:${ticket.publicId}`;
  const supportOnline = usePresence(channel, "staff");
  const fmt = (t: number) => formatEpoch(t, { timeZone: timezone, mode: "datetime", locale: "en-CA" });
  const sub = subcategoryLabel(ticket.category, ticket.subcategory ?? null);

  return (
    <div className={cn(FONT, "space-y-5")}>
      <div className="flex flex-wrap items-center gap-2">
        <Pill tone={STATUS_TONE[status]}>{STATUS_LABEL[status]}</Pill>
        <Pill>{categoryLabel(ticket.category)}</Pill>
        {sub ? <Pill>{sub}</Pill> : null}
        <span className="text-[13px] text-[var(--muted-foreground,#6E6558)]">Opened {fmt(ticket.createdAt)}</span>
        <span aria-live="polite" className="inline-flex items-center gap-1.5 text-[13px] text-[var(--muted-foreground,#6E6558)]">
          <span aria-hidden className={cn("size-2 rounded-full", supportOnline ? "bg-[var(--s-delivered-fg)]" : "bg-[var(--border)]")} />
          Support {supportOnline ? "online" : "offline"}
        </span>
      </div>

      <ChatMessageList
        className="space-y-3 pb-2"
        ui={kitChatUi}
        messages={messages.map((m): ChatMessage => ({
          id: m.publicId,
          kind: m.authorType === "system" ? "system" : m.authorType === "customer" ? "mine" : "theirs",
          body: m.body,
          meta: m.authorType === "system" ? fmt(m.createdAt) : `${m.authorType === "customer" ? "You" : "Support"} · ${fmt(m.createdAt)}`,
          attachments: m.attachments,
        }))}
      />

      <div className="c-glass sticky bottom-[calc(5rem+env(safe-area-inset-bottom))] z-10 -mx-4 border-t border-[var(--border)] px-4 py-3 lg:static lg:mx-0 lg:border-0 lg:bg-transparent lg:p-0">
        <Composer ticketId={ticket.publicId} closed={closed} channel={channel} />
      </div>
    </div>
  );
}

function Composer({ ticketId, closed, channel }: { ticketId: string; closed: boolean; channel: string }) {
  const c = useMessageComposer({ action: (form) => replyTicket(ticketId, form), channel, peerRole: "staff" });

  if (closed) {
    return <p className="rounded-2xl border border-dashed border-[var(--border)] p-4 text-[15px] text-[var(--muted-foreground,#6E6558)]">This ticket is closed. Staff can reopen it to continue the conversation.</p>;
  }

  return (
    <form
      className="space-y-3"
      onSubmit={(e) => {
        e.preventDefault();
        c.submit();
      }}
    >
      {c.peerTyping ? <p className="text-[13px] text-[var(--muted-foreground,#6E6558)]">Support is typing…</p> : null}
      <Textarea label="Reply" rows={3} placeholder="Write a reply…" value={c.body} onChange={(e) => c.onBodyChange(e.target.value)} />
      <PhotoPicker files={c.files} inputRef={c.inputRef} onAdd={c.addFiles} onRemove={c.removeFile} disabled={c.pending} label={`Attach (up to ${MAX_FILES})`} />
      {c.error ? <Notice tone="error">{c.error}</Notice> : null}
      <Button type="submit" variant="primary" size="lg" pending={c.pending} className="w-full sm:w-auto">
        <Send aria-hidden className="size-4" />
        {c.pending ? "Sending…" : "Send reply"}
      </Button>
    </form>
  );
}

const kitChatUi: Partial<ChatUi> = {
  System: ({ message: m }) => (
    <p className="text-center text-[13px] text-[var(--muted-foreground,#6E6558)]">
      {m.body} · {m.meta}
    </p>
  ),
  Bubble: ({ message: m, mine }) => (
    <div className={cn("flex flex-col gap-1", mine ? "items-end" : "items-start")}>
      <div
        className={cn(
          "max-w-[88%] rounded-[20px] px-4 py-2.5 text-[15px] leading-snug sm:max-w-[75%]",
          mine ? "rounded-br-md bg-[var(--primary)] text-[var(--primary-foreground,#fff)]" : "rounded-bl-md border border-[var(--border)] bg-[var(--card)]",
        )}
      >
        <p className="whitespace-pre-wrap text-pretty">{m.body}</p>
        {m.attachments?.length ? (
          <div className="mt-2 flex flex-wrap gap-2">
            {m.attachments.map((a, i) => (
              <a key={i} href={a.href} target="_blank" rel="noreferrer" aria-label={`Open ${a.name}`}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={a.thumbUrl} alt={a.name} className="size-24 rounded-xl object-cover" />
              </a>
            ))}
          </div>
        ) : null}
      </div>
      <span className="px-1 text-[12px] text-[var(--muted-foreground,#6E6558)]">{m.meta}</span>
    </div>
  ),
};

export function TicketThreadSkeleton() {
  return (
    <div className="space-y-4" aria-hidden>
      <div className="flex gap-2">
        <Skeleton className="h-7 w-16 rounded-full" />
        <Skeleton className="h-7 w-20 rounded-full" />
      </div>
      {[false, true, false].map((mine, i) => (
        <div key={i} className={cn("flex", mine && "justify-end")}>
          <Skeleton className="h-12 w-56" />
        </div>
      ))}
      <Skeleton className="h-24 w-full" />
    </div>
  );
}

