    methodLabel: "Interac e-Transfer",
    requireProof: false,
    payeeHandle: "pay@tiffingrab.com",
    instructions: "Send transfer with reference",
    referenceHint: "REF-1234",
    deploymentId: "dep_1",
    methodId: "interac",
    rejectNote: null,
  };

  afterEach(() => {
    cleanup();
    vi.clearAllMocks();
  });

  it("submits payment successfully with valid reference and screenshot", async () => {
    mockClaimPaymentAction.mockResolvedValueOnce({ ok: true });
    const onDone = vi.fn();

    render(<ClaimPayment ctx={baseCtx} currency="CAD" onDone={onDone} />);

    const refInput = screen.getByPlaceholderText("Interac confirmation / reference #");
    fireEvent.change(refInput, { target: { value: "REF999" } });

    const file = new File(["dummy content"], "screenshot.png", { type: "image/png" });
    const fileInput = document.querySelector('input[type="file"]') as HTMLInputElement;
    fireEvent.change(fileInput, { target: { files: [file] } });

    const submitBtn = screen.getByRole("button", { name: "I've sent the payment" });
    fireEvent.click(submitBtn);

    await waitFor(() => {
      expect(mockClaimPaymentAction).toHaveBeenCalledWith("pay_123", expect.any(FormData));
      expect(mockToast).toHaveBeenCalledWith("Payment submitted — we'll confirm it shortly");
      expect(onDone).toHaveBeenCalled();
      expect(mockRefresh).toHaveBeenCalled();
    });
  });

  it("rejects invalid file types and displays a clear message without throwing", async () => {
    render(<ClaimPayment ctx={baseCtx} currency="CAD" />);

    const badFile = new File(["fake pdf"], "invoice.pdf", { type: "application/pdf" });
    const fileInput = document.querySelector('input[type="file"]') as HTMLInputElement;
    fireEvent.change(fileInput, { target: { files: [badFile] } });

    await waitFor(() => {
      expect(screen.getByText("Only PNG, JPEG, WebP or GIF images are allowed")).toBeInTheDocument();
    });
  });

  it("rejects files larger than 5 MB without throwing", async () => {
    render(<ClaimPayment ctx={baseCtx} currency="CAD" />);

    const bigFile = new File(["x".repeat(100)], "huge.png", { type: "image/png" });
    Object.defineProperty(bigFile, "size", { value: 6 * 1024 * 1024 });

    const fileInput = document.querySelector('input[type="file"]') as HTMLInputElement;
    fireEvent.change(fileInput, { target: { files: [bigFile] } });

    await waitFor(() => {
      expect(screen.getByText("Screenshot must be 5 MB or smaller")).toBeInTheDocument();
    });
  });

  it("sanitizes Minified React error #441 if returned from server action", async () => {
    mockClaimPaymentAction.mockResolvedValueOnce({
      error: "Minified React error #441; visit https://reactjs.org/docs/error-decoder.html?invariant=441",
    });

    render(<ClaimPayment ctx={baseCtx} currency="CAD" />);

    const refInput = screen.getByPlaceholderText("Interac confirmation / reference #");
    fireEvent.change(refInput, { target: { value: "REF999" } });

    const submitBtn = screen.getByRole("button", { name: "I've sent the payment" });
    fireEvent.click(submitBtn);

    await waitFor(() => {
      // Must NOT display Minified React error #441 anywhere in the DOM
      expect(screen.queryByText(/Minified React error/)).not.toBeInTheDocument();
      expect(screen.queryByText(/invariant=441/)).not.toBeInTheDocument();
      // Must display clean friendly error
      expect(screen.getByText("Something went wrong. Please try again.")).toBeInTheDocument();
    });
  });

  it("sanitizes unhandled thrown error / #441 in the catch block", async () => {
    mockClaimPaymentAction.mockRejectedValueOnce(
      new Error("Minified React error #441; visit https://reactjs.org/docs/error-decoder.html?invariant=441"),
    );

    render(<ClaimPayment ctx={baseCtx} currency="CAD" />);

    const refInput = screen.getByPlaceholderText("Interac confirmation / reference #");
    fireEvent.change(refInput, { target: { value: "REF999" } });

    const submitBtn = screen.getByRole("button", { name: "I've sent the payment" });
    fireEvent.click(submitBtn);

    await waitFor(() => {
      // Must NOT display Minified React error #441
      expect(screen.queryByText(/Minified React error/)).not.toBeInTheDocument();
      // Must display custom fallback
      expect(screen.getByText("Could not submit payment. Please try again.")).toBeInTheDocument();
    });
  });

  it("displays normal validation error from server safely", async () => {
    mockClaimPaymentAction.mockResolvedValueOnce({
      error: "Payment reference has already been used",
    });

    render(<ClaimPayment ctx={baseCtx} currency="CAD" />);

    const refInput = screen.getByPlaceholderText("Interac confirmation / reference #");
    fireEvent.change(refInput, { target: { value: "REF111" } });

    const submitBtn = screen.getByRole("button", { name: "I've sent the payment" });
    fireEvent.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText("Payment reference has already been used")).toBeInTheDocument();
    });
  });
});

"use client";

import * as React from "react";
import {
  BarChart3Icon,
  BellIcon,
  Building2Icon,
  CalendarIcon,
  CheckIcon,
  ClipboardListIcon,
  CoinsIcon,
  CopyIcon,
  LayoutDashboardIcon,
  LifeBuoyIcon,
  LockIcon,
  LogOutIcon,
  TruckIcon,
  WalletCardsIcon,
  type LucideIcon,
  PackageIcon,
  PaletteIcon,
  SettingsIcon,
  TagIcon,
  TicketPercentIcon,
  UserIcon,
  UsersIcon,
  UtensilsCrossedIcon,
} from "lucide-react";
import { signOut } from "@/lib/auth/client";
import { lockSession } from "@/lib/auth/lock-actions";
import { markAllReadAction } from "@/lib/services/section-seen.actions";
import type { Section } from "@/lib/services/section-seen.service";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { cn } from "@foundry/ui/cn";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
} from "@foundry/ui/sidebar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@foundry/ui/dropdown-menu";
import { Avatar, AvatarFallback, AvatarImage } from "@foundry/ui/avatar";

export type NavItem = { title: string; href: string; icon: LucideIcon; roles: string[] };
export type NavSection = { label: string; items: NavItem[] };

const SECTION_BY_HREF: Record<string, Section> = {
  "/dashboard/tickets": "tickets",
  "/dashboard/inquiries": "inquiries",
  "/dashboard/customers": "customers",
  "/dashboard/payments": "payments",
};

// Grouped navigation. A section renders only when the current user's role
// matches at least one of its items. Exported so the command palette reuses it.
export const SECTIONS: NavSection[] = [
  {
    label: "Operations",
    items: [
      { title: "Overview", href: "/dashboard", icon: LayoutDashboardIcon, roles: ["admin", "member"] },
      { title: "Analytics", href: "/dashboard/analytics", icon: BarChart3Icon, roles: ["admin"] },
      { title: "Inquiries", href: "/dashboard/inquiries", icon: ClipboardListIcon, roles: ["admin", "member"] },
      { title: "Orders", href: "/dashboard/orders", icon: PackageIcon, roles: ["admin", "member"] },
      { title: "Daily labels", href: "/dashboard/labels", icon: TagIcon, roles: ["admin", "member"] },
      { title: "Dispatch", href: "/dashboard/dispatch", icon: TruckIcon, roles: ["admin", "member"] },
      { title: "Customers", href: "/dashboard/customers", icon: UsersIcon, roles: ["admin", "member"] },
      { title: "Tickets", href: "/dashboard/tickets", icon: LifeBuoyIcon, roles: ["admin", "member"] },
    ],
  },
  {
    label: "Catalog",
    items: [
      { title: "Catalog", href: "/dashboard/catalog", icon: UtensilsCrossedIcon, roles: ["admin"] },
      { title: "Weekly Menus", href: "/dashboard/menus", icon: CalendarIcon, roles: ["admin"] },
    ],
  },
  {
    label: "Finance",
    items: [
      { title: "Payments", href: "/dashboard/payments", icon: WalletCardsIcon, roles: ["admin"] },
      { title: "Wallet", href: "/dashboard/wallet", icon: CoinsIcon, roles: ["admin"] },
      { title: "Discounts", href: "/dashboard/discounts", icon: TicketPercentIcon, roles: ["admin"] },
    ],
  },
  {
    label: "Engagement",
    items: [
      { title: "Notifications", href: "/dashboard/notifications", icon: BellIcon, roles: ["admin"] },
    ],
  },
  {
    label: "Administration",
    items: [
      { title: "Organization", href: "/dashboard/organization", icon: Building2Icon, roles: ["admin"] },
      { title: "Settings", href: "/dashboard/settings", icon: SettingsIcon, roles: ["admin"] },
      { title: "Design system", href: "/dashboard/design", icon: PaletteIcon, roles: ["admin"] },
    ],
  },
  {
    label: "Personal",
    items: [
      { title: "My meals", href: "/dashboard/meals", icon: UtensilsCrossedIcon, roles: ["user"] },
      { title: "Support", href: "/me/support", icon: LifeBuoyIcon, roles: ["user"] },
      { title: "Account", href: "/dashboard/account", icon: UserIcon, roles: ["admin", "member", "user"] },
    ],
