"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { Invoice } from "./invoice";
import { PlanSummary } from "./plan-summary";
import type { ClientCatalogSnapshot } from "@/lib/catalog/types";
import type { PricingResult } from "@/lib/pricing";
import { reprice } from "@/app/(public)/subscribe/actions";
import { BottomBar, Button, Sheet } from "@/components/customer/kit";
import { initialSelections, nextBlockedReason, WIZARD_ORIGIN_KEY, WIZARD_STEP_KEY, WIZARD_STORAGE_KEY, type WizardOrigin, type WizardSelections } from "./selections";
import { StepBaseline } from "./steps/step-baseline";
import { StepBundle } from "./steps/step-bundle";
import { StepSchedule } from "./steps/step-schedule";
import { StepDuration } from "./steps/step-duration";
import { BestDeal } from "./best-deal";
import { SubscribeChrome } from "./subscribe-chrome";
import { anySameIsoWeek } from "./same-iso-week";
import type { CurrentPlanSummary } from "./current-plan-hint";

const STEPS = ["Baseline", "Bundle", "Schedule", "Start"] as const;
const QUESTIONS = ["What's your baseline?", "Pick your bundle.", "Set your schedule.", "Start date & commitment."] as const;

export function Wizard({
  catalog,
  closeHref,
  existingStartDates = [],
  currentPlan = null,
  origin = "subscribe",
  initial = initialSelections,
  minStartDate = null,
  exitHref,
}: {
  catalog: ClientCatalogSnapshot;
  closeHref: string;
  existingStartDates?: string[];
  currentPlan?: CurrentPlanSummary | null;
  origin?: WizardOrigin;
  initial?: WizardSelections;
  /** First date a new/renewed plan may start (overlap with a live plan). */
  minStartDate?: string | null;
  exitHref?: string;
}) {
  const router = useRouter();
  const [step, setStepState] = useState(0);
  const setStep = (n: number | ((s: number) => number)) =>
    setStepState((s) => {
      const next = typeof n === "function" ? n(s) : n;
      try { sessionStorage.setItem(WIZARD_STEP_KEY, String(next)); } catch { /* storage unavailable */ }
      return next;
    });
  const [selections, setSelections] = useState<WizardSelections>(initial);
  const [result, setResult] = useState<PricingResult | null>(null);
  const prevStep = useRef(0);
  const direction = step >= prevStep.current ? "forward" : "back";
  useEffect(() => {
    if (prevStep.current !== step) window.scrollTo({ top: 0 });
    prevStep.current = step;
  }, [step]);

  // "Edit plan" from checkout lands here again: restore what the customer had picked and the step they were on.
  useEffect(() => {
    try {
      if (sessionStorage.getItem(WIZARD_ORIGIN_KEY) !== origin) return;
      const raw = sessionStorage.getItem(WIZARD_STORAGE_KEY);
      if (!raw) return;
      const saved = JSON.parse(raw) as WizardSelections;
      if (saved.planKey != null && !catalog.plans.some((p) => p.key === saved.planKey)) return;
      const savedStep = Number(sessionStorage.getItem(WIZARD_STEP_KEY));
      /* eslint-disable react-hooks/set-state-in-effect */
      setSelections({ ...initial, ...saved });
      if (Number.isInteger(savedStep) && savedStep >= 0 && savedStep < STEPS.length) {
        prevStep.current = savedStep;
        setStepState(savedStep);
      }
      /* eslint-enable react-hooks/set-state-in-effect */
    } catch { /* unreadable saved plan: start fresh */ }
    // Mount-only restore.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const set = (patch: Partial<WizardSelections>) => setSelections((s) => ({ ...s, ...patch }));

  useEffect(() => {
    // Clearing the stale invoice when no meal is chosen; intentional effect-driven reset.

    // No frequency until the Schedule step: pricing would throw "Invalid frequency" (a 500) on every Bundle pick.
    if (!selections.mealSizeId || !selections.frequencyKey) { setResult(null); return; }
    let active = true;
    reprice(selections, undefined, selections.planKey ?? undefined)
      .then((r) => { if (active) setResult(r.pricing); })
      .catch(() => { if (active) setResult(null); });
    return () => { active = false; };
  }, [selections]);

  const blocked = nextBlockedReason(step, catalog, selections);
  const canNext = blocked === null;

  const deploy = () => {
    sessionStorage.setItem(WIZARD_STORAGE_KEY, JSON.stringify(selections));
    sessionStorage.setItem(WIZARD_ORIGIN_KEY, origin);
    router.push("/checkout");
  };

  const sameWeekConflict =
    selections.startDate !== "" && anySameIsoWeek(selections.startDate, existingStartDates);

  const goBack = () => {
    if (step > 0) {
      setStep((s) => s - 1);
      return;
    }
    if (exitHref) router.push(exitHref);
    else router.back();
  };

  const [invoiceOpen, setInvoiceOpen] = useState(false);
  const reduce = useReducedMotion();
  const slide = reduce ? 0 : 24;
  const sign = direction === "forward" ? 1 : -1;
  const spring = reduce ? { duration: 0.15 } : { type: "spring" as const, bounce: 0, duration: 0.4 };

  return (
    <div className="pb-44 sm:pb-6">
      <SubscribeChrome closeHref={closeHref} onBack={goBack} stepTag={STEPS[step]}
        trailing={result ? (
          <button
            type="button"
            aria-haspopup="dialog"
            aria-expanded={invoiceOpen}
            aria-label={`Price summary: ${result.tiffinCount} tiffins, $${result.total.toFixed(2)} total`}
            onClick={() => setInvoiceOpen(true)}
            className="bg-primary/15 text-foreground focus-visible:ring-ring flex h-11 items-center gap-1.5 rounded-full px-3.5 text-[13px] font-semibold tabular-nums transition-transform duration-100 outline-none focus-visible:ring-2 active:scale-[0.97] motion-reduce:active:scale-100"
          >
            <span className="text-muted-foreground">{result.tiffinCount}<span> {result.tiffinCount === 1 ? "tiffin" : "tiffins"}</span></span>
            <span className="min-w-[4.5ch] text-right text-[15px]">${result.total.toFixed(2)}</span>
          </button>
        ) : null}
      />

      <nav aria-label="Progress" className="mb-6">
        <ol className="grid grid-cols-4 gap-1.5">
          {STEPS.map((name, i) => (
            <li key={name} aria-current={i === step ? "step" : undefined}>
              <span className={`block h-1 rounded-full transition-colors duration-300 ${i <= step ? "bg-primary" : "bg-border"}`} />
              <span className={`mt-1.5 block truncate text-xs font-semibold ${i === step ? "text-foreground" : "text-muted-foreground"}`}>{name}</span>
            </li>
          ))}
        </ol>
      </nav>

      {step >= 1 && step <= 3 && <BestDeal key={step} vary={step === 1 ? "bundle" : step === 2 ? "frequency" : "duration"} catalog={catalog} selections={selections} set={set} />}

      <AnimatePresence mode="popLayout" initial={false} custom={sign}>
        <motion.div
          key={step}
          custom={sign}
          initial={{ opacity: 0, x: slide * sign }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -slide * sign }}
          transition={spring}
        >
          <h2 className="mb-6 text-[34px] leading-[1.06] font-bold tracking-[-0.03em] text-balance sm:text-[40px]">{QUESTIONS[step]}</h2>

          {step === 0 && <StepBaseline catalog={catalog} selections={selections} set={set} currentPlan={currentPlan} />}
          {step === 1 && <StepBundle catalog={catalog} selections={selections} set={set} currentPlan={currentPlan} />}
          {step === 2 && <StepSchedule catalog={catalog} selections={selections} set={set} currentPlan={currentPlan} />}
          {step === 3 && (
            <StepDuration
              catalog={catalog}
              selections={selections}
              set={set}
              result={result}
              sameWeekConflict={sameWeekConflict}
              currentPlan={currentPlan}
              minStartDate={minStartDate}
            />
          )}
        </motion.div>
      </AnimatePresence>

      <Sheet bottom open={invoiceOpen && result != null} onClose={() => setInvoiceOpen(false)} title="Price summary">
        {result && (
          <div className="space-y-3 pb-3">
            <PlanSummary
              baseline={catalog.plans.find((p) => p.key === selections.planKey)?.name}
              mealName={catalog.mealSizes.find((m) => m.publicId === selections.mealSizeId)?.name}
              deliveryName={catalog.frequencies.find((f) => f.key === selections.frequencyKey)?.name}
              eatingDays={selections.eatingDays ?? []}
              weeks={selections.durationWeeks}
              startDate={selections.startDate}
              tiffinCount={result.tiffinCount}
            />
            <Invoice result={result} />
          </div>
        )}
      </Sheet>

      <BottomBar alignEnd note={blocked ?? undefined} className="sm:sticky sm:mt-6 sm:px-0">
        <Button variant="quiet" size="lg" className="w-24 shrink-0 sm:hidden" onClick={goBack}>Back</Button>
        {step < 3 ? (
          <Button variant="primary" size="lg" className="flex-1 sm:min-h-10 sm:flex-none sm:px-8" disabled={!canNext} onClick={() => setStep((s) => s + 1)}>Next</Button>
        ) : (
          <Button variant="primary" size="lg" className="flex-1 sm:min-h-10 sm:flex-none sm:px-8" disabled={!canNext} onClick={deploy}>
            Continue to checkout
          </Button>
        )}
      </BottomBar>
    </div>
  );
}

import { and, eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { db } from "@/db/client";
import { dishCategories } from "@/db/schema";
import { attachAllCategoriesToPlans, testPlanId } from "@/db/test-helpers";
import { dishes, mealSizeItems, mealSizes, plans } from "@/db/schema/catalog";
import { orders } from "@/db/schema/orders";
import { loadCatalogSnapshot } from "@/lib/catalog/load";

const TEST_DEPLOYMENT_ID = "SUB-SCHEMA-CATCOUNTS";

async function cleanup() {
  await db.delete(orders).where(eq(orders.deploymentId, TEST_DEPLOYMENT_ID));
}

// Sibling live-DB suites truncate `dishes`/`dish_categories` and vitest's
// sequencer order is not stable (fileParallelism is off but the cache reorders
// runs), so the ambient seed may be gone by the time this suite runs. Re-assert
// the exact seed rows these tests inspect, idempotently, so the checks verify the
// category delta rather than another suite's cleanup timing.
async function ensureSeedRows() {
  await db
    .insert(dishCategories)
    .values(
      [
        { key: "daal", label: "Daal", sortOrder: 6 },
        { key: "curry", label: "Curry", sortOrder: 7, selectable: true },
        { key: "extra", label: "Extra", sortOrder: 8 },
      ].map((c) => ({ planType: "tiffin" as const, enabled: true, selectable: false, ...c })),
    )
    .onConflictDoNothing();
  await attachAllCategoriesToPlans();
  const planId = await testPlanId();
  await db
    .insert(dishes)
    .values([
      { publicId: "dsh_dal_tadka", name: "Dal Tadka", category: "daal", planId },
      { publicId: "dsh_paneer_butter_masala", name: "Paneer Butter Masala", category: "curry", planId },
      { publicId: "dsh_aloo_gobi", name: "Aloo Gobi", category: "sabzi", planId },
      { publicId: "dsh_chicken_curry", name: "Chicken Curry", category: "curry", planId },
      { publicId: "dsh_egg_bhurji", name: "Egg Bhurji", category: "extra", planId },
    ])
    .onConflictDoNothing();
}

describe("schema: meal-size ↔ category delta (Task 1)", () => {
  beforeAll(ensureSeedRows);
  afterAll(cleanup);

  it("orders.categoryCounts defaults to an empty object", async () => {
    await cleanup();
    const snap = await loadCatalogSnapshot();
    const [o] = await db
      .insert(orders)
      .values({
        planId: snap.plans[0].id,
        mealSizeId: snap.mealSizes[0].id,
        frequencyId: snap.frequencies[0].id,
        persons: 1,
        durationWeeks: 1,
        startDate: "2999-01-01",
        tiffinCount: 5,
        perTiffinPrice: "10.00",
        pricingSnapshot: {},
        total: "50.00",
        deploymentId: TEST_DEPLOYMENT_ID,
        fullName: "T",
        addressLine: "1",
        city: "Toronto",
        postalCode: "M5V 2T6",
      })
      .returning();
    expect(o.categoryCounts).toEqual({});
  });

  it("every seeded meal_size_items row has a non-empty category", async () => {
    const rows = await db.select({ category: mealSizeItems.category }).from(mealSizeItems);
    expect(rows.length).toBeGreaterThan(0);
    for (const r of rows) {
      expect(typeof r.category).toBe("string");
      expect(r.category.length).toBeGreaterThan(0);
    }
  });

  it("dish_categories contains daal, curry, extra for tiffin", async () => {
    for (const key of ["daal", "curry", "extra"]) {
      const [row] = await db
        .select({ key: dishCategories.key })
        .from(dishCategories)
        .where(eq(dishCategories.key, key));
      expect(row, `dish_categories ${key}`).toBeDefined();
    }
  });

  it("every seeded dishes row has a category", async () => {
    const rows = await db.select({ category: dishes.category }).from(dishes);
    expect(rows.length).toBeGreaterThan(0);
    for (const r of rows) {
      expect(r.category, "dish category").toBeTruthy();
    }
  });

  it("every seeded meal_sizes row is scoped to a tiffin plan via plan_id", async () => {
    const rows = await db
      .select({ planType: plans.planType })
      .from(mealSizes)
      .innerJoin(plans, eq(mealSizes.planId, plans.id));
    expect(rows.length).toBe(17);
    for (const r of rows) {
      expect(r.planType).toBe("tiffin");
    }
  });
});

import { describe, expect, it } from "vitest";
import { actionAvailability, buildDayStatusMap, buildTrips, type CalendarDayInput, type PlanContext, type TripAction } from "../index";

// Mon 2026-09-21 12:00 America/Toronto (EDT, UTC-4)
const NOW = Date.UTC(2026, 8, 21, 16, 0);
const plan: PlanContext = { cutoffHour: 18, timezone: "America/Toronto", lastDeliveryDate: "2026-10-02", deliveryWeekdays: ["mon", "wed", "fri"] };

const day = (o: Partial<CalendarDayInput> & { date: string }): CalendarDayInput => ({
  status: "scheduled", locked: false, isMakeup: false, menuWeekId: null, meal: null, options: [], ...o,
});
const one = (o: Partial<CalendarDayInput> & { date: string }, p: PlanContext = plan, now = NOW) => buildTrips([day(o)], now, p)[0]!;
const ACTIONS: TripAction[] = ["pick", "swap", "move", "address"];
const CLOSED = "Changes closed Tue 6:00 pm. This trip is being prepared.";

describe("buildTrips status", () => {
  const rows: [string, Partial<CalendarDayInput> & { date: string }, string][] = [
    ["future scheduled", { date: "2026-09-23" }, "upcoming"],
    ["cutoff passed, delivery day not reached", { date: "2026-09-22", locked: true }, "cutoff-passed"],
    ["cutoff passed via clock only", { date: "2026-09-22", cutoffAt: NOW - 1 }, "cutoff-passed"],
    ["delivered today", { date: "2026-09-21", locked: true }, "delivered"],
    ["skipped (a failed drop; nobody holds days)", { date: "2026-09-25", status: "skipped" }, "failed"],
    ["skipped, rescheduled", { date: "2026-09-25", status: "skipped", rescheduled: true }, "rescheduled"],
    ["paused", { date: "2026-09-25", status: "paused" }, "vacation"],
    ["skipped past cutoff stays failed, so it can still move", { date: "2026-09-22", status: "skipped", locked: true }, "failed"],
    ["merged source", { date: "2026-09-25", status: "skipped", combinedInto: "2026-09-28" }, "combined-into"],
    ["make-up stays upcoming", { date: "2026-09-25", isMakeup: true }, "upcoming"],
  ];
  it.each(rows)("%s", (_n, d, status) => expect(one(d).status).toBe(status));

  it("cutoff is 18:00 the day before, in the plan timezone", () => {
    expect(one({ date: "2026-09-23" }).cutoffAt).toBe(Date.UTC(2026, 8, 22, 22, 0));
    expect(one({ date: "2026-11-02" }).cutoffAt).toBe(Date.UTC(2026, 10, 1, 23, 0)); // EST after DST ends
  });
  it("snapshotted cutoffAt wins over derivation", () => {
    expect(one({ date: "2026-09-23", cutoffAt: 123 }).cutoffAt).toBe(123);
  });
  it("2026-09-22 22:00Z is exactly the cutoff instant: locked at, open 1ms before", () => {
    const at = Date.UTC(2026, 8, 22, 22, 0);
    expect(one({ date: "2026-09-23" }, plan, at - 1).status).toBe("upcoming");
    expect(one({ date: "2026-09-23" }, plan, at).status).toBe("cutoff-passed");
  });
  it("delivery day is judged in plan tz, not UTC", () => {
    // 2026-09-23 01:00Z is still Tue 21:00 Toronto
    expect(one({ date: "2026-09-23", locked: true }, plan, Date.UTC(2026, 8, 23, 1, 0)).status).toBe("cutoff-passed");
    expect(one({ date: "2026-09-23", locked: true }, plan, Date.UTC(2026, 8, 23, 5, 0)).status).toBe("delivered");
  });
  it("units default to 1, coversDates and eating days from covers", () => {
    const t = one({ date: "2026-09-25", units: 3, covers: ["2026-09-25", "2026-09-26", "2026-09-27"], appliedSwaps: { "2026-09-26": [{ label: "1 Rice → 4 Roti" }] }, mealsByDate: { "2026-09-25": [{ label: "Curry", picks: [{ name: "Aloo Gobi" }], quantity: 1 }] } });
    expect(t.units).toBe(3);
    expect(t.coversDates).toHaveLength(3);
    expect(t.eatingDays.map((e) => e.date)).toEqual(t.coversDates);
    expect(t.eatingDays[0]!.dishSummary).toBe("Aloo Gobi");
    expect(t.eatingDays[1]!.dishSummary).toBeNull();
    expect(t.eatingDays[1]!.swaps).toEqual(["1 Rice → 4 Roti"]);
    expect(t.eatingDays[1]!.locksWith).toBe("2026-09-25");
    expect(t.eatingDays[0]!.locksWith).toBeNull();
    expect(t.coversLabel).toBe("Covers Fri + Sat + Sun");
    expect(one({ date: "2026-09-23" }).units).toBe(1);
  });
  it("carries a re-addressed delivery's own address; inheriting ones have none", () => {
    expect(one({ date: "2026-09-23", addressOverride: { addressLine: "200 Bay St", postalCode: "M5J 2J1" } }).addressOverride)
      .toEqual({ addressLine: "200 Bay St", postalCode: "M5J 2J1" });
    expect(one({ date: "2026-09-23" }).addressOverride).toBeNull();
  });
  it("sorts by date and keeps mergedInto", () => {
    const ts = buildTrips([day({ date: "2026-09-28", status: "skipped", combinedInto: "2026-09-30" }), day({ date: "2026-09-23" })], NOW, plan);
    expect(ts.map((t) => t.date)).toEqual(["2026-09-23", "2026-09-28"]);
    expect(ts[1]!.mergedInto).toBe("2026-09-30");
  });
});

type Case = [string, Partial<CalendarDayInput> & { date: string }, Partial<Record<TripAction, boolean>>];
const off = { pick: false, swap: false, move: false, address: false };
const cases: Case[] = [
  ["upcoming", { date: "2026-09-23" }, { pick: true, swap: true, move: true, address: true }],
  ["make-up upcoming (a moved tiffin can't move again)", { date: "2026-09-25", isMakeup: true }, { pick: true, swap: true, move: false, address: true }],
  ["failed drop", { date: "2026-09-25", status: "skipped" }, { pick: false, swap: false, move: true, address: false }],
