// Regression coverage for the FINDING 1 / FINDING 2 fixes: buildMealsGrid must call
// resolveDeliveryMeal for its resolved/selected dish rather than re-deriving default
// selection, stale-pick fallback, or diet filtering itself. Every test here asserts BOTH
// buildMealsGrid and resolveDeliveryMeal AGREE — that agreement is the invariant under test.
import { afterAll, beforeEach, describe, expect, it, vi } from "vitest";
import { eq, like, ne } from "drizzle-orm";
import { db } from "@/db/client";
import {
  couponRedemptions, deliveries, deliveryFrequencies, dishes, ledgerEntries, mealSelections, menuItems, menuWeeks, orders, payments, plans, users, walletLedger,
} from "@/db/schema";
import { attachDishToPlans, categoryIdFor, testPlanId } from "@/db/test-helpers";
import { loadCatalogSnapshot } from "@/lib/catalog/load";
import { thisWeekStartIso } from "@/lib/menu/delivery-dates";
import type { GridCell } from "../meals-grid";

vi.mock("@/lib/auth", () => ({ auth: async () => null }));
const { resolveDeliveryMeal } = await import("../resolve-delivery-meal");
const { buildMealsGrid } = await import("../meals-grid");
const { skipDelivery, pauseRange } = await import("@/lib/services/deliveries.service");

const SETTINGS = { timezone: "UTC", cutoffHour: 23 };
const THIS_MONDAY = thisWeekStartIso(Date.now(), SETTINGS.timezone);

async function reset() {
  await db.delete(mealSelections); await db.delete(menuItems); await db.delete(menuWeeks); await db.delete(deliveries);
  // Orders other suites leave behind still hold money rows that restrict deleting them.
  await db.delete(walletLedger); await db.delete(ledgerEntries); await db.delete(couponRedemptions); await db.delete(payments);
  await db.delete(orders); await db.delete(dishes); await db.delete(users).where(ne(users.isSystem, true));
  await db.delete(plans).where(like(plans.key, "veg_no_sabzi_%"));
}

// A scheduled delivery row for THIS_MONDAY, far from its cutoff — the grid's read path only
// shows dates with a visible ('scheduled') row, so every grid test needs one materialized here
// (order alone no longer implies a schedule).
async function seedMondayDelivery(orderId: bigint, overrides: Partial<typeof deliveries.$inferInsert> = {}) {
  const [row] = await db.insert(deliveries).values({
    orderId, deliveryDate: THIS_MONDAY, status: "scheduled", cutoffAt: Date.now() + 1e9, ...overrides,
  }).returning();
  return row;
}

async function makeOrder(planId: bigint, overrides: Partial<typeof orders.$inferInsert> = {}) {
  const snap = await loadCatalogSnapshot();
  const [u] = await db.insert(users).values({ email: `u${Math.random().toString(36).slice(2)}@test.invalid`,  phone: `+1647555${Math.floor(Math.random() * 9000 + 1000)}`, role: "user" }).returning();
  const [freq] = await db.select().from(deliveryFrequencies).where(eq(deliveryFrequencies.key, "5_day")).limit(1);
  // A meal size scoped to THIS order's plan — allowedDishIdsForMealSize derives
  // eligible dishes from the meal size's own composition rows, not order.planId.
  const mealSize = snap.mealSizes.find((m) => m.planId === planId) ?? snap.mealSizes[0];
  const [o] = await db.insert(orders).values({
    userId: u.id, planId, mealSizeId: mealSize.id, frequencyId: freq.id,
    persons: 1, mealSlots: ["lunch"], durationWeeks: 1, startDate: THIS_MONDAY,
    // Counts now live on the order snapshot, not the plan — default to the veg shape.
    categoryCounts: { sabzi: 2, rice: 1 },
    tiffinCount: 5, perTiffinPrice: "10.00", pricingSnapshot: {}, total: "50.00", status: "active",
    deploymentId: `SUB-GRID-${Math.floor(Math.random() * 1e6)}`, fullName: "T", addressLine: "1", city: "Toronto", postalCode: "M5V 2T6",
    ...overrides,
  }).returning();
  const mealOrder = {
    id: o.id, publicId: o.publicId, planId: o.planId, mealSizeId: o.mealSizeId, persons: o.persons, categoryCounts: o.categoryCounts, mealSlots: o.mealSlots,
    includeSaturday: o.includeSaturday, includeSunday: o.includeSunday, startDate: o.startDate,
    durationWeeks: o.durationWeeks, frequencyKey: "5_day",
  };
  return { order: o, mealOrder };
}

async function makeWeek() {
  const [w] = await db.insert(menuWeeks).values({ weekStart: THIS_MONDAY, status: "released", orderCutoff: new Date("2999-01-01").getTime() }).returning();
  return w;
}

function cellsFor(grid: GridCell[], day: string, slot: string) {
  return grid.filter((c) => c.day === day && c.slot === slot);
}

describe("buildMealsGrid agrees with resolveDeliveryMeal", () => {
  beforeEach(reset);
  afterAll(reset);

  it("falls back to the day's default when a pick's dish was removed from that day (still present another day)", async () => {
    const snap = await loadCatalogSnapshot();
    const vegPlan = snap.plans.find((p) => p.key === "veg")!;
    const { order, mealOrder } = await makeOrder(vegPlan.id);
    await seedMondayDelivery(order.id);
    const week = await makeWeek();

    const [sabziDefault] = await db.insert(dishes).values({ planId: await testPlanId(), name: "Paneer"}).returning();
    await attachDishToPlans(sabziDefault.id);
    const [staleDish] = await db.insert(dishes).values({ planId: await testPlanId(), name: "Bhindi"}).returning();
    await attachDishToPlans(staleDish.id);

    // mon: only the default is offered (staleDish was removed from mon's menu).
    await db.insert(menuItems).values({ menuWeekId: week.id, dayOfWeek: "mon", categoryId: await categoryIdFor("sabzi"), dishId: sabziDefault.id, isDefault: true });
    // tue: staleDish is still offered elsewhere in the week.
    await db.insert(menuItems).values({ menuWeekId: week.id, dayOfWeek: "tue", categoryId: await categoryIdFor("sabzi"), dishId: staleDish.id, isDefault: false });

    // Subscriber's pick for mon references the now-removed dish.
    await db.insert(mealSelections).values({
      orderId: order.id, menuWeekId: week.id, dayOfWeek: "mon", categoryId: await categoryIdFor("sabzi"), personIndex: 1, pickIndex: 1, dishId: staleDish.id,
    });

    const resolved = await resolveDeliveryMeal(order, week, "mon", 1, null);
    const resolvedSabzi = resolved.find((r) => r.category === "sabzi")!;
    expect(resolvedSabzi.picks[0].dishPublicId).toBe(sabziDefault.publicId);
    expect(resolvedSabzi.picks[0].isDefaulted).toBe(true);

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty !== null) throw new Error(`expected grid, got empty=${grid.empty}`);
    const cell = cellsFor(grid.grid, "mon", "sabzi").find((c) => c.pickIndex === 1)!;

    expect(cell.selectedDishId).toBe(resolvedSabzi.picks[0].dishPublicId);
    expect(cell.isDefaulted).toBe(true);
    expect(cell.selectedDishId).toBe(sabziDefault.publicId);
  });

  it("omits a category whose day items are all off the order's plan (veg plan, non-veg-only rice)", async () => {
    const snap = await loadCatalogSnapshot();
    const vegPlan = snap.plans.find((p) => p.key === "veg")!;
    const { order, mealOrder } = await makeOrder(vegPlan.id);
    await seedMondayDelivery(order.id);
    const week = await makeWeek();

    const [sabziDish] = await db.insert(dishes).values({ planId: await testPlanId(), name: "Paneer"}).returning();
    await attachDishToPlans(sabziDish.id);
    await db.insert(menuItems).values({ menuWeekId: week.id, dayOfWeek: "mon", categoryId: await categoryIdFor("sabzi"), dishId: sabziDish.id, isDefault: true });

    // rice is fixed/non-selectable, and its only mon item is attached ONLY to the
    // non-veg plan — so it is outside this veg-plan order's reach.
    const [riceNonveg] = await db.insert(dishes).values({ planId: await testPlanId(), name: "Chicken Biryani Rice"}).returning();
    await attachDishToPlans(riceNonveg.id, ["non-veg"]);
    await db.insert(menuItems).values({ menuWeekId: week.id, dayOfWeek: "mon", categoryId: await categoryIdFor("rice"), dishId: riceNonveg.id, isDefault: true });

    const resolved = await resolveDeliveryMeal(order, week, "mon", 1, null);
    expect(resolved.find((r) => r.category === "rice")).toBeUndefined();

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty !== null) throw new Error(`expected grid, got empty=${grid.empty}`);
    expect(cellsFor(grid.grid, "mon", "rice")).toHaveLength(0);

    // sabzi (correctly veg) is still present in both, to prove the day/week isn't broken wholesale.
    expect(resolved.find((r) => r.category === "sabzi")).toBeDefined();
    expect(cellsFor(grid.grid, "mon", "sabzi").length).toBeGreaterThan(0);
  });

  it("reset() cleans up its own veg_no_sabzi_ junk plans (scoped cleanup, not a blanket wipe)", async () => {
    await db.insert(plans).values({
      key: `veg_no_sabzi_${Math.floor(Math.random() * 1e6)}`, name: "Veg (no sabzi count)", planType: "tiffin",
    });

    await reset();

    const leaked = await db.select().from(plans).where(like(plans.key, "veg_no_sabzi_%"));
    expect(leaked).toHaveLength(0);
  });

  it("emits zero cells/picks for a selectable category the order's category_counts omits", async () => {
    const [vegPlan] = await db.insert(plans).values({
      key: `veg_no_sabzi_${Math.floor(Math.random() * 1e6)}`, name: "Veg (no sabzi count)", planType: "tiffin",
    }).returning();
    // The omission now lives on the order snapshot, not the plan: sabzi intentionally omitted.
    const { order, mealOrder } = await makeOrder(vegPlan.id, { categoryCounts: { rice: 1, roti: 4, raita: 1, salad: 1 } });
    await seedMondayDelivery(order.id);
    const week = await makeWeek();

    const [sabziDish] = await db.insert(dishes).values({ planId: await testPlanId(), name: "Paneer"}).returning();
    await attachDishToPlans(sabziDish.id);
    await db.insert(menuItems).values({ menuWeekId: week.id, dayOfWeek: "mon", categoryId: await categoryIdFor("sabzi"), dishId: sabziDish.id, isDefault: true });

    const resolved = await resolveDeliveryMeal(order, week, "mon", 1, null);
    expect(resolved.find((r) => r.category === "sabzi")).toBeUndefined();

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty !== null) throw new Error(`expected grid, got empty=${grid.empty}`);
    expect(cellsFor(grid.grid, "mon", "sabzi")).toHaveLength(0);
  });
});

describe("buildMealsGrid reads deliveries rows, not a computed schedule", () => {
  beforeEach(reset);
  afterAll(reset);

  it("a skipped delivery vanishes from the grid", async () => {
    const snap = await loadCatalogSnapshot();
    const vegPlan = snap.plans.find((p) => p.key === "veg")!;
    const { order, mealOrder } = await makeOrder(vegPlan.id);
    const d = await seedMondayDelivery(order.id);
    await makeWeek();

    await skipDelivery(d.publicId, 1n);

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty === null) {
      expect(grid.weekDatesView.some((v) => v.dateIso === THIS_MONDAY)).toBe(false);
    } else {
      expect(grid.empty).toBe("no-dates");
    }
  });

  it("a paused delivery vanishes from the grid", async () => {
    const snap = await loadCatalogSnapshot();
    const vegPlan = snap.plans.find((p) => p.key === "veg")!;
    const { order, mealOrder } = await makeOrder(vegPlan.id);
    await seedMondayDelivery(order.id, { orderId: order.id, status: "paused" });
    await makeWeek();

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty === null) {
      expect(grid.weekDatesView.some((v) => v.dateIso === THIS_MONDAY)).toBe(false);
    } else {
      expect(grid.empty).toBe("no-dates");
    }
  });

  it("a scheduled make-up delivery appears in the grid (visibleDeliveries has no makeupForDeliveryId filter)", async () => {
    const snap = await loadCatalogSnapshot();
    const vegPlan = snap.plans.find((p) => p.key === "veg")!;
    const { order, mealOrder } = await makeOrder(vegPlan.id);
    const original = await seedMondayDelivery(order.id);
    await makeWeek();

    // A make-up is a real, independently-scheduled delivery — it must show up in the grid just
    // like any other scheduled row, regardless of makeupForDeliveryId.
    const makeupDateIso = (() => {
      const d = new Date(`${THIS_MONDAY}T00:00:00.000Z`);
      d.setUTCDate(d.getUTCDate() + 1);
      return d.toISOString().slice(0, 10);
    })();
    await db.insert(deliveries).values({
      orderId: order.id, deliveryDate: makeupDateIso, status: "scheduled",
      cutoffAt: Date.now() + 1e9, makeupForDeliveryId: original.id,
    });

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty !== null) throw new Error(`expected grid, got empty=${grid.empty}`);
    expect(grid.weekDatesView.some((v) => v.dateIso === makeupDateIso)).toBe(true);
  });

  it("the grid's lockMs equals the row's stored cutoffAt", async () => {
    const snap = await loadCatalogSnapshot();
    const vegPlan = snap.plans.find((p) => p.key === "veg")!;
    const { order, mealOrder } = await makeOrder(vegPlan.id);
    const cutoffAt = Date.now() + 12345;
    const d = await seedMondayDelivery(order.id, { cutoffAt });
    await makeWeek();

    const grid = await buildMealsGrid(mealOrder, SETTINGS);
    if (grid.empty !== null) throw new Error(`expected grid, got empty=${grid.empty}`);
    const view = grid.weekDatesView.find((v) => v.dateIso === THIS_MONDAY)!;
    expect(view.lockMs).toBe(d.cutoffAt);
    expect(view.lockMs).toBe(cutoffAt);
  });
});

// Resolving "what a subscriber actually receives" lives in ONE place:
// resolveCategoriesForDay (resolve-delivery-meal.ts). buildMealsGrid consumes it, and any
// future kitchen/ops/Optimo read MUST too — a second implementation will drift, and then
// the subscriber sees one meal while the kitchen packs another.
import { ValidationError } from "@foundry/commons";
import { and, asc, eq, inArray } from "drizzle-orm";
import { db } from "@/db/client";
import { deliveries, deliveryCategorySwaps, dishes, mealSelections, mealSizeItems, menuItems, menuWeeks, orderActivities, orders, plans } from "@/db/schema";
import { applySwapsToCounts } from "@/lib/menu/swap-rules";
import { categoryCountsFromItems } from "@/lib/menu/pick-size";
import { validateMealRules } from "@/lib/menu/meal-validation";
import { MealRuleViolationError } from "@/lib/menu/meal-rule-error";
import type { HydratedPick, MealRule } from "@/lib/menu/meal-rule-types";
import type { RuleLabels } from "@/lib/menu/meal-rule-text";
import { dishCategoriesService } from "@/lib/services/dish-categories.service";
import { mealRulesService } from "@/lib/services/meal-rules.service";
import { requireCategoryIds } from "@/lib/menu/category-ids";
import { mealPickNote } from "@/lib/menu/meal-pick-note";
import { carryingTrips } from "@/lib/menu/trip-lookup";
import { swapAppliesTo } from "@/lib/menu/coverage";
import { type DayOfWeek } from "@/lib/menu/delivery-dates";

type Order = typeof orders.$inferSelect;
type Week = typeof menuWeeks.$inferSelect;

const DAY_OFFSET: Record<DayOfWeek, number> = { mon: 0, tue: 1, wed: 2, thu: 3, fri: 4, sat: 5, sun: 6 };

/**
 * The dish ids on a plan. Single source of truth for "what may this plan be
 * served", shared by setSelection (input validation), buildMealsGrid (option
 * filtering) and resolveDeliveryMeal (per-category filtering) so the three
 * can never disagree.
 */
/**
 * Adds the dish facts a rule condition can test: name, and the dish's own plan
 * (the Diet axis — NOT the order's plan, which can differ when a meal size mixes
 * categories across plans).
 */
async function hydratePicks(
  picks: { category: string; dishId: bigint }[],
): Promise<HydratedPick[]> {
  if (picks.length === 0) return [];
  const ids = [...new Set(picks.map((p) => p.dishId))];
  const rows = await db
    .select({ id: dishes.id, name: dishes.name, planId: dishes.planId })
    .from(dishes)
    .where(inArray(dishes.id, ids));
  const byId = new Map(rows.map((r) => [r.id.toString(), r]));
  return picks.flatMap((p) => {
    const d = byId.get(p.dishId.toString());
    // A pick whose dish no longer exists cannot be tested; skipping it is safer
    // than inventing a name that a dish_name rule might match.
    return d ? [{ dishId: p.dishId, dishName: d.name, dishPlanId: d.planId, category: p.category }] : [];
  });
}

/**
 * Names for generating a rule's sentence when an admin left `description` blank.
 * Only loads what the rules actually reference.
 */
async function ruleLabelsFor(
  rules: MealRule[],
  cats: { key: string; label: string }[],
): Promise<RuleLabels> {
  const planIds = new Set<string>();
  const dishIds = new Set<string>();
  for (const r of rules) {
    for (const c of r.conditions) {
      for (const id of c.valueIds ?? []) {
        (c.field === "dish_plan" ? planIds : dishIds).add(id.toString());
      }
    }
  }
  const [planRows, dishRows] = await Promise.all([
    planIds.size
      ? db.select({ id: plans.id, name: plans.name }).from(plans).where(inArray(plans.id, [...planIds].map(BigInt)))
      : Promise.resolve([]),
    dishIds.size
      ? db.select({ id: dishes.id, name: dishes.name }).from(dishes).where(inArray(dishes.id, [...dishIds].map(BigInt)))
      : Promise.resolve([]),
  ]);
  return {
    category: Object.fromEntries(cats.map((c) => [c.key, c.label])),
    plan: Object.fromEntries(planRows.map((r) => [r.id.toString(), r.name])),
    dish: Object.fromEntries(dishRows.map((r) => [r.id.toString(), r.name])),
  };
}

export async function dishIdsForPlan(planId: bigint): Promise<Set<bigint>> {
  const rows = await db.select({ id: dishes.id }).from(dishes).where(eq(dishes.planId, planId));
  return new Set(rows.map((r) => r.id));
}

/**
 * A dish belongs to exactly one plan now, so "exclusive to this plan" is every
 * dish on it — same set as dishIdsForPlan. Kept as a separate export (rather
 * than inlining dishIdsForPlan at each call site) because callers name it for
 * the "exclusive_to_plan" meal-rule concept, not because the sets can differ.
 */
export const exclusiveDishIdsForPlan = dishIdsForPlan;

/**
 * The dish ids a subscriber on this MEAL SIZE may ever be served — the union of
 * dishIdsForPlan(planId) over every distinct plan the meal size's own
 * composition rows target, not just the order's own plan.
 *
 * This is what makes "add a second Sabzi row, tagged veg" on a non-veg meal
 * size actually reach the subscriber: a meal size can mix categories across
 * plans (e.g. non-veg thali with both a veg-tagged and a non-veg-tagged sabzi
 * slot), so the food-safety filter has to be keyed off the meal size's item
 * rows, not the order's single planId. A meal size whose items are all on one
 * plan (the common case) reduces to exactly dishIdsForPlan(that plan) — same
 * behavior as before this existed.
 */
export async function allowedDishIdsForMealSize(mealSizeId: bigint): Promise<Set<bigint>> {
  const rows = await db.selectDistinct({ planId: mealSizeItems.planId }).from(mealSizeItems).where(eq(mealSizeItems.mealSizeId, mealSizeId));
  const sets = await Promise.all(rows.map((r) => dishIdsForPlan(r.planId)));
  const out = new Set<bigint>();
  for (const s of sets) for (const id of s) out.add(id);
  return out;
}

// The ISO date of `dayOfWeek` within the menu week starting on weekStart.
function dateInWeek(weekStartIso: string, dayOfWeek: DayOfWeek): string {
  const d = new Date(`${weekStartIso}T00:00:00.000Z`);
  d.setUTCDate(d.getUTCDate() + DAY_OFFSET[dayOfWeek]);
  return d.toISOString().slice(0, 10);
}

export const selectionsService = {
  async setSelection(input: { order: Order; menuWeek: Week; dayOfWeek: DayOfWeek; slot: string; personIndex: number; pickIndex?: number; dishPublicId: string; actorId?: bigint | null }) {
    const { order, menuWeek, dayOfWeek, slot, personIndex, pickIndex = 1, dishPublicId, actorId = null } = input;
    if (order.status === "cancelled") throw new ValidationError("This order is cancelled");
    if (personIndex < 1 || personIndex > order.persons) throw new ValidationError("Invalid person");

    const deliveryDateIso = dateInWeek(menuWeek.weekStart, dayOfWeek);

    // A scheduled trip that COVERS the date is the single source of truth for day-membership AND
    // cutoff: a carried eating day (Tue on Monday's trip) has no row of its own but locks with the
    // trip. Paused/skipped/merged rows, or a date nothing covers, are not part of the order.
    const deliveryRow = (await carryingTrips(order.id, deliveryDateIso, deliveryDateIso)).get(deliveryDateIso);
    if (!deliveryRow) {
      throw new ValidationError("That day isn't part of your order");
    }
    if (Date.now() > deliveryRow.cutoffAt) {
      throw new ValidationError("Selections are locked — the cutoff for that day has passed");
    }

    const categoryId = (await requireCategoryIds([slot])).get(slot)!;

    const [dishRow] = await db.select({ id: dishes.id, name: dishes.name, planId: dishes.planId }).from(dishes).where(eq(dishes.publicId, dishPublicId)).limit(1);
    if (!dishRow) throw new ValidationError("Dish not found");
    const dishId = dishRow.id;

    const [item] = await db.select().from(menuItems).where(and(
      eq(menuItems.menuWeekId, menuWeek.id), eq(menuItems.dayOfWeek, dayOfWeek), eq(menuItems.categoryId, categoryId), eq(menuItems.dishId, dishId),
    )).limit(1);
    if (!item) throw new ValidationError("Dish is not available for that day and slot");

    // The dish must be on a plan this order's MEAL SIZE actually composes with — not
    // necessarily the order's own plan, since a meal size can mix categories across
    // plans (a non-veg thali can carry a veg-tagged sabzi slot). A dish on a plan
    // nothing in this meal size ever references is still refused.
    const allowedDishIds = await allowedDishIdsForMealSize(order.mealSizeId);
    if (!allowedDishIds.has(dishId)) throw new ValidationError("Dish does not match your plan");

    // `slot` is a dish-category key: only categories marked selectable may receive a subscriber pick,
    // and pickIndex must fall within that category's per-plan count (e.g. sabzi:2 allows picks 1 and 2).
    const cats = await dishCategoriesService.forPlan(order.planId);
    const cat = cats.find((c) => c.key === slot);
    if (!cat) throw new ValidationError("Unknown category");
    if (!cat.selectable) throw new ValidationError("This item is fixed and can't be changed");
    // Swaps on this day change how many picks a category has (daal -> sabzi = 2 sabzi); the
    // picker renders those folded counts, so validate against the same thing.
    const swaps = await db
      .select({ fromCategory: deliveryCategorySwaps.fromCategory, toCategory: deliveryCategorySwaps.toCategory, qtyFrom: deliveryCategorySwaps.qtyFrom, qtyTo: deliveryCategorySwaps.qtyTo, forDate: deliveryCategorySwaps.forDate })
      .from(deliveryCategorySwaps)
      .where(eq(deliveryCategorySwaps.deliveryId, deliveryRow.id))
      .orderBy(asc(deliveryCategorySwaps.id));
    const daySwaps = swaps.filter((s) => swapAppliesTo(s.forDate, deliveryRow.deliveryDate, deliveryDateIso));
    const mealItems = await db
      .select({ category: mealSizeItems.category })
      .from(mealSizeItems)
      .where(eq(mealSizeItems.mealSizeId, order.mealSizeId));
    const baseCounts = mealItems.length > 0 ? categoryCountsFromItems(mealItems) : (order.categoryCounts ?? {});
    const max = applySwapsToCounts(baseCounts, daySwaps)[slot] ?? 0;
    if (pickIndex < 1 || pickIndex > max) throw new ValidationError("Invalid pick");

    // Meal rules against the proposed final meal for this person/day.
    //
    // Evaluated over EVERY category, not just the one being edited: rules like
    // "cannot coexist" or a dish-name limit span categories, so a per-category
    // check cannot see them. The extra query only runs when rules exist.
    const rules = await mealRulesService.listEnabledForOrder({
      planId: order.planId,
      mealSizeId: order.mealSizeId,
    });
    if (rules.length > 0) {
      const categoryIds = await requireCategoryIds(cats.map((c) => c.key));
      const catId = categoryIds.get(slot)!;
      const idToKey = new Map([...categoryIds.entries()].map(([key, id]) => [id.toString(), key]));

      const existing = await db
        .select({
          categoryId: mealSelections.categoryId,
          pickIndex: mealSelections.pickIndex,
          dishId: mealSelections.dishId,
        })
        .from(mealSelections)
        .where(and(
          eq(mealSelections.orderId, order.id),
          eq(mealSelections.menuWeekId, menuWeek.id),
          eq(mealSelections.dayOfWeek, dayOfWeek),
          eq(mealSelections.personIndex, personIndex),
        ));

      // Overlay the incoming pick on the stored meal, keyed by (category, pick).
      const byKey = new Map<string, { category: string; pickIndex: number; dishId: bigint }>();
      for (const e of existing) {
        const key = idToKey.get(e.categoryId.toString());
        if (!key) continue; // category no longer on this plan — not part of the proposed meal
        byKey.set(`${key}:${e.pickIndex}`, { category: key, pickIndex: e.pickIndex, dishId: e.dishId });
      }
      byKey.set(`${slot}:${pickIndex}`, { category: slot, pickIndex, dishId });
      void catId;

      // Drop picks past each category's effective (post-swap) slot count, so a
      // pick that a swap has already removed cannot trigger a phantom violation.
      const effective = applySwapsToCounts(baseCounts, daySwaps);
      const live = [...byKey.values()].filter(
        (p) => p.pickIndex >= 1 && p.pickIndex <= (effective[p.category] ?? 0),
      );

      const picks = await hydratePicks(live);
      const focus = picks.find((p) => p.dishId === dishId && p.category === slot);
      const ruleCheck = validateMealRules({
        rules,
        picks,
        focus,
        labels: Object.fromEntries(cats.map((c) => [c.key, c.label])),
        // Only needed to GENERATE a sentence; rules the admin already described
        // need no lookups, so skip the two queries when every rule has text.
        ruleLabels: rules.every((r) => r.description?.trim())
          ? undefined
          : await ruleLabelsFor(rules, cats),
      });
      if (!ruleCheck.ok) throw new MealRuleViolationError(ruleCheck.reason, ruleCheck.rulePublicId);
    }

    // Read the outgoing dish BEFORE the upsert overwrites it. Without this the log could
    // only say "someone touched Tuesday" — the prior value is what answers the actual
    // question staff get asked ("why did I get paneer?").
    const [prior] = await db
      .select({ dishId: mealSelections.dishId, dishName: dishes.name })
      .from(mealSelections)
      .leftJoin(dishes, eq(dishes.id, mealSelections.dishId))
      .where(and(
        eq(mealSelections.orderId, order.id),
        eq(mealSelections.menuWeekId, menuWeek.id),
        eq(mealSelections.dayOfWeek, dayOfWeek),
        eq(mealSelections.categoryId, categoryId),
        eq(mealSelections.personIndex, personIndex),
        eq(mealSelections.pickIndex, pickIndex),
      ))
      .limit(1);

    await db.insert(mealSelections).values({ orderId: order.id, menuWeekId: menuWeek.id, dayOfWeek, categoryId, personIndex, pickIndex, dishId })
      .onConflictDoUpdate({
        target: [mealSelections.orderId, mealSelections.menuWeekId, mealSelections.dayOfWeek, mealSelections.categoryId, mealSelections.personIndex, mealSelections.pickIndex],
        set: { dishId },
      });

    // Re-picking the same dish is a no-op the customer can trigger by tapping twice —
    // logging it would bury the real changes.
    if (prior?.dishId === dishId) return;

    await db.insert(orderActivities).values({
      orderId: order.id,
      deliveryId: deliveryRow.id,
      type: "meal_pick",
      note: mealPickNote({
        deliveryDateIso,
        categoryLabel: cat.label,
        personIndex,
        persons: order.persons,
        from: prior?.dishName ?? null,
        to: dishRow.name,
      }),
      createdBy: actorId,
    });
  },
};

import { afterAll, beforeEach, describe, expect, it, vi } from "vitest";
import { eq, ne } from "drizzle-orm";
