describe("Order Delivery Charges (Integration)", () => {
  beforeEach(reset);
  afterAll(reset);

  it("persists deliveryCharge, deliveryTagId, deliveryStrategyIds, addressTagId and immutable pricingSnapshot", async () => {
    // 1. Configure delivery rules
    await deliveryService.updateBaseDeliveryCharge(2); // Base = $2.00
    const spot = await deliveryService.saveDeliveryStrategyGroup({ name: "Apartment" });
    const home = await deliveryService.saveDeliveryStrategyGroup({ name: "Home" });
    const dt = await deliveryService.saveDeliveryStrategy({
      name: "Doorstep",
      chargeType: "fixed",
      chargeValue: 1.5,
      groupId: spot.id,
    });
    const lobby = await deliveryService.saveDeliveryStrategy({ name: "Lobby", chargeType: "none", chargeValue: 0, groupId: spot.id });
    const porch = await deliveryService.saveDeliveryStrategy({ name: "Porch", chargeType: "none", chargeValue: 0, groupId: home.id });
    await deliveryService.connectDeliveryStrategy(dt.id, [lobby.id]);
    const call = await deliveryService.saveDeliveryStrategy({
      name: "Call on arrival",
      chargeType: "fixed",
      chargeValue: 0.5,
      groupId: spot.id,
    });
    expect(dt.groupId).toBe(spot.id);
    // Connections never span tags.
    await expect(deliveryService.connectDeliveryStrategy(dt.id, [porch.id])).rejects.toThrow("own tag");
    // Every strategy needs a tag.
    await expect(deliveryService.saveDeliveryStrategy({ name: "Loose", chargeType: "none", chargeValue: 0 })).rejects.toThrow("Pick a tag");
    const at = await deliveryService.saveAddressTag({
      name: "Apartment",
      chargeType: "percent",
      chargeValue: 5,
    });
    await invalidateCatalogSnapshot();

    const snap = await loadCatalogSnapshot();
    const planKey = snap.plans[0].key;
    const mealSizePublicId = snap.mealSizes[0].publicId;

    // 2. Create order with delivery selections
    const { deploymentId, publicId } = await createOrder({
      planKey,
      selections: {
        mealSizeId: mealSizePublicId,
        frequencyKey: "5_day",
        persons: 1,
        mealSlots: ["lunch"],
        includeSaturday: false,
        includeSunday: false,
        durationWeeks: 1,
        startDate: nextWeekday(new Date()).toISOString().slice(0, 10),
        deliveryTagId: spot.id,
        deliveryStrategyIds: [dt.id, call.id],
        addressTagId: at.id,
      },
      contact: {
        fullName: "Test Customer",
        phone: "+16475550222",
        email: "testcustomer@test.invalid",
        addressLine: "100 King St W",
        city: "Toronto",
        postalCode: "M5V 2T6",
      },
    });

    const [order] = await db.select().from(orders).where(eq(orders.publicId, publicId));
    expect(order).toBeDefined();

    // The new address typed at checkout keeps the drop-off chosen with it.
    const [addr] = await db.select({ tagId: customerAddresses.deliveryTagId, strategyIds: customerAddresses.deliveryStrategyIds }).from(customerAddresses).where(eq(customerAddresses.id, order.addressId!));
    expect(addr).toEqual({ tagId: spot.internalId, strategyIds: [dt.internalId, call.internalId] });

    const snapshot = order.pricingSnapshot as {
      subtotal: number;
      perTiffinPrice: number;
      tiffinCount: number;
      deliveryCharge?: {
        baseAmount: number;
        totalDeliveryCharge: number;
        deliveryStrategies: { name: string; group: string | null; amount: number }[];
        addressTag?: { name: string; amount: number };
      };
    };

    expect(snapshot.deliveryCharge).toBeDefined();
    expect(snapshot.deliveryCharge?.baseAmount).toBe(2);
    expect(snapshot.deliveryCharge?.deliveryStrategies.map((s) => [s.group, s.name, s.amount])).toEqual([
      ["Apartment", "Doorstep", 1.5],
      ["Apartment", "Call on arrival", 0.5],
    ]);
    expect(snapshot.deliveryCharge?.addressTag?.name).toBe("Apartment");
    expect(Number(order.deliveryCharge)).toBe(snapshot.deliveryCharge?.totalDeliveryCharge);
    expect(order.deliveryStrategyIds).toEqual([dt.internalId, call.internalId]);
    expect(order.deliveryTagId).toBe(spot.internalId);
    expect(order.addressTagId).toBe(at.internalId);
    const expectedDeliveryCharge = snapshot.deliveryCharge!.totalDeliveryCharge;

    // 3. Historical immutability test (Case 7):
    // Now change the delivery charge rules: Base -> $10, Doorstep -> $5
    await deliveryService.updateBaseDeliveryCharge(10);
    await deliveryService.saveDeliveryStrategy({
      id: dt.id,
      name: "Doorstep",
      chargeType: "fixed",
      chargeValue: 5,
      groupId: spot.id,
    });
    await invalidateCatalogSnapshot();

    // Verify the historical order remains untouched!
    const [orderAfter] = await db.select().from(orders).where(eq(orders.publicId, publicId));
    expect(Number(orderAfter.deliveryCharge)).toBe(expectedDeliveryCharge);
    expect(orderAfter.total).toBe(order.total);
    expect((orderAfter.pricingSnapshot as typeof snapshot).deliveryCharge?.totalDeliveryCharge).toBe(expectedDeliveryCharge);
  });

  it("reprice dynamically recalculates when customer changes delivery type or address tag (Case 8)", async () => {
    await deliveryService.updateBaseDeliveryCharge(2);
    const spot = await deliveryService.saveDeliveryStrategyGroup({ name: "Drop-off spot" });
    const dtLobby = await deliveryService.saveDeliveryStrategy({
      name: "Lobby",
      chargeType: "fixed",
      chargeValue: 1,
      groupId: spot.id,
    });
    const atHouse = await deliveryService.saveAddressTag({
      name: "House",
      chargeType: "none",
      chargeValue: 0,
    });
    const atApt = await deliveryService.saveAddressTag({
      name: "Apartment",
      chargeType: "fixed",
      chargeValue: 3,
    });
    await invalidateCatalogSnapshot();

    const snap = await loadCatalogSnapshot();
    const selBase = {
      mealSizeId: snap.mealSizes[0].publicId,
      frequencyKey: "5_day",
      persons: 1,
      mealSlots: ["lunch"],
      includeSaturday: false,
      includeSunday: false,
      durationWeeks: 1,
      startDate: nextWeekday(new Date()).toISOString().slice(0, 10),
    };

    // Reprice with House + Lobby: Base $2 + Lobby $1 + House $0 = $3 delivery
    const r1 = await reprice({ ...selBase, deliveryStrategyIds: [dtLobby.id], addressTagId: atHouse.id });
    expect(r1.pricing.deliveryCharge?.totalDeliveryCharge).toBe(3);

    // Reprice changed to Apartment + Lobby: Base $2 + Lobby $1 + Apt $3 = $6 delivery
    const r2 = await reprice({ ...selBase, deliveryStrategyIds: [dtLobby.id], addressTagId: atApt.id });
    expect(r2.pricing.deliveryCharge?.totalDeliveryCharge).toBe(6);
    expect(r2.pricing.subtotal).toBe(r1.pricing.subtotal + 3);
  });

  it("a tag still in use is retired, and its strategies leave the catalog", async () => {
    const spot = await deliveryService.saveDeliveryStrategyGroup({ name: "Apartment" });
    const lobby = await deliveryService.saveDeliveryStrategy({ name: "Lobby", chargeType: "none", chargeValue: 0, groupId: spot.id });
    // Same name under another tag is fine; under the same tag it is not.
    const other = await deliveryService.saveDeliveryStrategyGroup({ name: "Office" });
    await deliveryService.saveDeliveryStrategy({ name: "Lobby", chargeType: "none", chargeValue: 0, groupId: other.id });
    await expect(deliveryService.saveDeliveryStrategy({ name: "Lobby", chargeType: "none", chargeValue: 0, groupId: spot.id })).rejects.toThrow("already exists");

    expect(await deliveryService.deleteDeliveryStrategyGroup(spot.id)).toEqual({ success: true, deactivatedInstead: true });
    await invalidateCatalogSnapshot();
    const snap = await loadCatalogSnapshot();
    expect(snap.deliveryCharges?.strategyGroups?.map((g) => g.name)).toEqual(["Office"]);
    expect(snap.deliveryCharges?.deliveryStrategies.some((o) => o.publicId === lobby.id)).toBe(false);

    // Connections are shared: A→B, then C→B puts all three in one set.
    const mk = (name: string) => deliveryService.saveDeliveryStrategy({ name, chargeType: "none", chargeValue: 0, groupId: other.id });
    const [a, b, c] = [await mk("A"), await mk("B"), await mk("C")];
    await deliveryService.connectDeliveryStrategy(a.id, [b.id]);
    let all = await deliveryService.connectDeliveryStrategy(c.id, [a.id, b.id]);
    const setOf = (id: string) => all.find((o) => o.id === id)?.connectionId;
    expect(setOf(a.id)).toBeTruthy();
    expect(new Set([setOf(a.id), setOf(b.id), setOf(c.id)]).size).toBe(1);
    // Unpicking B from C's connections takes B out of the set; A and C stay connected.
    all = await deliveryService.connectDeliveryStrategy(c.id, [a.id]);
    expect(setOf(b.id)).toBeNull();
    expect(setOf(a.id)).toBe(setOf(c.id));
    // Leaving one alone in a set drops the set.
    all = await deliveryService.connectDeliveryStrategy(a.id, []);
    expect([setOf(a.id), setOf(c.id)]).toEqual([null, null]);
    expect(await db.select().from(deliveryStrategyConnections)).toHaveLength(0);
  });
});

import { afterAll, beforeEach, describe, expect, it, vi } from "vitest";
import { eq, ne } from "drizzle-orm";
import { ValidationError, nextWeekday } from "@foundry/commons";
import { db } from "@/db/client";
import { deliveries, ledgerEntries, orderActivities, orders, payments, users } from "@/db/schema";
import { loadCatalogSnapshot } from "@/lib/catalog/load";

vi.mock("@/lib/auth", () => ({ auth: async () => null }));
const { createOrder } = await import("../orders.service");

async function reset() {
  await db.delete(deliveries);
  await db.delete(ledgerEntries);
  await db.delete(payments);
  await db.delete(orders);
  await db.delete(users).where(ne(users.isSystem, true));
}

const baseInput = (mealSizePublicId: string, planKey: string) => ({
  planKey,
  selections: {
    mealSizeId: mealSizePublicId,
    frequencyKey: "5_day" as const,
    persons: 1,
    mealSlots: ["lunch"],
    includeSaturday: false,
    includeSunday: false,
    durationWeeks: 1,
    startDate: nextWeekday(new Date()).toISOString().slice(0, 10),
  },
  contact: { email: `u${Math.random().toString(36).slice(2)}@test.invalid`,  fullName: "A B", phone: "+16475550111", addressLine: "1 St", city: "Toronto", postalCode: "M5V 2T6" },
});

describe("createOrder (integration)", () => {
  beforeEach(reset);
  afterAll(reset);

  it("provisions a customer by phone, prices server-side, writes order + payment", async () => {
    const snap = await loadCatalogSnapshot();
    const { deploymentId, publicId } = await createOrder(baseInput(snap.mealSizes[0].publicId, snap.plans[0].key));
    expect(deploymentId).toMatch(/^SUB-/);
    expect(publicId).toMatch(/^ord_/);
    const [u] = await db.select().from(users).where(eq(users.phone, "+16475550111"));
    expect(u.role).toBe("user");
    const [o] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId));
    expect(o.publicId).toBe(publicId);
    expect(Number(o.total)).toBeGreaterThan(0);
    expect(o.tiffinCount).toBeGreaterThan(0);
    expect(Number.isInteger(o.tiffinCount)).toBe(true);
    expect(Number(o.perTiffinPrice)).toBeGreaterThan(0);
    // total = tiffins priced out, plus sales tax for the delivery province.
    const taxTotal = (o.pricingSnapshot as { taxTotal: number }).taxTotal;
    expect(Number(o.total)).toBeCloseTo(Number(o.perTiffinPrice) * o.tiffinCount + taxTotal, 2);
    const pays = await db.select().from(payments).where(eq(payments.orderId, o.id));
    expect(pays).toHaveLength(1);
    // A zone-matched order lands on "active" directly (createOrder never calls
    // activate()) and must materialize its N delivery rows in the same tx.
    expect(o.status).toBe("active");
    const drops = await db.select().from(deliveries).where(eq(deliveries.orderId, o.id));
    expect(drops.length).toBe(o.durationWeeks * 5); // 5_day frequency
    expect(drops.every((d) => d.status === "scheduled" && d.makeupForDeliveryId === null)).toBe(true);
  });

  it("seeds the activity timeline with a created row matching the initial status", async () => {
    const snap = await loadCatalogSnapshot();
    const { deploymentId } = await createOrder(baseInput(snap.mealSizes[0].publicId, snap.plans[0].key));
    const [o] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId));
    const acts = await db.select().from(orderActivities).where(eq(orderActivities.orderId, o.id));
    expect(acts).toHaveLength(1);
    expect(acts[0].type).toBe("created");
    expect(acts[0].toStatus).toBe(o.status);
  });

  it("reuses an existing customer on a second order with the same phone", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    await createOrder(input);
    // Second order for the same phone needs a non-overlapping window — the
    // guard under test here is customer dedup by phone, not the overlap rule.
    const secondStart = nextWeekday(new Date());
    secondStart.setUTCDate(secondStart.getUTCDate() + input.selections.durationWeeks * 7);
    await createOrder({
      ...input,
      selections: { ...input.selections, startDate: secondStart.toISOString().slice(0, 10) },
    });
    const rows = await db.select().from(users).where(eq(users.phone, "+16475550111"));
    expect(rows).toHaveLength(1);
  });

  // A returning customer who checks out logged-out and types a different number
  // must still be recognised, or the overlap guard runs against a brand-new
  // account and happily double-books the same calendar days.
  it("recognises a logged-out returning customer by email when the phone differs", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    await createOrder(input);

    // Same person, same email, second phone number, overlapping window.
    await expect(
      createOrder({
        ...input,
        contact: { ...input.contact, phone: "+16475550999" },
      }),
    ).rejects.toThrow(/already have a plan running/);

    // And no second account was minted for the new number.
    const rows = await db.select().from(users).where(eq(users.email, input.contact.email));
    expect(rows).toHaveLength(1);
  });

  it("attaches a non-overlapping order to the matched account rather than a new one", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    await createOrder(input);

    const laterStart = nextWeekday(new Date());
    laterStart.setUTCDate(laterStart.getUTCDate() + input.selections.durationWeeks * 7);
    const { deploymentId } = await createOrder({
      ...input,
      contact: { ...input.contact, phone: "+16475550999" },
      selections: { ...input.selections, startDate: laterStart.toISOString().slice(0, 10) },
    });

    const [matched] = await db.select().from(users).where(eq(users.email, input.contact.email));
    const [o] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId));
    expect(o.userId).toBe(matched.id);
  });

  it("attaches to ownerUserId without provisioning by phone", async () => {
    const snap = await loadCatalogSnapshot();
    const [owner] = await db.insert(users).values({ email: "owner@x.com", role: "user" }).returning();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    const { deploymentId } = await createOrder(input, { ownerUserId: owner.publicId });
    const [o] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId));
    expect(o.userId).toBe(owner.id);
    // No customer provisioned for the typed phone.
    const phoned = await db.select().from(users).where(eq(users.phone, "+16475550111"));
    expect(phoned).toHaveLength(0);
  });

  it("allows a second live plan when ownerUserId is set (customer checkout)", async () => {
    const snap = await loadCatalogSnapshot();
    const [owner] = await db.insert(users).values({ email: "two-plan@x.com", role: "user" }).returning();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    await createOrder(input, { ownerUserId: owner.publicId });
    // Second plan needs a non-overlapping window — this test's subject is that a
    // customer CAN carry two concurrent plans at all, not that windows may overlap.
    const secondStart = nextWeekday(new Date());
    secondStart.setUTCDate(secondStart.getUTCDate() + input.selections.durationWeeks * 7);
    const secondInput = { ...input, selections: { ...input.selections, startDate: secondStart.toISOString().slice(0, 10) } };
    await expect(createOrder(secondInput, { ownerUserId: owner.publicId })).resolves.toMatchObject({
      publicId: expect.stringMatching(/^ord_/),
    });
    const rows = await db.select().from(orders).where(eq(orders.userId, owner.id));
    expect(rows).toHaveLength(2);
  });

  it("rejects a malformed phone", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    input.contact.phone = "12";
    await expect(createOrder(input)).rejects.toBeInstanceOf(ValidationError);
  });

  it("stores order phone as E.164 on the user row", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    input.contact.phone = "647 555 0100";
    const { deploymentId } = await createOrder(input);
    const [u] = await db.select().from(users).where(eq(users.phone, "+16475550100"));
    expect(u).toBeDefined();
    expect(u.phone).toBe("+16475550100");
  });

  it("stores and round-trips lat/lng when the contact carries them", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    (input.contact as { lat?: number; lng?: number }).lat = 43.65107;
    (input.contact as { lat?: number; lng?: number }).lng = -79.347015;
    const { deploymentId } = await createOrder(input);
    const [o] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId));
    expect(o.latitude).toBeCloseTo(43.65107, 6);
    expect(o.longitude).toBeCloseTo(-79.347015, 6);
  });

  it("stores null lat/lng when the contact omits them", async () => {
    const snap = await loadCatalogSnapshot();
    const input = baseInput(snap.mealSizes[0].publicId, snap.plans[0].key);
    const { deploymentId } = await createOrder(input);
    const [o] = await db.select().from(orders).where(eq(orders.deploymentId, deploymentId));
    expect(o.latitude).toBeNull();
    expect(o.longitude).toBeNull();
  });
});

// Vacation (paused) trips can still be moved: actionAvailability offers Move for them, so the
// service must accept it (rescheduleDelivery's mutableStatuses includes "paused").
import { afterEach, describe, expect, it, vi } from "vitest";
import { eq, inArray } from "drizzle-orm";
import { nextWeekday } from "@foundry/commons";

vi.mock("@/lib/auth", () => ({ auth: async () => null }));

const { db } = await import("@/db/client");
const { deliveries, ledgerEntries, orders, payments, users } = await import("@/db/schema");
const { loadCatalogSnapshot } = await import("@/lib/catalog/load");
const { createOrder } = await import("../orders.service");
const { rescheduleDelivery, pauseRange } = await import("../deliveries.service");

const createdOrderIds: bigint[] = [];
const createdUserIds: bigint[] = [];

afterEach(async () => {
  const orderIds = createdOrderIds.splice(0);
  const userIds = createdUserIds.splice(0);
  if (orderIds.length) {
    await db.delete(ledgerEntries).where(inArray(ledgerEntries.orderId, orderIds));
    await db.delete(payments).where(inArray(payments.orderId, orderIds));
    await db.delete(orders).where(inArray(orders.id, orderIds));
  }
  if (userIds.length) await db.delete(users).where(inArray(users.id, userIds));
});

async function makeOrder(includeWeekend: boolean, frequencyKey = "5_day") {
  const snap = await loadCatalogSnapshot();
  const { publicId } = await createOrder({
    planKey: snap.plans[0].key,
    selections: {
      mealSizeId: snap.mealSizes[0].publicId,
      frequencyKey,
      persons: 1,
      mealSlots: ["lunch"],
      includeSaturday: includeWeekend,
      includeSunday: includeWeekend,
      durationWeeks: 1,
      startDate: nextWeekday(new Date(Date.now() + 3 * 864e5)).toISOString().slice(0, 10),
    },
    contact: {
      email: `u${Math.random().toString(36).slice(2)}@test.invalid`,
      fullName: "A B", phone: `+1647555${Math.floor(1000 + Math.random() * 9000)}`, addressLine: "1 St", city: "Toronto", postalCode: "M5V 2T6",
    },
  });
  const [order] = await db.select().from(orders).where(eq(orders.publicId, publicId)).limit(1);
  createdOrderIds.push(order.id);
  if (order.userId) createdUserIds.push(order.userId);
  return order;
}

async function firstDeliveryOf(order: { id: bigint }) {
  const [row] = await db.select().from(deliveries).where(eq(deliveries.orderId, order.id)).limit(1);
  return row;
}

describe("rescheduleDelivery on a vacation (paused) trip", () => {
  it("moves the paused day to a later plan day, matching actionAvailability's Move offer", async () => {
    const order = await makeOrder(false);
    const rows = await db.select().from(deliveries).where(eq(deliveries.orderId, order.id));
    const dates = rows.map((r) => r.deliveryDate).sort();
    await pauseRange(order.publicId, dates[0], dates[dates.length - 1]);
    const paused = (await db.select().from(deliveries).where(eq(deliveries.orderId, order.id)))
      .find((r) => r.deliveryDate === dates[0])!;
    expect(paused.status).toBe("paused");
    const target = nextWeekday(new Date(`${dates[dates.length - 1]}T00:00:00Z`)).toISOString().slice(0, 10);
    await expect(rescheduleDelivery(paused.publicId, target, null)).resolves.toMatchObject({ merged: false });
  });
});

// Moving ONE eating day off a multi-day trip (e.g. Saturday off a Fri+Sat+Sun trip) must split
// off only that tiffin — the rest of the trip keeps delivering on its own date, untouched.
// This is the exact bug reported in prod: moving "Friday" (really: one of its riders) dragged
// the whole Fri+Sat+Sun bundle along.
import { afterAll, beforeEach, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";
import { ValidationError } from "@foundry/commons";

vi.mock("@/lib/auth", () => ({ auth: async () => null }));

const { db } = await import("@/db/client");
const { deliveries, deliveryCategorySwaps, deliveryExtraTiffins, deliveryMoves, orders } = await import("@/db/schema");
const { rescheduleDelivery } = await import("../deliveries.service");
const { makeTripOrder, resetTrips } = await import("./trip-fixture");

const DEP = "SUB-SPLIT01";
const PFX = "tsplit";
const reset = () => resetTrips(DEP, PFX);
const extrasOf = async (id: bigint) => (await db.select({ d: deliveryExtraTiffins.eatDate }).from(deliveryExtraTiffins).where(eq(deliveryExtraTiffins.deliveryId, id))).map((r) => r.d).sort();

describe("rescheduleDelivery: splitting one eating day off a multi-day trip", () => {
  beforeEach(reset);
  afterAll(reset);

  it("moving Saturday off Fri+Sat+Sun leaves Fri+Sun on the original trip, still scheduled", async () => {
    const { fri } = await makeTripOrder(DEP, PFX);
    const res = await rescheduleDelivery(fri.publicId, "2030-01-19", 1n, "2030-01-12"); // Sat -> next Sat (2030-01-19 is a Sat, snaps to Fri 2030-01-18)
    expect(res.merged).toBe(false);

    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect(source.status).toBe("scheduled");
    expect(source.mergedIntoDeliveryId).toBeNull();
    expect(source.coversDates).toEqual(["2030-01-11", "2030-01-13"]);
    expect(source.tiffinUnits).toBe(2);

    const [target] = await db.select().from(deliveries).where(eq(deliveries.deliveryDate, res.carriedOn));
    expect(target.coversDates).toEqual(["2030-01-19"]); // now Saturday-the-19th's tiffin
    expect(target.tiffinUnits).toBe(1);
    expect(target.makeupForDeliveryId).toBeNull();
  });

  it("moving the anchor day (Friday itself) on MWF splits only Friday's tiffin, leaving Sat+Sun on Friday", async () => {
    const { fri } = await makeTripOrder(DEP, PFX);
    const res = await rescheduleDelivery(fri.publicId, "2030-01-18", 1n, "2030-01-11"); // sourceEatDate == trip's own date
    expect(res.merged).toBe(false);

    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect(source.status).toBe("scheduled");
    expect(source.mergedIntoDeliveryId).toBeNull();
    expect(source.coversDates).toEqual(["2030-01-12", "2030-01-13"]);
    expect(source.tiffinUnits).toBe(2);

    const [target] = await db.select().from(deliveries).where(eq(deliveries.deliveryDate, res.carriedOn));
    expect(target.coversDates).toEqual(["2030-01-18"]);
    expect(target.tiffinUnits).toBe(1);
    expect(target.makeupForDeliveryId).toBeNull();
  });

  it("moving Friday onto next Thursday merges only that tiffin onto Wednesday, under the 3-tiffin cap", async () => {
    const { fri } = await makeTripOrder(DEP, PFX, 1, "mwf", 2);
    // Thu 2030-01-17 snaps to Wed 2030-01-16, which already carries Wed+Thu (2). Friday alone makes 3.
    const res = await rescheduleDelivery(fri.publicId, "2030-01-17", 1n, "2030-01-11");
    expect(res.merged).toBe(true);
    expect(res.carriedOn).toBe("2030-01-16");

    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect(source.status).toBe("scheduled");
    expect(source.coversDates).toEqual(["2030-01-12", "2030-01-13"]);
    expect(source.tiffinUnits).toBe(2);

    const [wed] = await db.select().from(deliveries).where(eq(deliveries.deliveryDate, "2030-01-16"));
    expect(wed.coversDates).toEqual(["2030-01-16", "2030-01-17"]); // Fri's tiffin is now a second Thursday
    expect(await extrasOf(wed.id)).toEqual(["2030-01-17"]);
    expect(wed.tiffinUnits).toBe(3);
  });

  it("moving the anchor day (Friday itself) on a 5-day plan splits only Friday's tiffin off, leaving Sat+Sun on Friday", async () => {
    const { fri } = await makeTripOrder(DEP, PFX, 1, "5_day");
    const res = await rescheduleDelivery(fri.publicId, "2030-01-14", 1n, "2030-01-11"); // move Fri to next Mon
    expect(res.merged).toBe(false);

    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect(source.status).toBe("scheduled");
    expect(source.mergedIntoDeliveryId).toBeNull();
    expect(source.coversDates).toEqual(["2030-01-12", "2030-01-13"]); // Sat + Sun stay on Friday
    expect(source.tiffinUnits).toBe(2);

    const [target] = await db.select().from(deliveries).where(eq(deliveries.deliveryDate, res.carriedOn));
    expect(target.coversDates).toEqual(["2030-01-14"]);
    expect(target.tiffinUnits).toBe(1);
    expect(target.makeupForDeliveryId).toBeNull();
  });

  it("splitting onto an existing scheduled trip merges just the one tiffin", async () => {
    const { fri, wed } = await makeTripOrder(DEP, PFX);
    const res = await rescheduleDelivery(fri.publicId, "2030-01-09", 1n, "2030-01-12"); // Sat -> Wed (already scheduled, covers Wed+Thu)
    expect(res.merged).toBe(true);

    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect(source.coversDates).toEqual(["2030-01-11", "2030-01-13"]);
    expect(source.tiffinUnits).toBe(2);
    expect(source.mergedIntoDeliveryId).toBeNull();

    const [target] = await db.select().from(deliveries).where(eq(deliveries.id, wed.id));
    expect(target.coversDates).toEqual(["2030-01-09", "2030-01-10"]);
    expect(await extrasOf(target.id)).toEqual(["2030-01-09"]);
    expect(target.tiffinUnits).toBe(3);
  });

  it("a swap on the moved day stays behind (it takes the new day's meal); a swap on a remaining day stays on the source", async () => {
    const { fri } = await makeTripOrder(DEP, PFX);
    await db.insert(deliveryCategorySwaps).values([
      { deliveryId: fri.id, fromCategory: "sabzi", toCategory: "dal", qtyFrom: 1, qtyTo: 1, forDate: "2030-01-12" }, // Sat
      { deliveryId: fri.id, fromCategory: "roti", toCategory: "rice", qtyFrom: 1, qtyTo: 1, forDate: "2030-01-13" }, // Sun (stays)
    ]);
    const res = await rescheduleDelivery(fri.publicId, "2030-01-19", 1n, "2030-01-12");

    const sourceSwaps = await db.select().from(deliveryCategorySwaps).where(eq(deliveryCategorySwaps.deliveryId, fri.id));
    expect(sourceSwaps.map((s) => [s.fromCategory, s.forDate])).toEqual([["roti", "2030-01-13"]]);

    const [target] = await db.select().from(deliveries).where(eq(deliveries.deliveryDate, res.carriedOn));
    const targetSwaps = await db.select().from(deliveryCategorySwaps).where(eq(deliveryCategorySwaps.deliveryId, target.id));
    expect(targetSwaps).toEqual([]);
  });

  it("rejects a sourceEatDate that isn't part of this trip", async () => {
    const { fri } = await makeTripOrder(DEP, PFX);
    await expect(rescheduleDelivery(fri.publicId, "2030-01-19", 1n, "2030-01-20")).rejects.toBeInstanceOf(ValidationError);
  });

  it("a single-day trip ignores sourceEatDate and moves the whole trip", async () => {
    const { mon } = await makeTripOrder(DEP, PFX);
    await db.update(deliveries).set({ coversDates: ["2030-01-07"], tiffinUnits: 1 }).where(eq(deliveries.id, mon.id));
    const res = await rescheduleDelivery(mon.publicId, "2030-01-14", 1n, "2030-01-07");
    expect(res.merged).toBe(false);
    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, mon.id));
    expect(source.status).toBe("skipped");
  });

  it("the Fri/Sat/Sun example: Fri to Wed, Sat to next Tue; Friday's truck brings only Sun", async () => {
    const { fri, wed } = await makeTripOrder(DEP, PFX);
    await db.update(deliveries).set({ coversDates: ["2030-01-09"], tiffinUnits: 1 }).where(eq(deliveries.id, wed.id)); // Wed alone
    await rescheduleDelivery(fri.publicId, "2030-01-09", 1n, "2030-01-11");
    const tue = await rescheduleDelivery(fri.publicId, "2030-01-15", 1n, "2030-01-12"); // Tue rides Mon on mwf
    expect(tue.carriedOn).toBe("2030-01-14");

    const [w] = await db.select().from(deliveries).where(eq(deliveries.id, wed.id));
    expect([w.coversDates, await extrasOf(w.id), w.tiffinUnits]).toEqual([["2030-01-09"], ["2030-01-09"], 2]);
    const [f] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect([f.status, f.coversDates, f.tiffinUnits]).toEqual(["scheduled", ["2030-01-13"], 1]);
    const moves = await db.select({ from: deliveryMoves.fromEatDate, to: deliveryMoves.toEatDate }).from(deliveryMoves).where(eq(deliveryMoves.fromDeliveryId, fri.id));
    expect(moves.map((m) => [m.from, m.to]).sort()).toEqual([["2030-01-11", "2030-01-09"], ["2030-01-12", "2030-01-15"]]);
  });

  it("a moved-in tiffin can't move again, but the day's own tiffin can", async () => {
    const { fri, wed } = await makeTripOrder(DEP, PFX);
    await db.update(deliveries).set({ coversDates: ["2030-01-09"], tiffinUnits: 1 }).where(eq(deliveries.id, wed.id));
    await rescheduleDelivery(fri.publicId, "2030-01-09", 1n, "2030-01-11"); // Wed now: own + Fri's
    await rescheduleDelivery(wed.publicId, "2030-01-16", 1n, "2030-01-09"); // Wed's own tiffin leaves
    await expect(rescheduleDelivery(wed.publicId, "2030-01-18", 1n, "2030-01-09")).rejects.toThrow(/already moved/);
  });

  it("never lets a delivery exceed 3 tiffins", async () => {
    const { fri, wed } = await makeTripOrder(DEP, PFX); // Wed carries Wed+Thu
    await rescheduleDelivery(fri.publicId, "2030-01-09", 1n, "2030-01-11"); // 3 on Wed
    await expect(rescheduleDelivery(fri.publicId, "2030-01-10", 1n, "2030-01-12")).rejects.toThrow(/at most 3/);
    const [w] = await db.select().from(deliveries).where(eq(deliveries.id, wed.id));
    expect(w.tiffinUnits).toBe(3);
  });

  it("a held multi-day trip moves only the picked day; the rest stay on hold", async () => {
    const { fri } = await makeTripOrder(DEP, PFX);
    await db.update(deliveries).set({ status: "skipped" }).where(eq(deliveries.id, fri.id));
    await rescheduleDelivery(fri.publicId, "2030-01-19", 1n, "2030-01-12");
    const [f] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect([f.status, f.coversDates, f.tiffinUnits]).toEqual(["skipped", ["2030-01-11", "2030-01-13"], 2]);
  });

  it("same truck: Friday's tiffin eaten Saturday instead stays on Friday's delivery", async () => {
    const { fri } = await makeTripOrder(DEP, PFX);
    const res = await rescheduleDelivery(fri.publicId, "2030-01-12", 1n, "2030-01-11");
    expect(res.carriedOn).toBe("2030-01-11");
    const [f] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect([f.status, f.coversDates, await extrasOf(f.id), f.tiffinUnits]).toEqual(["scheduled", ["2030-01-12", "2030-01-13"], ["2030-01-12"], 3]);
  });

  it("a day whose tiffins all moved away can take a move again: the emptied row is revived", async () => {
    const { mon, wed, fri } = await makeTripOrder(DEP, PFX);
    await db.update(deliveries).set({ coversDates: ["2030-01-11"], tiffinUnits: 1 }).where(eq(deliveries.id, fri.id));
    await rescheduleDelivery(fri.publicId, "2030-01-10", 1n, "2030-01-11"); // Fri's only tiffin -> Thu, merges onto Wed
    const [gone] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect(gone.mergedIntoDeliveryId).toBe(wed.id);

    await rescheduleDelivery(mon.publicId, "2030-01-12", 1n, "2030-01-07"); // Mon's tiffin -> Sat, rides Friday
    const [f] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect([f.status, f.mergedIntoDeliveryId, f.coversDates, f.tiffinUnits]).toEqual(["scheduled", null, ["2030-01-12"], 1]);
  });

  it("a day emptied by a make-up is revived too, and the make-up keeps its tiffin", async () => {
    const { mon, fri } = await makeTripOrder(DEP, PFX);
    await db.update(deliveries).set({ coversDates: ["2030-01-11"], tiffinUnits: 1 }).where(eq(deliveries.id, fri.id));
    await rescheduleDelivery(fri.publicId, "2030-01-18", 1n, "2030-01-11"); // onto an open next Friday: a make-up row
    const [makeup] = await db.select().from(deliveries).where(eq(deliveries.makeupForDeliveryId, fri.id));
    await rescheduleDelivery(mon.publicId, "2030-01-11", 1n, "2030-01-07");
    const [f] = await db.select().from(deliveries).where(eq(deliveries.id, fri.id));
    expect([f.status, f.coversDates]).toEqual(["scheduled", ["2030-01-11"]]);
    const [m] = await db.select().from(deliveries).where(eq(deliveries.id, makeup.id));
    expect([m.status, m.coversDates, m.makeupForDeliveryId]).toEqual(["scheduled", ["2030-01-18"], null]);
    await expect(rescheduleDelivery(m.publicId, "2030-01-21", 1n)).rejects.toThrow(/already moved/);
  });
});

// Eat-day reschedule: picker is the day the customer wants to EAT. Weekends and
// off-pattern weekdays snap to the carrying trip (never a weekend delivery row).
import { afterEach, describe, expect, it, vi } from "vitest";
import { eq, inArray } from "drizzle-orm";
import { nextWeekday, parseIsoDateUtc, weekdayKey } from "@foundry/commons";

vi.mock("@/lib/auth", () => ({ auth: async () => null }));

const { db } = await import("@/db/client");
const { deliveries, ledgerEntries, orders, payments, users } = await import("@/db/schema");
const { loadCatalogSnapshot } = await import("@/lib/catalog/load");
const { createOrder } = await import("../orders.service");
const { rescheduleDelivery } = await import("../deliveries.service");
const { coveredDates } = await import("@/lib/menu/coverage");
const { carryTripDateIso } = await import("@/lib/menu/carry-trip");
import type { DayOfWeek } from "@/lib/menu/delivery-days";

const createdOrderIds: bigint[] = [];
const createdUserIds: bigint[] = [];

afterEach(async () => {
  const orderIds = createdOrderIds.splice(0);
  const userIds = createdUserIds.splice(0);
  if (orderIds.length) {
    await db.delete(ledgerEntries).where(inArray(ledgerEntries.orderId, orderIds));
    await db.delete(payments).where(inArray(payments.orderId, orderIds));
    await db.delete(orders).where(inArray(orders.id, orderIds));
  }
  if (userIds.length) await db.delete(users).where(inArray(users.id, userIds));
});

async function makeOrder(includeWeekend: boolean, frequencyKey = "5_day") {
  const snap = await loadCatalogSnapshot();
  const { publicId } = await createOrder({
    planKey: snap.plans[0].key,
    selections: {
      mealSizeId: snap.mealSizes[0].publicId,
      frequencyKey,
      persons: 1,
      mealSlots: ["lunch"],
      includeSaturday: includeWeekend,
      includeSunday: includeWeekend,
      durationWeeks: 2,
      startDate: nextWeekday(new Date()).toISOString().slice(0, 10),
    },
    contact: {
      email: `u${Math.random().toString(36).slice(2)}@test.invalid`,
      fullName: "A B", phone: "+16475550111", addressLine: "1 St", city: "Toronto", postalCode: "M5V 2T6",
    },
  });
  const [order] = await db.select().from(orders).where(eq(orders.publicId, publicId)).limit(1);
  createdOrderIds.push(order.id);
  if (order.userId) createdUserIds.push(order.userId);
  return order;
}

async function firstDeliveryOf(order: { id: bigint }) {
  const [row] = await db.select().from(deliveries).where(eq(deliveries.orderId, order.id)).limit(1);
  return row;
}

function farFutureWeekendIso(day: "sat" | "sun"): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 21);
  const target = day === "sun" ? 0 : 6;
  while (d.getUTCDay() !== target) d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().slice(0, 10);
}

function farFutureIso(dow: number): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 21);
  while (d.getUTCDay() !== dow) d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().slice(0, 10);
}

describe("rescheduleDelivery eat-day snap", () => {
  it("snaps Saturday onto that week's Friday trip (no weekend delivery row)", async () => {
    const order = await makeOrder(false);
    const delivery = await firstDeliveryOf(order);
    const sat = farFutureWeekendIso("sat");
    const fri = carryTripDateIso(sat, ["mon", "tue", "wed", "thu", "fri"] as DayOfWeek[])!;
    expect(weekdayKey(parseIsoDateUtc(fri))).toBe("fri");

    const res = await rescheduleDelivery(delivery.publicId, sat, null);
    expect(res.carriedOn).toBe(fri);
    expect(res.merged).toBeTypeOf("boolean");

    const rows = await db.select().from(deliveries).where(eq(deliveries.orderId, order.id));
    expect(rows.some((r) => r.deliveryDate === sat && r.status === "scheduled")).toBe(false);
    const carrier = rows.find((r) => r.deliveryDate === fri && r.status === "scheduled");
    expect(carrier).toBeTruthy();
    expect(coveredDates(carrier!).includes(sat)).toBe(true);
  });

  it("snaps Sunday onto Friday even when weekend add-ons are priced in", async () => {
    const order = await makeOrder(true);
    const delivery = await firstDeliveryOf(order);
    const sun = farFutureWeekendIso("sun");
    const res = await rescheduleDelivery(delivery.publicId, sun, null);
    expect(weekdayKey(parseIsoDateUtc(res.carriedOn))).toBe("fri");
    const [source] = await db.select().from(deliveries).where(eq(deliveries.id, delivery.id));
    expect(source.status).toBe("skipped");
  });
});

describe("rescheduleDelivery for eatingDays / MWF", () => {
  it("snaps Tue onto Mon and allows Wed on-pattern; rejects nothing for Sat (snaps to Fri)", async () => {
    const order = await makeOrder(false, "mwf");
    await db.update(orders).set({ eatingDays: ["mon", "tue", "wed", "fri", "sat", "sun"] }).where(eq(orders.id, order.id));
    const delivery = await firstDeliveryOf(order);

    const tue = farFutureIso(2); // Tuesday
    const tueRes = await rescheduleDelivery(delivery.publicId, tue, null);
    expect(weekdayKey(parseIsoDateUtc(tueRes.carriedOn))).toBe("mon");
    expect(tueRes.carriedOn).toBe(carryTripDateIso(tue, ["mon", "wed", "fri"])!);
  });


  it("merges onto an existing trip instead of rejecting", async () => {
    const order = await makeOrder(false, "mwf");
    await db.update(orders).set({ eatingDays: ["mon", "wed", "thu", "fri"] }).where(eq(orders.id, order.id));
    const all = await db.select().from(deliveries).where(eq(deliveries.orderId, order.id));
    const mon = all.find((d) => weekdayKey(parseIsoDateUtc(d.deliveryDate)) === "mon");
    const dates = new Set(all.map((d) => d.deliveryDate));
    const plusDays = (iso: string, n: number) => {
      const d = parseIsoDateUtc(iso);
      d.setUTCDate(d.getUTCDate() + n);
      return d.toISOString().slice(0, 10);
    };
    // A Monday whose own week also has a Wednesday trip (start date varies with today).
    const laterMon = all.find((d) => weekdayKey(parseIsoDateUtc(d.deliveryDate)) === "mon" && dates.has(plusDays(d.deliveryDate, 2)));
    expect(laterMon).toBeTruthy();
    // Reschedule later Mon trip onto Wed of same week via Thursday eat day
    const thu = (() => {
      const d = parseIsoDateUtc(laterMon!.deliveryDate);
      d.setUTCDate(d.getUTCDate() + 3); // Mon+3 = Thu
      return d.toISOString().slice(0, 10);
    })();
    const res = await rescheduleDelivery(laterMon!.publicId, thu, null);
    expect(res.merged).toBe(true);
    expect(weekdayKey(parseIsoDateUtc(res.carriedOn))).toBe("wed");
    const [carrier] = await db.select().from(deliveries).where(eq(deliveries.deliveryDate, res.carriedOn));
    expect(coveredDates(carrier).includes(thu)).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import { computeAllSwapOptions, validateProposedSwap, type CompositionContext } from "../../menu/meal-validation";
import type { SwapCategory, SwapRow } from "../../menu/swap-rules";
import { portionsByCategory } from "../../menu/pick-size";
import type { TuCategory } from "../../menu/format-tu";

describe("Dynamic provisional swap generation", () => {
  const sabziCat: SwapCategory = { key: "sabzi", pickTu: 1.5, unitType: "weight", unitLabel: "oz", unitSize: 8, maxPicksPerTiffin: null };
  const daalCat: SwapCategory = { key: "daal", pickTu: 1.0, unitType: "weight", unitLabel: "oz", unitSize: 8, maxPicksPerTiffin: null };
  const riceCat: SwapCategory = { key: "rice", pickTu: 1.0, unitType: "weight", unitLabel: "oz", unitSize: 8, maxPicksPerTiffin: null };

  const tuMap = new Map<string, TuCategory>([
    ["sabzi", { tuUnitType: "weight", tuUnitSize: 8, tuUnitLabel: "oz" }],
    ["daal", { tuUnitType: "weight", tuUnitSize: 8, tuUnitLabel: "oz" }],
    ["rice", { tuUnitType: "weight", tuUnitSize: 8, tuUnitLabel: "oz" }],
  ]);

  const items = [
    { category: "sabzi", tuAmount: 1.50, maxTuAmount: null, sortOrder: 0 },
    { category: "sabzi", tuAmount: 1.00, maxTuAmount: null, sortOrder: 1 },
    { category: "sabzi", tuAmount: 0.50, maxTuAmount: null, sortOrder: 2 },
    { category: "daal", tuAmount: 1.50, maxTuAmount: null, sortOrder: 3 },
    { category: "rice", tuAmount: 1.00, maxTuAmount: null, sortOrder: 4 },
  ];

  const composition: CompositionContext = {
    baseCounts: { sabzi: 3, daal: 1, rice: 1 },
    mealSizeItems: items,
    categories: new Map([["sabzi", sabziCat], ["daal", daalCat], ["rice", riceCat]]),
    labels: { sabzi: "Sabzi", daal: "Daal", rice: "Rice" },
  };

  it("Test 1 & 2: Provisional swap removes 12oz, leaving 8oz to get its own valid options", () => {
    // Base options without pending swaps
    const baseOpts = computeAllSwapOptions({
      composition,
      applied: [],
      pairs: [{ fromCategory: "sabzi", toCategory: "daal" }],
    });
    // First sabzi is 12oz (1.5 TU)
    expect(baseOpts[0]!.validBundles[0]?.getNatural).toBe("12oz");

    // With a pending swap of 1 sabzi
    const pendingApplies: SwapRow[] = [{ fromCategory: "sabzi", toCategory: "daal", qtyFrom: 1, qtyTo: 1 }];
    const dynamicOpts = computeAllSwapOptions({
      composition,
      applied: pendingApplies,
      pairs: [{ fromCategory: "sabzi", toCategory: "daal" }],
    });

    // The remaining sabzi is 8oz (1.0 TU), so the swap option should dynamically target 8oz
    expect(dynamicOpts[0]!.validBundles[0]?.getNatural).toBe("8oz");
    expect(dynamicOpts[0]!.giveNatural).toBe("8oz");
  });

  it("Test 3: Multiple pending swaps compute against combined state", () => {
    const pendingApplies: SwapRow[] = [
      { fromCategory: "sabzi", toCategory: "daal", qtyFrom: 1, qtyTo: 1 }, // takes 12oz
      { fromCategory: "sabzi", toCategory: "daal", qtyFrom: 1, qtyTo: 1 }, // takes 8oz
    ];
    const dynamicOpts = computeAllSwapOptions({
      composition,
      applied: pendingApplies,
      pairs: [{ fromCategory: "sabzi", toCategory: "daal" }],
    });

    // The third sabzi is 4oz (0.5 TU)
    expect(dynamicOpts[0]!.validBundles[0]?.getNatural).toBe("4oz");
    expect(dynamicOpts[0]!.giveNatural).toBe("4oz");
  });

  it("Test 4: Undo a swap restores the correct previous state", () => {
    // First swap 12oz
    let pendingApplies: SwapRow[] = [{ fromCategory: "sabzi", toCategory: "daal", qtyFrom: 1, qtyTo: 1 }];
    // Undo it -> back to empty
    pendingApplies = [];
    const revertedOpts = computeAllSwapOptions({
      composition,
      applied: pendingApplies,
      pairs: [{ fromCategory: "sabzi", toCategory: "daal" }],
    });
    // Back to 12oz
    expect(revertedOpts[0]!.validBundles[0]?.getNatural).toBe("12oz");
  });
});

import { afterAll, beforeEach, describe, expect, it, vi } from "vitest";
import { eq, inArray } from "drizzle-orm";
import { db } from "@/db/client";
import { ticketMessages, tickets, users } from "@/db/schema";
import { ForbiddenError, ValidationError } from "@foundry/commons";

const session: { user: { id: string; role: string } | null } = { user: null };
vi.mock("@/lib/auth/session", () => ({ getSession: async () => (session.user ? session : null) }));

const { ticketsService } = await import("../tickets.service");

const seededUserIds: bigint[] = [];

async function seedUser(name: string, role: "user" | "member" | "admin") {
  const [u] = await db.insert(users).values({ email: `u${Math.random().toString(36).slice(2)}@test.invalid`,  name, role }).returning({ id: users.id, publicId: users.publicId });
  seededUserIds.push(u.id);
  return u;
}

function actAs(user: { publicId: string }, role: "user" | "member" | "admin") {
  session.user = { id: user.publicId, role };
}

async function reset() {
  await db.delete(ticketMessages);
  await db.delete(tickets);
  session.user = null;
}

describe("ticketsService", () => {
  beforeEach(reset);

  afterAll(async () => {
    await db.delete(ticketMessages);
    await db.delete(tickets);
    if (seededUserIds.length) await db.delete(users).where(inArray(users.id, seededUserIds));
  });

  it("create inserts an open ticket and a first customer message", async () => {
    const customer = await seedUser("Cust Create", "user");
    actAs(customer, "user");

    const ticket = await ticketsService.create({ subject: "Where is my order?", category: "order", subcategory: "order_missing", body: "It never arrived." });
    expect(ticket.status).toBe("open");
    expect(ticket.raisedBy).toBe(customer.id);

    const messages = await ticketsService.listMessages(ticket.publicId);
    expect(messages).toHaveLength(1);
    expect(messages[0].authorType).toBe("customer");
    expect(messages[0].body).toBe("It never arrived.");
  });

  it("rejects a customer reply on a resolved ticket (no silent reopen)", async () => {
    const customer = await seedUser("Cust Locked", "user");
    const staff = await seedUser("Staff Locked", "admin");

    actAs(customer, "user");
    const ticket = await ticketsService.create({ subject: "Billing", category: "billing", subcategory: "payment_failed", body: "Charged twice." });

    actAs(staff, "admin");
    await ticketsService.changeStatus(ticket.publicId, "resolved");

    actAs(customer, "user");
    await expect(ticketsService.reply(ticket.publicId, "Still wrong")).rejects.toThrow(ForbiddenError);

    const [row] = await db.select().from(tickets).where(eq(tickets.id, ticket.id));
    expect(row.status).toBe("resolved");
  });

  it("rejects a staff reply on a closed ticket", async () => {
    const customer = await seedUser("Cust Closed", "user");
    const staff = await seedUser("Staff Closed", "member");

    actAs(customer, "user");
    const ticket = await ticketsService.create({ subject: "Closed", category: "general", subcategory: "something_else", body: "Done?" });

    actAs(staff, "member");
    await ticketsService.changeStatus(ticket.publicId, "closed");
    await expect(ticketsService.reply(ticket.publicId, "One more thing")).rejects.toThrow(ForbiddenError);
  });

  it("staff reopen (changeStatus to open) clears closedAt and lets replies resume", async () => {
    const customer = await seedUser("Cust Resume", "user");
    const staff = await seedUser("Staff Resume", "admin");

    actAs(customer, "user");
    const ticket = await ticketsService.create({ subject: "Resume", category: "order", subcategory: "order_missing", body: "Where?" });

    actAs(staff, "admin");
    await ticketsService.changeStatus(ticket.publicId, "resolved");
    await ticketsService.changeStatus(ticket.publicId, "open");

    const [reopened] = await db.select().from(tickets).where(eq(tickets.id, ticket.id));
    expect(reopened.status).toBe("open");
    expect(reopened.closedAt).toBeNull();

    actAs(customer, "user");
    await ticketsService.reply(ticket.publicId, "Thanks, still waiting");
    const messages = await ticketsService.listMessages(ticket.publicId);
    expect(messages.at(-1)?.body).toBe("Thanks, still waiting");
  });

  it("allows an image-only reply (empty body with an attachment)", async () => {
    const customer = await seedUser("Cust Img", "user");
    actAs(customer, "user");
    const ticket = await ticketsService.create({ subject: "Photo", category: "order", subcategory: "order_missing", body: "See photo." });
    await ticketsService.reply(ticket.publicId, "", [
      { path: "tickets/x/orig-a.png", thumbUrl: "https://x/thumb-a.png", name: "a.png" },
    ]);
    const messages = await ticketsService.listMessages(ticket.publicId);
    expect(messages.at(-1)?.attachments).toEqual([
      { path: "tickets/x/orig-a.png", thumbUrl: "https://x/thumb-a.png", name: "a.png" },
    ]);
  });

  it("setOpeningAttachments updates the first customer message", async () => {
    const customer = await seedUser("Cust Open Img", "user");
    actAs(customer, "user");
    const ticket = await ticketsService.create({
      subject: "With screenshot",
      category: "order", subcategory: "order_missing",
      body: "See attached.",
    });
    const att = [{ path: "tickets/y/orig-b.png", thumbUrl: "https://x/thumb-b.png", name: "b.png" }];
    await ticketsService.setOpeningAttachments(ticket.publicId, att);
    const messages = await ticketsService.listMessages(ticket.publicId);
    expect(messages[0]?.authorType).toBe("customer");
    expect(messages[0]?.attachments).toEqual(att);
  });

  it("changeStatus to resolved writes a system message and sets closedAt", async () => {
    const customer = await seedUser("Cust Resolve", "user");
    const staff = await seedUser("Staff Resolve", "member");

    actAs(customer, "user");
    const ticket = await ticketsService.create({ subject: "Catering quote", category: "catering", subcategory: "", body: "Need a quote." });

    actAs(staff, "member");
    await ticketsService.changeStatus(ticket.publicId, "resolved");

    const messages = await ticketsService.listMessages(ticket.publicId);
    const system = messages.find((m) => m.authorType === "system");
    expect(system).toBeDefined();
    expect(system?.body).toBe("Status: open → resolved");

    const [row] = await db.select().from(tickets).where(eq(tickets.id, ticket.id));
    expect(row.status).toBe("resolved");
    expect(row.closedAt).not.toBeNull();
  });

  it("a different customer cannot read or reply to another customer's ticket", async () => {
    const owner = await seedUser("Cust Owner", "user");
    const intruder = await seedUser("Cust Intruder", "user");

    actAs(owner, "user");
    const ticket = await ticketsService.create({ subject: "Private", category: "general", subcategory: "something_else", body: "Confidential." });

    actAs(intruder, "user");
    await expect(ticketsService.listMessages(ticket.publicId)).rejects.toThrow(ForbiddenError);
    await expect(ticketsService.reply(ticket.publicId, "Let me peek")).rejects.toThrow(ForbiddenError);
  });
});

/**
 * Integration: wallet coins awarded when an order becomes active.
 *
 * Tests two call sites:
 *   1. activateOrder(publicId) — waitlisted → active
 *   2. createOrder — immediate active (zone match)
 *
 * Uses the live DB; cleans up all own rows in afterAll.
 */
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq, inArray, ne } from "drizzle-orm";
import { nextWeekday } from "@foundry/commons";

const { db } = await import("@/db/client");
const { orders, orderActivities, payments, ledgerEntries, walletLedger, eventPayout, users } =
  await import("@/db/schema");
const { loadCatalogSnapshot } = await import("@/lib/catalog/load");
const svc = await import("../orders.service");

// Phones in 555 test range, unlikely to collide with seed fixtures
const TEST_PHONE = "+16475550019";
const TEST_PHONE_2 = "+16475550020";
const TEST_PHONE_3 = "+16475550021";
const TEST_PHONE_4 = "+16475550022";
const TEST_PHONE_5 = "+16475550023";

const TEST_PHONES = [TEST_PHONE, TEST_PHONE_2, TEST_PHONE_3, TEST_PHONE_4, TEST_PHONE_5];

async function cleanup() {
  // Unconditional wallet clear first: a row leaked by a failed test (before the
  // scoped ids resolve) FK-blocks every later suite's `delete users`. Only the
  // two wallet suites produce these tables, so a blanket delete is safe.
  await db.delete(walletLedger);
  await db.delete(eventPayout);
  // Delete wallet ledger entries for our test users first (FK order)
  const testUsers = await db
    .select({ id: users.id })
    .from(users)
    .where(inArray(users.phone, TEST_PHONES));

  for (const u of testUsers) {
    await db.delete(walletLedger).where(eq(walletLedger.userId, u.id));
  }

  // Clean orders and their dependents created by our test phones
  // We identify orders by their payments/activities then delete
  const ourOrders = await db
    .select({ id: orders.id, publicId: orders.publicId })
    .from(orders)
    .innerJoin(users, eq(orders.userId, users.id))
    .where(inArray(users.phone, TEST_PHONES));

  for (const o of ourOrders) {
    await db.delete(ledgerEntries).where(eq(ledgerEntries.orderId, o.id));
    await db.delete(orderActivities).where(eq(orderActivities.orderId, o.id));
    await db.delete(payments).where(eq(payments.orderId, o.id));
    await db.delete(orders).where(eq(orders.id, o.id));
  }

  // Delete test users
  await db.delete(users).where(inArray(users.phone, TEST_PHONES));
}

