export type Tx = Parameters<Parameters<typeof db.transaction>[0]>[0];
type Order = typeof orders.$inferSelect;
type Delivery = typeof deliveries.$inferSelect;

const WEEKEND = new Set(["sat", "sun"]);

/** ISO date `n` days before `dateIso` — UTC date math, same style as nextDeliveryDateAfter. */
function isoDaysBefore(dateIso: string, n: number): string {
  const d = parseIsoDateUtc(dateIso);
  d.setUTCDate(d.getUTCDate() - n);
  return d.toISOString().slice(0, 10);
}

/**
 * Carries one delivery's applied swaps onto its replacement. Used by reschedule,
 * where the SAME day moves: a per-day override the customer made must survive
 * the move rather than snapping back to the subscription default.
 */
export async function copyDeliverySwaps(
  tx: Tx,
  fromDeliveryId: bigint,
  toDeliveryId: bigint,
  /** Date a NULL for_date resolves to on the copy. Pass the source's own date whenever the copy's
   *  own date differs from it, or the swap would silently move to another eating day. */
  resolveNullTo?: string,
): Promise<void> {
  const rows = await tx.select().from(deliveryCategorySwaps)
    .where(eq(deliveryCategorySwaps.deliveryId, fromDeliveryId)).orderBy(asc(deliveryCategorySwaps.id));
  if (rows.length === 0) return;
  await tx.insert(deliveryCategorySwaps).values(rows.map((r) => ({
    deliveryId: toDeliveryId,
    fromCategory: r.fromCategory,
    toCategory: r.toCategory,
    qtyFrom: r.qtyFrom,
    qtyTo: r.qtyTo,
    fromRow: r.fromRow,
    receiveTu: r.receiveTu,
    forDate: r.forDate ?? resolveNullTo ?? null,
  })));
}

/**
 * Materializes the delivery-drop rows for an order. Tiffin total is unaffected by this
 * function (pricing already fixed order.tiffinCount at checkout using deliveryDays.length,
 * weekend days included) — this only decides how that total is DISTRIBUTED across rows.
 *
 * There is no physical Saturday/Sunday route: a weekend add-on ships with the same week's
 * Friday instead, so a "sat"/"sun" entry never gets its own row — it adds `persons` tiffin
 * units onto that Friday's row (tiffinUnits) instead. Friday is always a base delivery day
 * (both "mwf" and the 5-day pattern include it), so the Friday row it bundles onto is
 * guaranteed to already exist earlier in the same walk — the fallback branch below is a
 * defensive backstop, not the expected path, so a bundle target is never silently dropped.
 *
 * Idempotent: returns 0 and inserts nothing if the order already has deliveries. Caller
 * supplies the transaction; this is a write path only, called from both routes that put an
 * order into "active".
 */
export async function materializeDeliveries(tx: Tx, order: Order): Promise<number> {
  const [existing] = await tx.select({ id: deliveries.id }).from(deliveries)
    .where(eq(deliveries.orderId, order.id)).limit(1);
  if (existing) return 0;

  const [freq] = await tx.select({ key: deliveryFrequencies.key, daysPerWeek: deliveryFrequencies.daysPerWeek, weekdays: deliveryFrequencies.weekdays })
    .from(deliveryFrequencies).where(eq(deliveryFrequencies.id, order.frequencyId)).limit(1);
  if (!freq) throw new ValidationError("Delivery frequency not found");

  type Row = { deliveryDate: string; tiffinUnits: number; coversDates?: string[] };
  const rows: Row[] = [];

  if (order.eatingDays?.length) {
    // Delivery days come from the frequency row alone; eating days (weekends included)
    // ride the nearest earlier delivery, so a trip's tiffinUnits is its carried days.
    const week = planWeek(
      orderDeliveryDays({ frequencyKey: freq.key, weekdays: freq.weekdays as DayOfWeek[] | null, includeSaturday: false, includeSunday: false }),
      order.eatingDays as DayOfWeek[],
    );
    if (!week) throw new ValidationError("An eating day falls before the first delivery day of this frequency");
    const unitsByDay = new Map(week.map((t) => [t.day, t.units]));
    const dates = subscriptionDeliveryDates({ startDate: order.startDate, durationWeeks: order.durationWeeks, deliveryDays: week.map((t) => t.day) });
    const carriedByDay = new Map(week.map((t) => [t.day, t.days]));
    for (const d of dates) {
      rows.push({
        deliveryDate: d.dateIso,
        tiffinUnits: unitsByDay.get(d.dayOfWeek)! * order.persons,
        coversDates: tripCoverage(d.dateIso, d.dayOfWeek, carriedByDay.get(d.dayOfWeek)!),
      });
    }
    const total = rows.reduce((n, r) => n + r.tiffinUnits, 0);
    if (total !== order.tiffinCount) {
      throw new ValidationError(`Delivery plan carries ${total} tiffins but the order is priced for ${order.tiffinCount}`);
    }
  } else {
    const deliveryDays = orderDeliveryDays({
      frequencyKey: freq.key,
      weekdays: freq.weekdays as DayOfWeek[] | null,
      includeSaturday: order.includeSaturday,
      includeSunday: order.includeSunday,
    });

    // orderDeliveryDays hardcodes 3 weekdays for "mwf" and 5 otherwise, independent of the
    // frequency row. If an admin edits daysPerWeek, pricing's tiffinCount and the row count
    // silently diverge — refuse to create a subscription whose rows contradict its price.
    const baseDays = deliveryDays.filter((d) => !WEEKEND.has(d)).length;
    if (baseDays !== freq.daysPerWeek) {
      throw new ValidationError(
        `Frequency "${freq.key}" declares ${freq.daysPerWeek} days/week but resolves to ${baseDays}`,
      );
    }

    const dates = subscriptionDeliveryDates({
      startDate: order.startDate,
      durationWeeks: order.durationWeeks,
      deliveryDays,
    });

    const rowByDate = new Map<string, Row>();
    for (const d of dates) {
      if (d.dayOfWeek === "sat" || d.dayOfWeek === "sun") {
        const fridayIso = isoDaysBefore(d.dateIso, d.dayOfWeek === "sat" ? 1 : 2);
        const friday = rowByDate.get(fridayIso);
        if (friday) {
          friday.tiffinUnits += order.persons;
          continue;
        }
        // Shouldn't happen (Friday is always a base day) — don't drop a real customer's
        // tiffin over it, just give the weekend day its own row instead of merging.
      }
      const newRow: Row = { deliveryDate: d.dateIso, tiffinUnits: order.persons };
      rows.push(newRow);
      rowByDate.set(d.dateIso, newRow);
    }
  }

  const { timezone, cutoffHour } = await getAppSettings();
  await tx.insert(deliveries).values(rows.map((r) => ({
    orderId: order.id,
    deliveryDate: r.deliveryDate,
    status: "scheduled" as const,
    cutoffAt: cutoffMsFor(r.deliveryDate, cutoffHour, timezone),
    tiffinUnits: r.tiffinUnits,
    coversDates: r.coversDates ?? null,
  })));
  return rows.length;
}

/**
 * Visible deliveries for an order within [from, until] (inclusive), ordered by date.
 * Only `status = 'scheduled'` rows are visible — paused/skipped/cancelled rows vanish.
 * Read-only: this must NEVER reconcile or write. Callers (grid, selection validation) rely
 * on that to run safely inside async Server Components.
 */
export async function visibleDeliveries(orderId: bigint, from: string, until: string): Promise<Delivery[]> {
  return db.select().from(deliveries).where(and(
    eq(deliveries.orderId, orderId),
    eq(deliveries.status, "scheduled"),
    gte(deliveries.deliveryDate, from),
    lte(deliveries.deliveryDate, until),
  )).orderBy(asc(deliveries.deliveryDate));
}

/**
 * Every delivery row for an order (all statuses, originals and make-ups alike), for the admin
 * panel. Unlike visibleDeliveries this is not customer-facing and must not hide paused/skipped/
 * cancelled rows. Read-only: never reconciles.
 */
export async function listDeliveries(orderId: bigint): Promise<Delivery[]> {
  return db.select().from(deliveries).where(eq(deliveries.orderId, orderId)).orderBy(asc(deliveries.deliveryDate));
}

/** Rows past their snapshotted cutoff are immutable. cutoff_at is never re-derived. */
export function assertMutable(row: Delivery): void {
  if (Date.now() > row.cutoffAt) {
    throw new ValidationError("This delivery is locked — its cutoff has passed");
  }
}

function assertOriginal(row: Delivery): void {
  // A make-up cannot itself be skipped or paused: that would spawn a make-up of a make-up and
  // grow the tail without bound.
  if (row.makeupForDeliveryId !== null) {
    throw new ValidationError("A make-up delivery cannot be skipped or paused");
  }
}

// Exported so category-swaps.service.ts can reuse this pre-lock/load shape rather
// than duplicating it.
export async function loadByPublicId(tx: Tx, publicId: string): Promise<Delivery> {
  const [row] = await tx.select().from(deliveries).where(eq(deliveries.publicId, publicId)).limit(1);
  if (!row) throw new ValidationError("Delivery not found");
  return row;
}

/** Pre-lock lookup: only orderId, so we know what to lock before trusting any other column. */
export async function loadOrderIdByPublicId(tx: Tx, publicId: string): Promise<bigint> {
  const [row] = await tx.select({ orderId: deliveries.orderId }).from(deliveries)
    .where(eq(deliveries.publicId, publicId)).limit(1);
  if (!row) throw new ValidationError("Delivery not found");
  return row.orderId;
}

/** Pre-lock lookup by the order's own public_id, so we know what to lock before reading anything else. */
async function loadOrderIdByOrderPublicId(tx: Tx, orderPublicId: string): Promise<bigint> {
  const [row] = await tx.select({ id: orders.id }).from(orders).where(eq(orders.publicId, orderPublicId)).limit(1);
  if (!row) throw new ValidationError("Order not found");
  return row.id;
}

/**
 * Marks every future scheduled original in [from, until] as paused. Make-ups (non-null
 * makeupForDeliveryId) are immutable and simply excluded, never a reason to reject. Rows already
 * past their own snapshotted cutoff are likewise excluded, not rejected — a range that lands
 * entirely in the past, or matches nothing at all, is a successful no-op returning 0.
 */
export async function pauseRange(orderPublicId: string, from: string, until: string): Promise<number> {
  const isoDateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!isoDateRegex.test(from) || !isoDateRegex.test(until)) {
    throw new ValidationError("Pause dates must be ISO YYYY-MM-DD");
  }
  if (from > until) throw new ValidationError("Pause start must be on or before pause end");

  let orderId: bigint;
  let pausedRows: OptimoSyncedRow[] = [];
  const updatedCount = await db.transaction(async (tx) => {
    orderId = await loadOrderIdByOrderPublicId(tx, orderPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);

    const updated = await tx.update(deliveries)
      .set({ status: "paused" })
      .where(and(
        eq(deliveries.orderId, orderId),
        eq(deliveries.status, "scheduled"),
        isNull(deliveries.makeupForDeliveryId),
        gte(deliveries.deliveryDate, from),
        lte(deliveries.deliveryDate, until),
        gt(deliveries.cutoffAt, Date.now()),
      ))
      .returning({ id: deliveries.id, publicId: deliveries.publicId, routeSyncedAt: deliveries.routeSyncedAt });
    pausedRows = updated;
    return updated.length;
  });
  await deleteFromOptimoRouteBestEffort(pausedRows);
  if (updatedCount > 0) publishAnalyticsLive();
  return updatedCount;
}

/**
 * Reverts paused rows to scheduled. Ignores 'skipped' rows by design — skip is a deliberate
 * single-delivery act that only an explicit unskip undoes.
 *
 * Plain resume (no `fromDate`): every FUTURE paused row (cutoff not passed) comes back.
 * Resume-from (`fromDate`): only paused days on/after `fromDate` (with a future cutoff) come back.
 * Vacation has no entry point today (move-only deliveries); this stays for its redesign.
 */
export async function resumeOrder(orderPublicId: string, fromDate?: string): Promise<number> {
  if (fromDate && !/^\d{4}-\d{2}-\d{2}$/.test(fromDate)) {
    throw new ValidationError("Resume date must be ISO YYYY-MM-DD");
  }
  let orderId: bigint;
  const updatedCount = await db.transaction(async (tx) => {
    orderId = await loadOrderIdByOrderPublicId(tx, orderPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);

    const conds = [
      eq(deliveries.orderId, orderId),
      eq(deliveries.status, "paused"),
      gt(deliveries.cutoffAt, Date.now()),
    ];
    if (fromDate) conds.push(gte(deliveries.deliveryDate, fromDate));

    const updated = await tx.update(deliveries)
      .set({ status: "scheduled" })
      .where(and(...conds))
      .returning({ id: deliveries.id });
    return updated.length;
  });
  publishAnalyticsLive();
  return updatedCount;
}

/**
 * Marks a scheduled delivery as not delivered (a failed or never-confirmed drop). Customers can't
 * hold days any more; each tiffin on the row stays movable once with rescheduleDelivery.
 */
export async function skipDelivery(
  deliveryPublicId: string,
  actorId: bigint | null,
  opts: { bypassCutoffLock?: boolean } = {},
): Promise<{ missedDates: string[] }> {
  let orderId: bigint;
  let syncedRow: OptimoSyncedRow | null = null;
  let missedDates: string[] = [];
  await db.transaction(async (tx) => {
    orderId = await loadOrderIdByPublicId(tx, deliveryPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);
    // Re-read post-lock: a concurrent request may have mutated this row while we waited.
    const row = await loadByPublicId(tx, deliveryPublicId);
    assertOriginal(row);
    // The cutoff lock protects a customer from self-service-cancelling too late — it
    // does not apply to the system's own post-cutoff reconciliation (pullCompletions),
    // which by design only ever calls this once the cutoff has already passed.
    if (!opts.bypassCutoffLock) assertMutable(row);
    if (row.status !== "scheduled") throw new ValidationError(`Cannot skip a ${row.status} delivery`);
    const updated = await tx.update(deliveries).set({ status: "skipped" })
      .where(and(eq(deliveries.id, row.id), eq(deliveries.status, "scheduled")))
      .returning({ id: deliveries.id });
    if (updated.length === 0) throw new ValidationError(`Cannot skip a ${row.status} delivery`);
    missedDates = coveredDates(row);
    await tx.insert(orderActivities).values({
      orderId, deliveryId: row.id, type: "skipped",
      note: row.coversDates ? `Missed days: ${missedDates.join(", ")}` : null,
      createdBy: actorId,
    });
    syncedRow = { publicId: row.publicId, routeSyncedAt: row.routeSyncedAt };
  });
  await deleteFromOptimoRouteBestEffort([syncedRow!]);
  publishAnalyticsLive();
  return { missedDates };
}

// Self-join alias used only to test "does a make-up already exist for this row" — a correlated
// NOT EXISTS written via a bare `${deliveries}` interpolation is not guaranteed to alias
// correctly in Drizzle's raw sql tag, so this uses a real join alias instead.
const existingMakeup = alias(deliveries, "existing_makeup");

/** A cancelled/skipped row that had already been synced to OptimoRoute — the caller's cue to
 *  also delete it there. `routeSyncedAt` null means OptimoRoute never had this stop. */
export type OptimoSyncedRow = { publicId: string; routeSyncedAt: number | null };

/**
 * Best-effort OptimoRoute cleanup for a row that just left the schedule. Never throws: a stop
 * OptimoRoute already dropped, or an API hiccup, must not block the DB change that already
 * committed — this only stops printing a label for a delivery nobody is making anymore.
 */
export async function deleteFromOptimoRouteBestEffort(rows: OptimoSyncedRow[]): Promise<void> {
  for (const row of rows) {
    if (row.routeSyncedAt == null) continue;
    try {
      await deleteOrder(row.publicId);
    } catch (e) {
      log.error({ err: e, publicId: row.publicId }, "optimoroute delete-on-cancel failed");
    }
  }
}

/**
 * Marks every scheduled/paused row (originals and make-ups alike) cancelled. Terminal: cancel()
 * never reactivates, so there is no corresponding "uncancel". Caller owns the transaction/lock —
 * this runs inside orders.service.ts cancel()'s own advisory-locked tx.
 *
 * Returns the cancelled rows' publicId/routeSyncedAt (not just a count) so the caller can clean
 * them up on OptimoRoute after the transaction commits — an external API call has no place
 * inside a DB transaction.
 */
export async function cancelDeliveries(tx: Tx, orderId: bigint): Promise<OptimoSyncedRow[]> {
  return tx.update(deliveries).set({ status: "cancelled" })
    .where(and(eq(deliveries.orderId, orderId), inArray(deliveries.status, ["scheduled", "paused"])))
    .returning({ publicId: deliveries.publicId, routeSyncedAt: deliveries.routeSyncedAt });
}

/**
 * No future non-cancelled rows and no unmaterialized make-up debt -> the subscription is done.
 * A delivered original still reads status='scheduled' (spec 2 has no 'delivered' status), so
 * "no scheduled/paused rows" is the WRONG completion test — it fires the moment every original
 * is skipped/paused (even with future cutoffs, i.e. live debt) and never fires on a happy-path
 * subscription that ran its full course (its past originals stay 'scheduled' forever). The
 * correct test: no row dated today-or-later that isn't cancelled, AND no missed original
 * (paused|skipped, makeup_for_delivery_id IS NULL) still lacking a make-up.
 */
export async function maybeComplete(orderId: bigint): Promise<boolean> {
  return db.transaction(async (tx) => {
    // Lock before any read it guards on: without this, a concurrent reconcileMakeups can insert
    // a fresh make-up (new scheduled debt) between our reads and the update below, and we'd still
    // flip the order to "completed" out from under an outstanding delivery.
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);

    const { timezone } = await getAppSettings();
    const today = zonedDateIso(Date.now(), timezone);

    const [{ n: outstanding }] = await tx.select({ n: sql<number>`count(*)::int` }).from(deliveries).where(and(
      eq(deliveries.orderId, orderId),
      sql`${deliveries.status} != 'cancelled'`,
      gte(deliveries.deliveryDate, today),
    ));
    if (outstanding > 0) return false;

    // Same aliased leftJoin + isNull anti-join formulation as reconcileMakeups — debt counts
    // regardless of cutoff, since a future-cutoff skipped row will still spawn a make-up later.
    const [{ n: debt }] = await tx.select({ n: sql<number>`count(*)::int` })
      .from(deliveries)
      .leftJoin(existingMakeup, eq(existingMakeup.makeupForDeliveryId, deliveries.id))
      .where(and(
        eq(deliveries.orderId, orderId),
        isNull(deliveries.makeupForDeliveryId),
        inArray(deliveries.status, ["paused", "skipped"]),
        isNull(deliveries.mergedIntoDeliveryId),
        isNull(existingMakeup.id),
      ));
    if (debt > 0) return false;

    const updated = await tx.update(orders).set({ status: "completed" })
      .where(and(eq(orders.id, orderId), eq(orders.status, "active")))
      .returning({ id: orders.id });
    return updated.length > 0;
  });
}

/** First ISO date strictly after `afterIso` whose weekday is in `deliveryDays`. */
export function nextDeliveryDateAfter(afterIso: string, deliveryDays: Set<string>): string {
  const d = parseIsoDateUtc(afterIso);
  for (let guard = 0; guard < 30; guard++) {
    d.setUTCDate(d.getUTCDate() + 1);
    if (deliveryDays.has(weekdayKey(d))) return d.toISOString().slice(0, 10);
  }
  throw new ValidationError("Could not find a make-up slot within 30 days");
}

async function orderDeliveryDaySet(tx: Tx, order: Order): Promise<Set<string>> {
  const [freq] = await tx.select({ key: deliveryFrequencies.key, weekdays: deliveryFrequencies.weekdays }).from(deliveryFrequencies)
    .where(eq(deliveryFrequencies.id, order.frequencyId)).limit(1);
  return new Set(orderDeliveryDays({
    frequencyKey: freq!.key,
    weekdays: freq!.weekdays as DayOfWeek[] | null,
    includeSaturday: !order.eatingDays?.length && order.includeSaturday,
    includeSunday: !order.eatingDays?.length && order.includeSunday,
  }));
}

/** Extras follow the trip; a single-day trip re-dated to the picked eat day carries them there. */
function carriedExtras(extras: string[], eatingDateIso: string | null, own: string[]): string[] {
  return eatingDateIso && own.length === 1 ? extras.map(() => eatingDateIso) : extras;
}

async function replaceExtras(tx: Tx, deliveryId: bigint, eatDates: string[]): Promise<void> {
  await tx.delete(deliveryExtraTiffins).where(eq(deliveryExtraTiffins.deliveryId, deliveryId));
  if (eatDates.length) await tx.insert(deliveryExtraTiffins).values(eatDates.map((eatDate) => ({ deliveryId, eatDate })));
}

/** Drops the swaps that apply to `eatDate`: that day no longer rides this delivery. */
async function dropDeliverySwapsForDate(tx: Tx, deliveryId: bigint, tripDate: string, eatDate: string): Promise<void> {
  const rows = await tx.select({ id: deliveryCategorySwaps.id, forDate: deliveryCategorySwaps.forDate }).from(deliveryCategorySwaps).where(eq(deliveryCategorySwaps.deliveryId, deliveryId));
  const gone = rows.filter((r) => swapAppliesTo(r.forDate, tripDate, eatDate)).map((r) => r.id);
  if (gone.length) await tx.delete(deliveryCategorySwaps).where(inArray(deliveryCategorySwaps.id, gone));
}

/**
 * A row whose tiffins all left (merged into another trip, or replaced by a make-up) still owns
 * its date under deliveries_order_date_unique but carries nothing, which used to block every
 * later move onto that day. A move landing there revives it as a fresh, empty scheduled trip.
 */
async function reviveIfEmptied(tx: Tx, row: Delivery, cutoffAt: number): Promise<Delivery> {
  if (row.status === "scheduled") return row;
  const [child] = await tx.select({ id: deliveries.id }).from(deliveries).where(eq(deliveries.makeupForDeliveryId, row.id)).limit(1);
  if (row.mergedIntoDeliveryId == null && !child) return row;
  // The make-up keeps its tiffin but stops pointing here; delivery_moves still records the move and keeps it locked.
  if (child) await tx.update(deliveries).set({ makeupForDeliveryId: null }).where(eq(deliveries.id, child.id));
  const [revived] = await tx.update(deliveries).set({
    status: "scheduled", cutoffAt, mergedIntoDeliveryId: null, coversDates: [], tiffinUnits: 0,
    routeDriverSerial: null, routeDriverName: null, routeStopNumber: null, routeSyncedAt: null,
    optimoCompletionStatus: null, optimoCompletedAt: null, optimoCompletionNote: null,
  }).where(eq(deliveries.id, row.id)).returning();
  await replaceExtras(tx, row.id, []);
  await tx.delete(deliveryCategorySwaps).where(eq(deliveryCategorySwaps.deliveryId, row.id));
  return revived!;
}

/**
 * Moves a WHOLE trip onto `targetDate` (a delivery weekday): payment-shift, re-delivery, a
 * single-tiffin reschedule. If a SCHEDULED trip already sits on targetDate
 * the tiffins merge into it (units add, coverage unions); otherwise a make-up row is inserted.
 * A single-tiffin trip moved to another eat day (`eatingDateIso`) becomes that day's tiffin and
 * takes that day's menu, so its old swaps stay behind. Never creates weekend delivery rows.
 */
async function moveTrip(
  tx: Tx,
  source: Delivery,
  targetDate: string,
  targetCutoff: number,
  eatingDateIso: string | null,
  persons: number,
  enforceCaps = true,
): Promise<{ id: bigint; merged: boolean; coversDates: string[] }> {
  const own = coveredDates(source);
  const carried = eatingDateIso && own.length === 1 ? [eatingDateIso] : own;
  const relabel = carried.length === 1 && own.length === 1 && carried[0] !== own[0];
  const [found] = await tx.select().from(deliveries)
    .where(and(eq(deliveries.orderId, source.orderId), eq(deliveries.deliveryDate, targetDate))).limit(1);
  const target = found && (await reviveIfEmptied(tx, found, targetCutoff));
  // Legacy rows (no covers_dates) keep their stored units: a bundled Friday must not drop to one day.
  const srcExtraDates = (await loadExtraDates(tx, [source.id])).get(source.id) ?? [];
  const movingExtras = carriedExtras(srcExtraDates, eatingDateIso, own);
  const explicit = (d: Delivery, extraCount: number) => (d.coversDates ? (coveredDates(d).length + extraCount) * Math.max(1, persons) : d.tiffinUnits);
  // Swaps written for the trip's own date (NULL for_date) must follow the day they were for.
  const nullFollows = source.coversDates || eatingDateIso == null ? source.deliveryDate : eatingDateIso;

  if (!target) {
    const covers = carried;
    const [inserted] = await tx.insert(deliveries).values({
      orderId: source.orderId,
      deliveryDate: targetDate,
      status: "scheduled",
      cutoffAt: targetCutoff,
      makeupForDeliveryId: source.id,
      tiffinUnits: source.coversDates ? (covers.length + movingExtras.length) * Math.max(1, persons) : source.tiffinUnits,
      coversDates: source.coversDates || eatingDateIso ? covers : null,
    }).returning({ id: deliveries.id });
    await replaceExtras(tx, inserted.id, movingExtras);
    await replaceExtras(tx, source.id, []);
    if (!relabel) await copyDeliverySwaps(tx, source.id, inserted.id, source.coversDates ? source.deliveryDate : (eatingDateIso ?? undefined));
    return { id: inserted.id, merged: false, coversDates: covers };
  }

  if (target.status !== "scheduled") throw new ValidationError("You already have a delivery on that day");
  const incoming = new Map<string, number>();
  for (const c of [...carried, ...movingExtras]) incoming.set(c, (incoming.get(c) ?? 0) + 1);
  const targetExtras = (await loadExtraDates(tx, [target.id])).get(target.id) ?? [];
  const blocked = enforceCaps ? mergeBlockReason(dateCounts(target, targetExtras), incoming) : null;
  if (blocked) throw new ValidationError(blocked);
  const merged = new Map(dateCounts(target, targetExtras));
  for (const [k, v] of incoming) merged.set(k, (merged.get(k) ?? 0) + v);
  const { covers, extras } = countsToCoverage(merged);
  // Units add even when coverage overlaps (moving Wed's tiffin onto a Fri that already eats Fri):
  // the customer paid for both tiffins, the doubled day is recorded in delivery_extra_tiffins.
  await tx.update(deliveries).set({
    tiffinUnits: explicit(source, srcExtraDates.length) + target.tiffinUnits,
    coversDates: covers,
  }).where(eq(deliveries.id, target.id));
  await replaceExtras(tx, target.id, extras);
  await replaceExtras(tx, source.id, []);
  if (!relabel) await copyDeliverySwaps(tx, source.id, target.id, nullFollows);
  await tx.update(deliveries).set({ mergedIntoDeliveryId: target.id }).where(eq(deliveries.id, source.id));
  return { id: target.id, merged: true, coversDates: covers };
}

/**
 * One tiffin leaves a trip that carries several: eaten on `fromEat`, it becomes a tiffin eaten
 * on `toEat`, riding the trip on `targetDate` (possibly the same trip) with that day's menu.
 * The source keeps its status and every other tiffin. A scheduled trip already on targetDate
 * takes it within the 3-tiffin cap; otherwise a new row is inserted (not a make-up: the source
 * is still a live trip).
 */
async function moveOneTiffin(
  tx: Tx,
  source: Delivery,
  fromEat: string,
  toEat: string,
  targetDate: string,
  targetCutoff: number,
  persons: number,
): Promise<{ id: bigint; merged: boolean }> {
  const per = Math.max(1, persons);
  const srcCounts = dateCounts(source, (await loadExtraDates(tx, [source.id])).get(source.id) ?? []);
  const writeCounts = async (id: bigint, counts: Map<string, number>) => {
    const { covers, extras } = countsToCoverage(counts);
    await tx.update(deliveries).set({ coversDates: covers, tiffinUnits: tiffinTotal(counts) * per }).where(eq(deliveries.id, id));
    await replaceExtras(tx, id, extras);
  };
  const leftSource = shiftTiffin(srcCounts, fromEat, null);
  const dropSwaps = () => (leftSource.has(fromEat) ? Promise.resolve() : dropDeliverySwapsForDate(tx, source.id, source.deliveryDate, fromEat));

  if (targetDate === source.deliveryDate) {
    if (source.status !== "scheduled") throw new ValidationError("This delivery isn't going out. Pick another day.");
    await writeCounts(source.id, shiftTiffin(srcCounts, fromEat, toEat));
    await dropSwaps();
    return { id: source.id, merged: true };
  }

  const [found] = await tx.select().from(deliveries)
    .where(and(eq(deliveries.orderId, source.orderId), eq(deliveries.deliveryDate, targetDate))).limit(1);
  const target = found && (await reviveIfEmptied(tx, found, targetCutoff));
  let targetId: bigint;
  if (target) {
    if (target.status !== "scheduled" || target.mergedIntoDeliveryId) throw new ValidationError("You already have a delivery on that day");
    const targetCounts = dateCounts(target, (await loadExtraDates(tx, [target.id])).get(target.id) ?? []);
    const blocked = mergeBlockReason(targetCounts, new Map([[toEat, 1]]));
    if (blocked) throw new ValidationError(blocked);
    await writeCounts(target.id, shiftTiffin(targetCounts, null, toEat));
    targetId = target.id;
  } else {
    const [inserted] = await tx.insert(deliveries).values({
      orderId: source.orderId,
      deliveryDate: targetDate,
      status: "scheduled",
      cutoffAt: targetCutoff,
      tiffinUnits: per,
      coversDates: [toEat],
    }).returning({ id: deliveries.id });
    targetId = inserted.id;
  }
  await writeCounts(source.id, leftSource);
  await dropSwaps();
  return { id: targetId, merged: !!target };
}

/**
 * Runs when staff approve an e-transfer: trips whose date passed while payment was unconfirmed
 * are moved (whole, coverage kept) to the next plan weekdays after the current tail. Past-dated
 * trips are found by date, so a second run finds nothing. Caller owns the tx and should delete
 * the returned stops from OptimoRoute after commit.
 */
export async function shiftMissedDeliveries(
  tx: Tx,
  orderId: bigint,
  actorId: bigint | null,
): Promise<OptimoSyncedRow[]> {
  const [order] = await tx.select().from(orders).where(eq(orders.id, orderId)).limit(1);
  if (!order) return [];

  const { timezone, cutoffHour } = await getAppSettings();
  const today = zonedDateIso(Date.now(), timezone);

  const missed = await tx.select().from(deliveries).where(and(
    eq(deliveries.orderId, orderId),
    eq(deliveries.status, "scheduled"),
    isNull(deliveries.mergedIntoDeliveryId),
    sql`${deliveries.deliveryDate} < ${today}`,
  )).orderBy(asc(deliveries.deliveryDate));
  if (missed.length === 0) return [];

  const weekdays = new Set([...(await orderDeliveryDaySet(tx, order))].filter((d) => d !== "sat" && d !== "sun"));
  const yesterday = parseIsoDateUtc(today);
  yesterday.setUTCDate(yesterday.getUTCDate() - 1);
  const floor = yesterday.toISOString().slice(0, 10);

  const stops: OptimoSyncedRow[] = [];
  for (const row of missed) {
    const [{ max }] = await tx.select({ max: sql<string | null>`max(${deliveries.deliveryDate})` })
      .from(deliveries)
      .where(and(eq(deliveries.orderId, orderId), eq(deliveries.status, "scheduled"), isNull(deliveries.mergedIntoDeliveryId)));
    const tail = max && max > floor ? max : floor;
    const target = nextDeliveryDateAfter(tail, weekdays);

    await tx.update(deliveries).set({ status: "skipped" }).where(eq(deliveries.id, row.id));
    const moved = await moveTrip(tx, row, target, cutoffMsFor(target, cutoffHour, timezone), null, order.persons);
    await tx.insert(orderActivities).values({
      orderId, deliveryId: moved.id, type: "pool_scheduled", createdBy: actorId,
      note: `Missed ${row.deliveryDate} while payment was unconfirmed; moved to ${target}`,
    });
    stops.push({ publicId: row.publicId, routeSyncedAt: row.routeSyncedAt });
  }
  return stops;
}

/**
 * Reschedule moves ONE eating day's tiffin, never a whole bundle. The customer picks the day
 * they want to EAT it (`eatingDateIso`); it snaps to its carrying trip (nearest earlier-or-equal
 * plan weekday — weekends ride Friday) and from then on it IS that day's tiffin: that day's
 * menu, that day's meal picks. All cutoff / past checks use the carrying trip; a trip may carry
 * at most 3 tiffins. Never writes a Saturday/Sunday delivery row.
 *
 * `sourceEatDate` says WHICH eating day's tiffin leaves (required when the trip carries more
 * than one day). The trip keeps delivering (or stays on hold with) everything else. A tiffin
 * that was itself moved in can't move again; the day's own tiffin still can.
 */
export async function rescheduleDelivery(
  deliveryPublicId: string,
  eatingDateIso: string,
  actorId: bigint | null,
  sourceEatDate: string | null = null,
): Promise<{ merged: boolean; carriedOn: string }> {
  const isoDateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!isoDateRegex.test(eatingDateIso)) throw new ValidationError("Reschedule date must be ISO YYYY-MM-DD");
  if (sourceEatDate != null && !isoDateRegex.test(sourceEatDate)) throw new ValidationError("Source date must be ISO YYYY-MM-DD");

  let oldStop: OptimoSyncedRow | null = null;
  const refreshIds: bigint[] = [];
  const result = await db.transaction(async (tx) => {
    const orderId = await loadOrderIdByPublicId(tx, deliveryPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);

    const row = await loadByPublicId(tx, deliveryPublicId);
    assertOriginal(row);

    const mutableStatuses = ["scheduled", "skipped", "paused"] as const;
    if (!mutableStatuses.includes(row.status as (typeof mutableStatuses)[number])) {
      throw new ValidationError(`Cannot reschedule a ${row.status} delivery`);
    }
    if (row.status === "scheduled") {
      assertMutable(row);
    }

    const [order] = await tx.select().from(orders).where(eq(orders.id, orderId)).limit(1);
    if (!order || order.status === "cancelled" || order.status === "completed") {
      throw new ValidationError("This subscription can no longer be rescheduled");
    }

    const [freq] = await tx.select({ key: deliveryFrequencies.key, weekdays: deliveryFrequencies.weekdays }).from(deliveryFrequencies)
      .where(eq(deliveryFrequencies.id, order.frequencyId)).limit(1);
    const deliveryDays = new Set(orderDeliveryDays({
      frequencyKey: freq!.key,
      weekdays: freq!.weekdays as DayOfWeek[] | null,
      includeSaturday: !order.eatingDays?.length && order.includeSaturday,
      includeSunday: !order.eatingDays?.length && order.includeSunday,
    }));
    // Trip weekdays never include sat/sun — weekend food always rides Friday (one rule
    // for legacy weekend add-ons and eating_days orders).
    const deliveryWeekdays = [...deliveryDays].filter((d) => d !== "sat" && d !== "sun") as DayOfWeek[];
    const carriedOn = carryTripDateIso(eatingDateIso, deliveryWeekdays);
    if (!carriedOn) throw new ValidationError("That day isn't on your plan");

    const { timezone, cutoffHour } = await getAppSettings();
    const today = zonedDateIso(Date.now(), timezone);
    if (carriedOn < today) throw new ValidationError("Reschedule date cannot be in the past");
    const newCutoff = cutoffMsFor(carriedOn, cutoffHour, timezone);
    if (Date.now() > newCutoff) throw new ValidationError("That day's cutoff has already passed");

    const [existingMakeup] = await tx.select({ id: deliveries.id }).from(deliveries)
      .where(eq(deliveries.makeupForDeliveryId, row.id)).limit(1);
    if (existingMakeup || row.mergedIntoDeliveryId) throw new ValidationError("This delivery has already been rescheduled");
    // Make-up rows only ever carry moved tiffins.
    if (row.makeupForDeliveryId != null) throw new ValidationError("This tiffin was already moved once. It can't move again.");

    const own = coveredDates(row);
    // No source given: the trip's own day, or its only day when it no longer carries its own.
    const fromEat = sourceEatDate ?? (own.includes(row.deliveryDate) ? row.deliveryDate : own.length === 1 ? own[0]! : null);
    if (!fromEat) throw new ValidationError("Pick which day's tiffin to move.");
    const counts = dateCounts(row, (await loadExtraDates(tx, [row.id])).get(row.id) ?? []);
    if (!counts.has(fromEat)) throw new ValidationError("That day isn't part of this trip anymore.");
    if (fromEat === eatingDateIso) throw new ValidationError("Pick a different day");
    const [{ movedIn }] = await tx.select({ movedIn: sql<number>`count(*)::int` }).from(deliveryMoves)
      .where(and(eq(deliveryMoves.toDeliveryId, row.id), eq(deliveryMoves.toEatDate, fromEat)));
    if (counts.get(fromEat)! - movedIn < 1) throw new ValidationError("This tiffin was already moved once. It can't move again.");

    const whole = tiffinTotal(counts) === 1;
    let moved: { id: bigint; merged: boolean };
    if (whole) {
      if (carriedOn === row.deliveryDate && row.status === "scheduled") {
        // Same truck, other eat day (Fri's only tiffin eaten Sat instead): relabel in place.
        moved = await moveOneTiffin(tx, row, fromEat, eatingDateIso, carriedOn, newCutoff, order.persons);
      } else {
        if (carriedOn === row.deliveryDate) throw new ValidationError("This delivery isn't going out. Pick another day.");
        if (row.status === "scheduled") {
          const skipped = await tx.update(deliveries).set({ status: "skipped" })
            .where(and(eq(deliveries.id, row.id), eq(deliveries.status, "scheduled")))
            .returning({ id: deliveries.id });
          if (skipped.length === 0) throw new ValidationError(`Cannot reschedule a ${row.status} delivery`);
          oldStop = { publicId: row.publicId, routeSyncedAt: row.routeSyncedAt };
        }
        moved = await moveTrip(tx, row, carriedOn, newCutoff, eatingDateIso, order.persons);
      }
    } else {
      moved = await moveOneTiffin(tx, row, fromEat, eatingDateIso, carriedOn, newCutoff, order.persons);
    }
    // Re-push every synced stop whose tiffins changed: the source if it keeps delivering, the target on a merge.
    if (row.status === "scheduled" && (!whole || moved.id === row.id)) refreshIds.push(row.id);
    if (moved.merged && moved.id !== row.id) refreshIds.push(moved.id);

    await tx.insert(deliveryMoves).values({
      orderId, fromDeliveryId: row.id, toDeliveryId: moved.id, fromEatDate: fromEat, toEatDate: eatingDateIso, organizationId: row.organizationId,
    });
    const where = carriedOn === eatingDateIso ? carriedOn : `${eatingDateIso} (rides ${carriedOn})`;
    await tx.insert(orderActivities).values(
      moved.id === row.id
        ? [{ orderId, deliveryId: row.id, type: "note", note: `Moved ${fromEat}'s tiffin to ${eatingDateIso} on the same delivery`, createdBy: actorId }]
        : [
            { orderId, deliveryId: row.id, type: whole && row.status === "scheduled" ? "skipped" : "note", note: `Moved ${fromEat}'s tiffin to ${where}${moved.merged ? " (merged)" : ""}`, createdBy: actorId },
            { orderId, deliveryId: moved.id, type: "pool_scheduled", note: `${fromEat}'s tiffin from ${row.deliveryDate}, now eaten ${eatingDateIso}`, createdBy: actorId },
          ],
    );
    return { merged: moved.merged, carriedOn };
  });
  if (oldStop) await deleteFromOptimoRouteBestEffort([oldStop]);
  for (const id of refreshIds) await refreshStopBestEffort(id);
  publishAnalyticsLive();
  return result;
}

/**
 * A merge changes the target trip's units and covered days, so a stop already on OptimoRoute
 * must be re-pushed. Best-effort like the delete: the DB change already committed. Only touches
 * a stop we previously synced (routeSyncedAt set), never creates one for an unpushed day.
 * Dynamic import: push.ts imports daily-labels.service, which imports this module.
 */
async function refreshStopBestEffort(deliveryId: bigint): Promise<void> {
  try {
    const [t] = await db.select({ publicId: deliveries.publicId, deliveryDate: deliveries.deliveryDate, routeSyncedAt: deliveries.routeSyncedAt, status: deliveries.status })
      .from(deliveries).where(eq(deliveries.id, deliveryId)).limit(1);
    if (!t || t.routeSyncedAt == null || t.status !== "scheduled") return;
    const { pushOneDelivery } = await import("@/lib/services/optimoroute/push");
    await pushOneDelivery(t.publicId, t.deliveryDate);
  } catch (e) {
    log.error({ err: e, deliveryId: String(deliveryId) }, "optimoroute refresh-after-merge failed");
  }
}

async function moveTripPreflight(tx: Tx, orderId: bigint, date: string): Promise<Delivery | undefined> {
  const [row] = await tx.select().from(deliveries)
    .where(and(eq(deliveries.orderId, orderId), eq(deliveries.deliveryDate, date))).limit(1);
  return row;
}

/**
 * Staff-only (the caller enforces it): OUR failure — the driver could not deliver — so the whole
 * trip is re-delivered on the order's next delivery day and merged there. Rejects with a
 * ValidationError when no eligible next day exists.
 */
export async function redeliverTrip(
  deliveryPublicId: string,
  actorId: bigint | null,
): Promise<{ targetDate: string; merged: boolean }> {
  let syncedRow: OptimoSyncedRow;
  let targetId: bigint;
  const result = await db.transaction(async (tx) => {
    const orderId = await loadOrderIdByPublicId(tx, deliveryPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);
    const row = await loadByPublicId(tx, deliveryPublicId);
    if (row.status !== "scheduled") throw new ValidationError(`Cannot re-deliver a ${row.status} delivery`);

    const [order] = await tx.select().from(orders).where(eq(orders.id, orderId)).limit(1);
    if (!order || order.status === "cancelled" || order.status === "completed") {
      throw new ValidationError("This subscription can no longer be re-delivered");
    }
    const deliveryDays = await orderDeliveryDaySet(tx, order);
    const { timezone, cutoffHour } = await getAppSettings();
    const today = zonedDateIso(Date.now(), timezone);

    let targetDate: string | null = null;
    let targetCutoff = 0;
    let cursor = row.deliveryDate;
    for (let guard = 0; guard < 30 && !targetDate; guard++) {
      try {
        cursor = nextDeliveryDateAfter(cursor, deliveryDays);
      } catch {
        break;
      }
      if (WEEKEND.has(weekdayKey(parseIsoDateUtc(cursor)))) continue;
      const cutoff = cutoffMsFor(cursor, cutoffHour, timezone);
      if (cursor < today || Date.now() > cutoff) continue;
      const occupant = await moveTripPreflight(tx, orderId, cursor);
      if (occupant && occupant.status !== "scheduled") continue;
      targetDate = cursor;
      targetCutoff = cutoff;
    }
    if (!targetDate) throw new ValidationError("No upcoming delivery day to re-deliver on");

    const skipped = await tx.update(deliveries).set({ status: "skipped" })
      .where(and(eq(deliveries.id, row.id), eq(deliveries.status, "scheduled")))
      .returning({ id: deliveries.id });
    if (skipped.length === 0) throw new ValidationError("Cannot re-deliver a delivery that is no longer scheduled");

    const moved = await moveTrip(tx, row, targetDate, targetCutoff, null, order.persons, false);
    await tx.insert(orderActivities).values([
      { orderId, deliveryId: row.id, type: "skipped", note: `Re-delivered on ${targetDate} (driver could not deliver)`, createdBy: actorId },
      { orderId, deliveryId: moved.id, type: "pool_scheduled", note: `Re-delivery of ${row.deliveryDate}${moved.merged ? " (merged)" : ""}`, createdBy: actorId },
    ]);
    syncedRow = { publicId: row.publicId, routeSyncedAt: row.routeSyncedAt };
    targetId = moved.id;
    return { targetDate, merged: moved.merged };
  });
  await deleteFromOptimoRouteBestEffort([syncedRow!]);
  if (result.merged) await refreshStopBestEffort(targetId!);
  publishAnalyticsLive();
  return result;
}

/** Postal zone first, then radius circles (active zones only). Rejects an unserviced postal code. */
export async function resolveZoneId(tx: Tx, postalCode: string): Promise<bigint> {
  const rows = await tx.select({
    id: deliveryZones.id,
    name: deliveryZones.name,
    radiusKm: deliveryZones.radiusKm,
    postalPrefixes: deliveryZones.postalPrefixes,
    slotWindow: deliveryZones.slotWindow,
    active: deliveryZones.active,
  }).from(deliveryZones).where(eq(deliveryZones.active, true));
  const zones = rows.map((z) => ({ ...z, radiusKm: z.radiusKm == null ? null : Number(z.radiusKm) }));
  const hit = await findZone(zones, { postalCode });
  // Deliberately asymmetric with createOrder, which WAITLISTS an unmatched postal code
  // (orders.service.ts ~line 248): an active subscription may not redirect a drop to an
  // unserviced address, whereas a brand-new order can simply wait for coverage.
  if (!hit) throw new ValidationError("We don't deliver to that postal code");
  return hit.id;
}

export async function setDeliveryAddress(
  deliveryPublicId: string,
  pick: { addressPublicId?: string; newAddress?: AddressInput; dropOff?: DropOffValue },
  scope: AddressScope,
  actorId: bigint | null,
): Promise<void> {
  const deliveryId = await db.transaction(async (tx) => {
    const orderId = await loadOrderIdByPublicId(tx, deliveryPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);
    // Re-read post-lock: a concurrent request may have mutated this row while we waited.
    const row = await loadByPublicId(tx, deliveryPublicId);
    // NOTE: no assertOriginal — re-addressing a make-up is the one mutation make-ups permit.
    assertMutable(row);
    if (row.status !== "scheduled") throw new ValidationError(`Cannot re-address a ${row.status} delivery`);

    let address = null;
    if (pick.addressPublicId) {
      address = await addressService.getRow(scope, pick.addressPublicId, tx);
    } else if (pick.newAddress) {
      address = await addressService.create(scope, pick.newAddress, { tx });
      // A new address remembers the drop-off chosen with it, for its next delivery or checkout.
      if (pick.dropOff?.tagId) await setAddressDropOff(scope, { id: address.id }, pick.dropOff, tx);
    }

    let zoneId = null;
    if (address) {
      zoneId = await resolveZoneId(tx, address.postalCode);
    }

    // Omitted = keep this delivery's drop-off; no tag = inherit the plan's.
    const dropOff = pick.dropOff ? await resolveDropOff(pick.dropOff, tx) : undefined;

    // A saved address may carry no recipient name; fall back to the plan's.
    const [plan] = await tx.select({ fullName: orders.fullName }).from(orders).where(eq(orders.id, orderId)).limit(1);
    // Per-delivery changes are never charged: no pricing or ledger writes here.
    const updated = await tx.update(deliveries).set({
      ...(address ? {
        addressId: address.id,
        fullName: address.fullName ?? plan?.fullName ?? null,
        addressLine: address.addressLine,
        addressUnit: address.addressUnit,
        city: address.city,
        postalCode: address.postalCode,
        deliveryInstructions: address.deliveryInstructions,
        zoneId,
      } : {}),
      ...(dropOff ? { deliveryTagId: dropOff.tagId, deliveryStrategyIds: dropOff.strategyIds } : {}),
    })
      .where(and(eq(deliveries.id, row.id), eq(deliveries.status, "scheduled")))
      .returning({ id: deliveries.id });
    if (updated.length === 0) throw new ValidationError(`Cannot re-address a ${row.status} delivery`);
    await tx.insert(orderActivities).values({
      orderId, deliveryId: row.id, type: "delivery_address_changed", createdBy: actorId,
    });
    return row.id;
  });
  await refreshStopBestEffort(deliveryId);
}

export async function clearDeliveryAddress(deliveryPublicId: string, actorId: bigint | null): Promise<void> {
  await db.transaction(async (tx) => {
    const orderId = await loadOrderIdByPublicId(tx, deliveryPublicId);
    await tx.execute(sql`select pg_advisory_xact_lock(${orderId})`);
    const row = await loadByPublicId(tx, deliveryPublicId);
    assertMutable(row);
    if (row.status !== "scheduled") throw new ValidationError(`Cannot re-address a ${row.status} delivery`);
    const updated = await tx.update(deliveries)
      .set({
        addressId: null, fullName: null, addressLine: null, addressUnit: null, city: null, postalCode: null,
        deliveryInstructions: null, deliveryTagId: null, deliveryStrategyIds: [], addressTagId: null, zoneId: null,
      })
      .where(and(eq(deliveries.id, row.id), eq(deliveries.status, "scheduled")))
      .returning({ id: deliveries.id });
    if (updated.length === 0) throw new ValidationError(`Cannot re-address a ${row.status} delivery`);
    await tx.insert(orderActivities).values({
      orderId, deliveryId: row.id, type: "delivery_address_changed", createdBy: actorId,
    });
  });
}

/** addressLine NULL means "inherit the order's address". */
export function effectiveAddress(
  d: Delivery,
  order: Pick<Order, "fullName" | "addressLine" | "city" | "postalCode" | "zoneId"> &
    Partial<Pick<Order, "addressUnit" | "deliveryInstructions" | "deliveryTagId" | "deliveryStrategyIds">>,
) {
  return d.addressLine === null
    ? {
        fullName: order.fullName, addressLine: order.addressLine, addressUnit: order.addressUnit ?? null, city: order.city,
        postalCode: order.postalCode, deliveryInstructions: order.deliveryInstructions ?? null, zoneId: order.zoneId,
        deliveryTagId: order.deliveryTagId ?? null,
        deliveryStrategyIds: order.deliveryStrategyIds ?? [],
      }
    : {
        fullName: d.fullName!, addressLine: d.addressLine, addressUnit: d.addressUnit, city: d.city!,
        postalCode: d.postalCode!, deliveryInstructions: d.deliveryInstructions, zoneId: d.zoneId,
        ...(d.deliveryTagId != null
          ? { deliveryTagId: d.deliveryTagId, deliveryStrategyIds: d.deliveryStrategyIds }
          : { deliveryTagId: order.deliveryTagId ?? null, deliveryStrategyIds: order.deliveryStrategyIds ?? [] }),
      };
}

import { cutoffMsFor, ValidationError, zonedDateIso } from "@foundry/commons";
import { sharedCache } from "@/lib/cache";
import { BaseRepository, UpdatableRepository } from "@foundry/database";
import { and, asc, desc, eq, gte, inArray, sql } from "drizzle-orm";
import { db } from "@/db/client";
import { dishCategories, dishes, mealSelections, mealSizeItems, mealSizes, menuItems, menuWeeks, organization, plans } from "@/db/schema";
import { mondayOfIso } from "@/lib/menu/delivery-dates";
import { requireCategoryIds } from "@/lib/menu/category-ids";
import { getAppSettings, getMealTypes } from "./app-settings.service";
import { dishCategoriesService } from "./dish-categories.service";
import type { DayOfWeek, PosterItem } from "@/lib/menu/poster";
import { SessionBaseService, SessionUpdatableService } from "./session-service";

const menuWeeksEntity = new SessionUpdatableService(new UpdatableRepository(db, menuWeeks, menuWeeks.publicId, menuWeeks.id));
const menuItemsEntity = new SessionBaseService(new BaseRepository(db, menuItems, menuItems.publicId, menuItems.id));

const publishedCache = sharedCache("published-week");

/** Released menu_week identity — shared by Menu poster + Deliveries calendar resolution. */
export type ReleasedWeekRef = {
  id: bigint;
  publicId: string;
  weekStart: string;
};

async function loadReleasedWeek(weekStart: string): Promise<ReleasedWeekRef | null> {
  const [week] = await db
    .select({ id: menuWeeks.id, publicId: menuWeeks.publicId, weekStart: menuWeeks.weekStart })
    .from(menuWeeks)
    .where(and(eq(menuWeeks.weekStart, weekStart), eq(menuWeeks.status, "released")))
    .limit(1);
  return week ?? null;
}

/**
 * Content edits are draft-only. The UI hid the controls on a released week, but nothing
 * server-side stopped the mutation — a stale tab or a direct action call could rewrite a
 * live menu under existing meal_selections, and a removed dish then silently resolved to
 * the day's default with the subscriber never told. Every content mutation goes through
 * assertDraft/draftWeekId so the rule cannot be forgotten at one call site.
 *
 * One message per locked state, so the UI can tell the admin what to do about it.
 */
function lockError(status: string): ValidationError {
  return status === "ready"
    ? new ValidationError("This menu is marked ready — move it back to draft to edit")
    : new ValidationError("This menu is released — edits are locked");
}

async function assertDraft(weekId: bigint) {
  const [week] = await db.select({ status: menuWeeks.status }).from(menuWeeks).where(eq(menuWeeks.id, weekId)).limit(1);
  if (!week) throw new ValidationError("Week not found");
  if (week.status !== "draft") throw lockError(week.status);
}

/** Resolve a week public id to its row id, asserting it is still editable. */
async function draftWeekId(weekPublicId: string): Promise<bigint> {
  const [week] = await db.select({ id: menuWeeks.id, status: menuWeeks.status }).from(menuWeeks)
    .where(eq(menuWeeks.publicId, weekPublicId)).limit(1);
  if (!week) throw new ValidationError("Week not found");
  if (week.status !== "draft") throw lockError(week.status);
  return week.id;
}

/**
 * One row of the builder's working copy. `id` is the menu_item public id, or null for a
 * row the admin has added but not saved yet. There is deliberately no `position`: order is
 * the array order within each (day, slot) group, assigned server-side. The old per-click
 * addItem took a client-computed position, so two fast clicks both read the same stale
 * length and collided — with position derived at save time that race cannot be expressed.
 */
export type DraftMenuItem = {
  id: string | null;
  dayOfWeek: DayOfWeek;
  slot: string;
  dishId: string;
  isDefault: boolean;
};

export type SavedMenuItem = DraftMenuItem & { id: string; position: number };

export const menuService = {
  async upsertWeek(input: { weekStart: string }) {
    // Ordering/edit locks roll per-day at cutoffHour (delivery TZ) — see
    // selectionsService. menu_weeks.orderCutoff is a NOT NULL column we keep
    // populated with a representative value (the first delivery day's cutoff),
    // derived TZ-correctly so it is never the admin's ambiguous local time.
    const { timezone, cutoffHour } = await getAppSettings();
    const cutoffMs = cutoffMsFor(input.weekStart, cutoffHour, timezone);
    const [existing] = await db.select().from(menuWeeks)
      .where(eq(menuWeeks.weekStart, input.weekStart)).limit(1);
    if (existing) return menuWeeksEntity.update(existing.publicId, { orderCutoff: cutoffMs });
    return menuWeeksEntity.create({ weekStart: input.weekStart, orderCutoff: cutoffMs });
  },

  async addItem(input: { menuWeekId: string; dayOfWeek: DayOfWeek; slot: string; dishId: string; position: number }) {
    const [week] = await db.select({ id: menuWeeks.id, status: menuWeeks.status }).from(menuWeeks).where(eq(menuWeeks.publicId, input.menuWeekId)).limit(1);
    if (!week) throw new ValidationError("Week not found");
    if (week.status !== "draft") throw new ValidationError("This menu is released — edits are locked");
    const allowed = new Set((await dishCategoriesService.enabledCategories()).map((s) => s.key));
    if (!allowed.has(input.slot)) throw new ValidationError(`Category "${input.slot}" is not enabled`);
    const categoryId = (await requireCategoryIds([input.slot])).get(input.slot)!;
    const [dish] = await db.select({ id: dishes.id, category: dishes.category }).from(dishes).where(eq(dishes.publicId, input.dishId)).limit(1);
    if (!dish) throw new ValidationError("Dish not found");
    // A categorized dish may only be placed in its own category's slot; a
    // null-category dish stays placeable in any slot (back-compat — I5).
    if (dish.category != null && dish.category !== input.slot) throw new ValidationError("Dish category does not match slot");
    const [dupe] = await db.select({ id: menuItems.id }).from(menuItems)
      .where(and(eq(menuItems.menuWeekId, week.id), eq(menuItems.dayOfWeek, input.dayOfWeek), eq(menuItems.categoryId, categoryId), eq(menuItems.dishId, dish.id))).limit(1);
    if (dupe) return null;
    return menuItemsEntity.create({
      menuWeekId: week.id, dayOfWeek: input.dayOfWeek, categoryId, dishId: dish.id, isDefault: false, position: input.position,
    });
  },

  async removeItem(publicId: string) {
    const [item] = await db.select({ menuWeekId: menuItems.menuWeekId }).from(menuItems).where(eq(menuItems.publicId, publicId)).limit(1);
    if (!item) throw new ValidationError("Menu item not found");
    await assertDraft(item.menuWeekId);
    await menuItemsEntity.delete(publicId);
  },

  async reorderItems(input: { menuWeekId: string; dayOfWeek: DayOfWeek; slot: string; orderedItemIds: string[] }) {
    await draftWeekId(input.menuWeekId);
    // Raw bulk position update by public id; NOT audited (matches existing bulk pattern). Documented.
    await Promise.all(input.orderedItemIds.map((pid, idx) => db.update(menuItems).set({ position: idx }).where(eq(menuItems.publicId, pid))));
  },

  async setDefault(input: { itemId: string }) {
    const [item] = await db
      .select({
        id: menuItems.id,
        menuWeekId: menuItems.menuWeekId,
        dayOfWeek: menuItems.dayOfWeek,
        categoryId: menuItems.categoryId,
        isDefault: menuItems.isDefault,
        weekStatus: menuWeeks.status,
      })
      .from(menuItems)
      .innerJoin(menuWeeks, eq(menuItems.menuWeekId, menuWeeks.id))
      .where(eq(menuItems.publicId, input.itemId))
      .limit(1);
    if (!item) throw new ValidationError("Menu item not found");
    if (item.weekStatus !== "draft") throw new ValidationError("Defaults can only be set on a draft week");

    const wasDefault = item.isDefault;
    // One default per (week, day, slot); toggle off if it was already default.
    // Raw bulk update, NOT audited — matches the reorderItems pattern above.
    await db.transaction(async (tx) => {
      await tx.update(menuItems).set({ isDefault: false }).where(and(
        eq(menuItems.menuWeekId, item.menuWeekId),
        eq(menuItems.dayOfWeek, item.dayOfWeek),
        eq(menuItems.categoryId, item.categoryId),
      ));
      if (!wasDefault) {
        await tx.update(menuItems).set({ isDefault: true }).where(eq(menuItems.id, item.id));
      }
    });
  },

  /**
   * Persist a whole week's working copy in one transaction, diffing against what is stored.
   * This replaces the per-click addItem/removeItem/reorderItems round trips the builder used
   * to fire — those revalidated three paths and re-ran the page's whole query set on every
   * single click.
   *
   * Idempotent: saving the same list twice is a no-op. Concurrency is guarded by
   * expectedUpdatedAt — the week row is stamped under the same predicate, so a second tab
   * that loaded earlier is rejected rather than silently overwriting.
   */
  async saveWeek(input: { menuWeekId: string; expectedUpdatedAt: number; items: DraftMenuItem[]; amend?: boolean }): Promise<{ updatedAt: number; items: SavedMenuItem[]; resetPicks: number }> {
    const [week] = await db
      .select({ id: menuWeeks.id, status: menuWeeks.status })
      .from(menuWeeks).where(eq(menuWeeks.publicId, input.menuWeekId)).limit(1);
    if (!week) throw new ValidationError("Week not found");
    // A released week is editable only through an explicit amend, so nothing can rewrite a
    // live menu by accident. `ready` is frozen either way — it exists to be reviewed.
    if (week.status === "ready") throw lockError("ready");
    if (week.status === "released" && !input.amend) throw lockError("released");

    const allowed = new Set((await dishCategoriesService.enabledCategories()).map((s) => s.key));
    const categoryIdByKey = await requireCategoryIds(input.items.map((i) => i.slot));
    const wantedDishIds = [...new Set(input.items.map((i) => i.dishId))];
    const dishRows = wantedDishIds.length
      ? await db.select({ id: dishes.id, publicId: dishes.publicId, category: dishes.category })
          .from(dishes).where(inArray(dishes.publicId, wantedDishIds))
      : [];
    const dishByPublicId = new Map(dishRows.map((d) => [d.publicId, d]));

    // Same rules addItem enforces per click, applied to the whole list up front so a save
    // is all-or-nothing — a half-valid week must never land.
    const seenCell = new Set<string>();
    const seenDefault = new Set<string>();
    for (const item of input.items) {
      if (!allowed.has(item.slot)) throw new ValidationError(`Category "${item.slot}" is not enabled`);
      const dish = dishByPublicId.get(item.dishId);
      if (!dish) throw new ValidationError("Dish not found");
      // A categorized dish may only be placed in its own category's slot; a
      // null-category dish stays placeable in any slot (back-compat — I5).
      if (dish.category != null && dish.category !== item.slot) throw new ValidationError("Dish category does not match slot");
      const cellKey = `${item.dayOfWeek}:${item.slot}:${item.dishId}`;
      if (seenCell.has(cellKey)) throw new ValidationError("The same dish is listed twice in one day and category");
      seenCell.add(cellKey);
      if (item.isDefault) {
        const groupKey = `${item.dayOfWeek}:${item.slot}`;
        if (seenDefault.has(groupKey)) throw new ValidationError("Only one dish can be the default for a day and category");
        seenDefault.add(groupKey);
      }
    }

    const stored = await db.select({ publicId: menuItems.publicId }).from(menuItems).where(eq(menuItems.menuWeekId, week.id));
    const storedIds = new Set(stored.map((s) => s.publicId));
    for (const item of input.items) {
      if (item.id && !storedIds.has(item.id)) throw new ValidationError("A menu item no longer exists — reload the week before saving");
    }
    const keptIds = new Set(input.items.flatMap((i) => (i.id ? [i.id] : [])));
    const removedIds = stored.map((s) => s.publicId).filter((id) => !keptIds.has(id));

    // Position is the row's index within its own (day, slot) group, in the order the client
    // sent it. Derived here, never trusted from the client.
    const nextPosition = new Map<string, number>();
    const positioned = input.items.map((item) => {
      const groupKey = `${item.dayOfWeek}:${item.slot}`;
      const position = nextPosition.get(groupKey) ?? 0;
      nextPosition.set(groupKey, position + 1);
      return { ...item, position };
    });

    // Picks this save orphans. Deleting them makes the fallback to the day's default
    // explicit and auditable, instead of resolveDeliveryMeal quietly papering over a
    // dangling dish id. Computed before the transaction so the count can be reported.
    const impact = input.amend ? await this.amendImpact({ menuWeekId: input.menuWeekId, items: input.items }) : null;

    const now = Date.now();
    await db.transaction(async (tx) => {
      // Optimistic lock and the week's own timestamp bump in one statement: if another
      // session saved since this client loaded, no row matches and nothing below runs.
      const locked = await tx.update(menuWeeks).set({ updatedAt: now })
        .where(and(eq(menuWeeks.id, week.id), eq(menuWeeks.updatedAt, input.expectedUpdatedAt)))
        .returning({ id: menuWeeks.id });
      if (locked.length === 0) throw new ValidationError("This menu changed in another tab — reload before saving");

      if (impact?.brokenIds.length) await tx.delete(mealSelections).where(inArray(mealSelections.id, impact.brokenIds));

      if (removedIds.length) await tx.delete(menuItems).where(inArray(menuItems.publicId, removedIds));

      const added = positioned.filter((i) => !i.id);
      if (added.length) {
        await tx.insert(menuItems).values(added.map((i) => ({
          menuWeekId: week.id, dayOfWeek: i.dayOfWeek, categoryId: categoryIdByKey.get(i.slot)!,
          dishId: dishByPublicId.get(i.dishId)!.id, isDefault: i.isDefault, position: i.position,
        })));
      }
      // Raw bulk update, NOT audited — matches the existing reorderItems/setDefault pattern.
      for (const i of positioned) {
        if (!i.id) continue;
        await tx.update(menuItems).set({
          dayOfWeek: i.dayOfWeek, categoryId: categoryIdByKey.get(i.slot)!, dishId: dishByPublicId.get(i.dishId)!.id,
          isDefault: i.isDefault, position: i.position, updatedAt: now,
        }).where(eq(menuItems.publicId, i.id));
      }
    });

    // An amend changed a live menu, so the public poster's cached copy is now wrong.
    if (input.amend) await publishedCache.evictAll();

    // Return the persisted list so the client can adopt the new rows' ids without a
    // full page refresh — the refresh per click was the other half of the old cost.
    const [saved, freshWeek] = await Promise.all([this.weekWithItems(input.menuWeekId), db
      .select({ updatedAt: menuWeeks.updatedAt }).from(menuWeeks).where(eq(menuWeeks.id, week.id)).limit(1)]);
    const dishPublicIdById = new Map(dishRows.map((d) => [d.id, d.publicId]));
    return {
      updatedAt: freshWeek[0].updatedAt,
      resetPicks: impact?.resetPicks ?? 0,
      items: saved.items.flatMap((i) => {
        const dishId = dishPublicIdById.get(i.dishId);
        return dishId ? [{ id: i.publicId, dayOfWeek: i.dayOfWeek as DayOfWeek, slot: i.slot, dishId, isDefault: i.isDefault, position: i.position }] : [];
      }),
    };
  },

  /**
   * Duplicate a week's dishes into another week — the single biggest weekly-ops saving,
   * since most weeks are last week with a few swaps. The target must be a draft.
   */
  async copyWeek(input: { fromWeekId: string; toWeekId: string }) {
    const [from] = await db.select({ id: menuWeeks.id }).from(menuWeeks).where(eq(menuWeeks.publicId, input.fromWeekId)).limit(1);
    if (!from) throw new ValidationError("Source week not found");
    const toId = await draftWeekId(input.toWeekId);
    const source = await db.select().from(menuItems).where(eq(menuItems.menuWeekId, from.id)).orderBy(asc(menuItems.position));
    if (source.length === 0) throw new ValidationError("That week has no dishes to copy");
    await db.transaction(async (tx) => {
      await tx.delete(menuItems).where(eq(menuItems.menuWeekId, toId));
      await tx.insert(menuItems).values(source.map((i) => ({
        menuWeekId: toId, dayOfWeek: i.dayOfWeek, categoryId: i.categoryId, dishId: i.dishId,
        isDefault: i.isDefault, position: i.position,
      })));
    });
    return { copied: source.length };
  },

  /**
   * Soft check for the builder: which (plan, day, category) cells would leave a
   * subscriber without a dish if this week went live now. Warnings only — release()
   * does not consult this list.
   *
   * The builder shows the union of categories across a plan type, and offers dishes filtered
   * by dishes.category — but what a subscriber actually receives is filtered by dish_plans
   * membership. So an admin can fill a day that is empty for the veg plan and get no
   * feedback unless we surface it here.
   *
   * Only days that already have dishes are checked: a week that deliberately skips Sunday
   * is not an error, but a Monday built for non-veg only is worth a warning.
   */
  async releaseProblems(weekPublicId: string): Promise<
    { kind: "missing" | "extra"; day: DayOfWeek; planName: string; planPublicId: string; categoryKey: string; categoryLabel: string; dishNames: string[] }[]
  > {
    const [week] = await db.select({ id: menuWeeks.id })
      .from(menuWeeks).where(eq(menuWeeks.publicId, weekPublicId)).limit(1);
    if (!week) throw new ValidationError("Week not found");

    const items = await db
      .select({ dayOfWeek: menuItems.dayOfWeek, slot: dishCategories.key, dishId: menuItems.dishId, dishName: dishes.name })
      .from(menuItems)
      .innerJoin(dishCategories, eq(dishCategories.id, menuItems.categoryId))
      .innerJoin(dishes, eq(dishes.id, menuItems.dishId))
      .where(eq(menuItems.menuWeekId, week.id));
    if (items.length === 0) return [];
    const daysWithItems = [...new Set(items.map((i) => i.dayOfWeek))] as DayOfWeek[];

    // Every active plan: one week now serves all of them, so a hole for any plan is a hole.
    const planRows = await db.select({ id: plans.id, name: plans.name, publicId: plans.publicId })
      .from(plans).where(eq(plans.active, true));

    const problems: {
      kind: "missing" | "extra";
      day: DayOfWeek;
      planName: string;
      planPublicId: string;
      categoryKey: string;
      categoryLabel: string;
      dishNames: string[];
    }[] = [];
    for (const plan of planRows) {
      const [categories, requiredRows, membership] = await Promise.all([
        dishCategoriesService.forPlan(plan.id),
        // How much of each category this plan's biggest active meal size asks for. Keyed by
        // the ITEM's own planId, not its parent meal size's — an item can independently
        // target a different plan than the meal size it's on. A category nobody orders is
        // not required, so it cannot block a release.
        db.select({ category: mealSizeItems.category })
          .from(mealSizeItems)
          .innerJoin(mealSizes, eq(mealSizeItems.mealSizeId, mealSizes.id))
          .where(and(eq(mealSizeItems.planId, plan.id), eq(mealSizes.active, true))),
        db.select({ dishId: dishes.id }).from(dishes).where(eq(dishes.planId, plan.id)),
      ]);
      const required = new Set(requiredRows.map((r) => r.category));
      const planDishIds = new Set(membership.map((m) => m.dishId));

      for (const day of daysWithItems) {
        for (const category of categories) {
          if (!required.has(category.key)) continue;
          // Plan membership first, exactly as resolveCategoriesForDay does it. That ordering
          // is why several dishes in one fixed category can be correct: one per plan. Only
          // dishes reaching the SAME plan compete, and only then is the surplus dead.
          const served = items.filter(
            (i) => i.dayOfWeek === day && i.slot === category.key && planDishIds.has(i.dishId),
          );
          if (served.length === 0) {
            problems.push({ kind: "missing", day, planName: plan.name, planPublicId: plan.publicId, categoryKey: category.key, categoryLabel: category.label, dishNames: [] });
          } else if (!category.selectable && served.length > 1) {
            // A fixed category serves exactly one dish per subscriber (the default, else the
            // lowest position), so anything past the first never reaches this plan's plate.
            problems.push({
              kind: "extra",
              day,
              planName: plan.name,
              planPublicId: plan.publicId,
              categoryKey: category.key,
              categoryLabel: category.label,
              dishNames: served.map((i) => i.dishName),
            });
          }
        }
      }
    }
    return problems;
  },

  /**
   * Customer picks this save would invalidate. A pick survives only while the dish it points
   * at is still on the menu for that exact day and category — otherwise resolveDeliveryMeal
   * silently falls back to the day's default, which is how an amend used to change what
   * somebody eats without anyone being told.
   */
  async amendImpact(input: { menuWeekId: string; items: DraftMenuItem[] }) {
    const [week] = await db.select({ id: menuWeeks.id }).from(menuWeeks).where(eq(menuWeeks.publicId, input.menuWeekId)).limit(1);
    if (!week) throw new ValidationError("Week not found");

    const picks = await db
      .select({ id: mealSelections.id, dayOfWeek: mealSelections.dayOfWeek, slot: dishCategories.key, orderId: mealSelections.orderId, dishPublicId: dishes.publicId })
      .from(mealSelections)
      .innerJoin(dishes, eq(mealSelections.dishId, dishes.id))
      .innerJoin(dishCategories, eq(dishCategories.id, mealSelections.categoryId))
      .where(eq(mealSelections.menuWeekId, week.id));

    const surviving = new Set(input.items.map((i) => `${i.dayOfWeek}:${i.slot}:${i.dishId}`));
    const broken = picks.filter((p) => !surviving.has(`${p.dayOfWeek}:${p.slot}:${p.dishPublicId}`));
    return {
      resetPicks: broken.length,
      affectedOrders: new Set(broken.map((p) => String(p.orderId))).size,
      days: [...new Set(broken.map((p) => p.dayOfWeek))] as DayOfWeek[],
      brokenIds: broken.map((p) => p.id),
    };
  },

  async markReady(weekPublicId: string) {
    const [week] = await db.select({ status: menuWeeks.status }).from(menuWeeks).where(eq(menuWeeks.publicId, weekPublicId)).limit(1);
    if (!week) throw new ValidationError("Week not found");
    if (week.status !== "draft") throw new ValidationError("Only a draft can be marked ready");
    await menuWeeksEntity.update(weekPublicId, { status: "ready" });
  },

  async backToDraft(weekPublicId: string) {
    const [week] = await db.select({ status: menuWeeks.status }).from(menuWeeks).where(eq(menuWeeks.publicId, weekPublicId)).limit(1);
    if (!week) throw new ValidationError("Week not found");
    if (week.status !== "ready") throw new ValidationError("Only a week marked ready can go back to draft");
    await menuWeeksEntity.update(weekPublicId, { status: "draft" });
  },

  async release(weekPublicId: string) {
    const [week] = await db.select({ status: menuWeeks.status }).from(menuWeeks).where(eq(menuWeeks.publicId, weekPublicId)).limit(1);
    if (!week) throw new ValidationError("Week not found");
    if (week.status === "released") throw new ValidationError("This menu is already released");

    // Gaps (missing categories / surplus on a fixed slot) stay as builder warnings via
    // releaseProblems — they do not block going live. Kitchen/ops may ship a partial week
    // on purpose (e.g. weekends empty for some plans).

    await menuWeeksEntity.update(weekPublicId, { status: "released", releasedAt: Date.now() });
    await publishedCache.evictAll();
  },

  // getPublishedWeek caches slots + theme per plan; callers that change either
  // (slot edits, meal-type theme) must evict so the public poster isn't stale.
  async evictPublishedCache() {
    await publishedCache.evictAll();
  },

  async listWeeks() {
    const rows = await db
      .select({
        publicId: menuWeeks.publicId,
        weekStart: menuWeeks.weekStart,
        status: menuWeeks.status,
        releasedAt: menuWeeks.releasedAt,
        itemCount: sql<number>`count(${menuItems.id})`,
      })
      .from(menuWeeks)
      .leftJoin(menuItems, eq(menuItems.menuWeekId, menuWeeks.id))
      .groupBy(menuWeeks.id)
      .orderBy(desc(menuWeeks.weekStart));
    return rows.map((r) => ({ ...r, itemCount: Number(r.itemCount) }));
  },

  async listWeekMenus() {
    const weeks = await db
      .select({ id: menuWeeks.id, publicId: menuWeeks.publicId, weekStart: menuWeeks.weekStart, status: menuWeeks.status, releasedAt: menuWeeks.releasedAt })
      .from(menuWeeks)
      .orderBy(desc(menuWeeks.weekStart));
    const categories = await dishCategoriesService.enabledCategories();
    if (weeks.length === 0) return [];
    const rows = await db
      .select({ menuWeekId: menuItems.menuWeekId, dayOfWeek: menuItems.dayOfWeek, slot: dishCategories.key, position: menuItems.position, dishName: dishes.name })
      .from(menuItems)
      .innerJoin(dishes, eq(menuItems.dishId, dishes.id))
      .innerJoin(dishCategories, eq(dishCategories.id, menuItems.categoryId))
      .where(inArray(menuItems.menuWeekId, weeks.map((w) => w.id)))
      .orderBy(asc(menuItems.position));
    const byWeek = new Map<bigint, PosterItem[]>();
    for (const r of rows) {
      const list = byWeek.get(r.menuWeekId) ?? [];
      list.push({ dayOfWeek: r.dayOfWeek as DayOfWeek, slot: r.slot, dishName: r.dishName, position: r.position });
      byWeek.set(r.menuWeekId, list);
    }
    return weeks.map((w) => {
      const items = byWeek.get(w.id) ?? [];
      return { publicId: w.publicId, weekStart: w.weekStart, status: w.status, releasedAt: w.releasedAt, itemCount: items.length, slots: categories, items };
    });
  },

  async weekWithItems(weekPublicId: string) {
    const [week] = await db.select().from(menuWeeks).where(eq(menuWeeks.publicId, weekPublicId)).limit(1);
    if (!week) return { week: undefined, items: [] };
    // Explicit projection with the category key aliased back to `slot`: storage is a foreign
    // key now, but every caller above this line still works in keys.
    const items = await db
      .select({
        publicId: menuItems.publicId,
        menuWeekId: menuItems.menuWeekId,
        dayOfWeek: menuItems.dayOfWeek,
        slot: dishCategories.key,
        categoryId: menuItems.categoryId,
        dishId: menuItems.dishId,
        isDefault: menuItems.isDefault,
        position: menuItems.position,
      })
      .from(menuItems)
      .innerJoin(dishCategories, eq(dishCategories.id, menuItems.categoryId))
      .where(eq(menuItems.menuWeekId, week.id))
      .orderBy(asc(menuItems.position));
    return { week, items };
  },

  /**
   * Exact released week for a planType + weekStart (Monday ISO). Same gate Deliveries and
   * customer Menu use — never falls back to another week.
   */
  async getReleasedWeek(weekStart: string): Promise<ReleasedWeekRef | null> {
    return loadReleasedWeek(weekStart);
  },

  /** Batch of released weeks for calendar ranges; preserves exact weekStart matching. */
  async getReleasedWeeks(weekStarts: string[]): Promise<ReleasedWeekRef[]> {
    if (weekStarts.length === 0) return [];
    return db
      .select({ id: menuWeeks.id, publicId: menuWeeks.publicId, weekStart: menuWeeks.weekStart })
      .from(menuWeeks)
      .where(and(inArray(menuWeeks.weekStart, weekStarts), eq(menuWeeks.status, "released")));
  },

  /**
   * `organizationId` is the URL-resolved org from proxy.ts (Task 3/4 —
   * resolveRequestOrg). Additive alongside the existing `app_id`-scoped
   * queries below: today's single-tenant deployment has exactly one
   * organization row, so this is a no-op scoping check for now, not a
   * behavior change. A resolved id that matches no organization fails
   * closed (null), never falling through to the unscoped query.
   */
  async getPublishedWeek(weekStart?: string, organizationId?: string | null) {
    if (organizationId) {
      const [org] = await db.select({ id: organization.id }).from(organization).where(eq(organization.id, organizationId)).limit(1);
      if (!org) return null;
    }
    return publishedCache.getOrSet(`${weekStart ?? "current"}:${organizationId ?? "-"}`, async () => {
      const base = eq(menuWeeks.status, "released");
      // Explicit weekStart → same exact-match path as getReleasedWeek (Menu/Deliveries agree).
      // No weekStart → soonest released on/after this Monday (app TZ), else latest released
      // (marketing/PDF "current poster" only — not customer calendar).
      let weekId: bigint | undefined;
      let resolvedWeekStart: string | undefined;
      if (weekStart) {
        const ref = await loadReleasedWeek(weekStart);
        if (!ref) return null;
        weekId = ref.id;
        resolvedWeekStart = ref.weekStart;
      } else {
        const { timezone } = await getAppSettings();
        const thisMonday = mondayOfIso(zonedDateIso(Date.now(), timezone));
        const current = await db.select({ id: menuWeeks.id, weekStart: menuWeeks.weekStart }).from(menuWeeks)
          .where(and(base, eq(menuWeeks.weekStart, thisMonday)))
          .limit(1);
        const week = current[0];
        if (!week) return null;
        weekId = week.id;
        resolvedWeekStart = week.weekStart;
      }
      const rows = await db
        .select({
          dayOfWeek: menuItems.dayOfWeek,
          slot: dishCategories.key,
          position: menuItems.position,
          dishName: dishes.name,
          image: dishes.image,
          dishPublicId: dishes.publicId,
        })
        .from(menuItems)
        .innerJoin(dishes, eq(menuItems.dishId, dishes.id))
        .innerJoin(dishCategories, eq(dishCategories.id, menuItems.categoryId))
        .where(eq(menuItems.menuWeekId, weekId)).orderBy(asc(menuItems.position));
      // One consolidated menu: every enabled category, and the tiffin poster theme —
      // there is a single public poster now, not one per plan type.
      const categories = await dishCategoriesService.enabledCategories();
      const cfg = (await getMealTypes()).tiffin;
      const items: PosterItem[] = rows.map((r) => ({
        dayOfWeek: r.dayOfWeek as DayOfWeek,
        slot: r.slot,
        dishName: r.dishName,
        position: r.position,
        image: r.image ?? null,
        dishPublicId: r.dishPublicId,
      }));
      return { theme: { accent: cfg.accent, titlePrefix: cfg.titlePrefix }, weekStart: resolvedWeekStart!, slots: categories, items };
    });
  },
};

import { eq } from "drizzle-orm";
import { db } from "@/db/client";
import { deliveries, orderActivities } from "@/db/schema";
import { publishAnalyticsLive } from "@/lib/realtime/publish-inbox";
import { loadDayDeliveries, type DayDeliveryRow } from "@/lib/services/daily-labels.service";
import { skipDelivery } from "@/lib/services/deliveries.service";
import { getCompletionDetails, getOrderDetails, getRoutes, type OptimoStop } from "./client";
import { normalisePhone } from "./push";
import { tripDetail } from "./trip-notes";

// The half of the integration that turns a driver's real-world action into a real-world
// tiffin count. Driven from OUR side (every scheduled delivery for the date), not
// OptimoRoute's — the account is shared with another business (see push.ts), so looping
// over OptimoRoute's stops instead would mean wading through someone else's data to find
// ours, and would have nothing to say about a delivery OptimoRoute has no stop for at all.
//
// Three outcomes per delivery, deliberately not treated the same:
//
//   "success" only records confirmation — the cutoff-passed-and-still-scheduled default
//   (lib/services/tiffin-counts.ts) already counts the delivery, and stays the source of
//   truth for billing. A late/missing sync must never make an already-delivered tiffin
//   look undelivered.
//
//   "failed", or still not "success" once the cutoff has passed (a driver never got to it, or
//   never closed it out) — skipDelivery() marks the row not delivered, so billing stops counting
//   it. Nothing is re-delivered automatically: the customer or staff moves each tiffin to a new
//   day with Move (see rescheduleDelivery). Before
//   cutoff, "not success yet" just means the day isn't over — left alone, not a miss.
//
//   No matching OptimoRoute stop at all is NOT treated as a miss. That means the route was
//   never pushed (or push/match failed) — an operational gap, not evidence food didn't go
//   out. Auto-skipping on missing data would silently drop a real, delivered day
//   any time staff forgot to click "Send stops". Reported separately so it gets investigated.
//
// Matching is phone-first, not orderNo-first, because today's real OptimoRoute account has
// stops entered by the legacy spreadsheet process, keyed by customer name — not by anything
// this app generates. Once this app is the only thing pushing (orderNo = our delivery's
// publicId, see push.ts), the exact-publicId path below is what actually fires; the
// phone fallback keeps working for the migration period without needing a second run.

export type CompletionOutcome = {
  deliveryPublicId: string;
  customerName: string;
  /** What OptimoRoute actually said — "success" | "failed" | "scheduled" (never attempted) | null (no data at all). */
  optimoStatus: string | null;
  /** What we did about it — "confirmed" for a success, "skipped" for anything else after cutoff. */
  action: "confirmed" | "skipped" | "skip_failed";
  skipError?: string;
  /** Tiffins on the stop and the days they cover, so a failed multi-day trip reads as such. */
  tiffinUnits: number;
  coverage: string | null;
};

export type CompletionAmbiguous = {
  phone: string;
  deliveryPublicId: string;
  candidateCount: number;
};

export type PullCompletionsResult = {
  date: string;
  outcomes: CompletionOutcome[];
  /** One of our deliveries' phone matched more than one OptimoRoute stop for the date — never guessed. */
  ambiguous: CompletionAmbiguous[];
  /** Matched a stop, but its cutoff hasn't passed yet and OptimoRoute hasn't confirmed success —
   *  too early to call it a miss. Re-pull after cutoff. */
  pendingCount: number;
  /** No OptimoRoute stop found for this delivery at all — a push/sync gap, not a delivery
   *  outcome. Left untouched (falls back to the time-based default), listed by name so
   *  staff know which customers to check rather than just a bare count. */
  unmatched: { deliveryPublicId: string; customerName: string }[];
};

export async function pullCompletions(
  date: string,
  actorId: bigint | null = null,
): Promise<PullCompletionsResult> {
  const rows = await loadDayDeliveries(date);

  const routes = await getRoutes(date);
  const stops = routes.flatMap((r) => r.stops ?? []).filter((s) => s.id && s.orderNo && s.orderNo !== "-");
  const ids = stops.map((s) => s.id!);

  const [orderDetails, completions] = await Promise.all([
    getOrderDetails(ids),
    getCompletionDetails(ids),
  ]);

  const stopByOrderNo = new Map<string, OptimoStop>();
  const stopsByPhone = new Map<string, OptimoStop[]>();
  for (const stop of stops) {
    stopByOrderNo.set(stop.orderNo!, stop);
    const phone = normalisePhone(orderDetails.get(stop.id!)?.customField1);
    if (!phone) continue;
    const existing = stopsByPhone.get(phone);
    if (existing) existing.push(stop);
    else stopsByPhone.set(phone, [stop]);
  }

  const now = Date.now();
  const outcomes: CompletionOutcome[] = [];
  const ambiguous: CompletionAmbiguous[] = [];
  let pendingCount = 0;
  const unmatched: { deliveryPublicId: string; customerName: string }[] = [];

  for (const row of rows) {
    const phone = normalisePhone(row.customerPhone);
    let stop = stopByOrderNo.get(row.delivery.publicId);
    if (!stop) {
      const candidates = phone ? stopsByPhone.get(phone) : undefined;
      if (candidates && candidates.length === 1) {
        stop = candidates[0];
      } else if (candidates && candidates.length > 1) {
        ambiguous.push({ phone, deliveryPublicId: row.delivery.publicId, candidateCount: candidates.length });
        continue;
      } else {
        unmatched.push({ deliveryPublicId: row.delivery.publicId, customerName: row.order.fullName });
        continue;
      }
    }

    const completion = completions.get(stop.id!);
    const optimoStatus = completion?.status ?? null;
    const isSuccess = optimoStatus === "success";
    const trip = tripDetail(row);
    const cutoffPassed = row.delivery.cutoffAt <= now;

    if (!isSuccess && !cutoffPassed) {
      // Not confirmed yet, but the day isn't over — could still happen. Not a miss.
      pendingCount += 1;
      continue;
    }

    const completedAtMs = completion?.endTime?.unixTimestamp ? completion.endTime.unixTimestamp * 1000 : now;
    const note = isSuccess ? null : (completion?.form?.note?.trim() || null);

    await db.update(deliveries).set({
      optimoCompletionStatus: optimoStatus,
      optimoCompletedAt: completedAtMs,
      optimoCompletionNote: note,
    }).where(eq(deliveries.id, row.delivery.id));

    if (isSuccess) {
      await db.insert(orderActivities).values({
        orderId: row.order.id,
        deliveryId: row.delivery.id,
        type: "route_completed",
        note: "Confirmed delivered via OptimoRoute",
        createdBy: actorId,
      });
      outcomes.push({
        deliveryPublicId: row.delivery.publicId,
        customerName: row.order.fullName,
        optimoStatus,
        action: "confirmed",
        tiffinUnits: trip.units,
        coverage: trip.coverage,
      });
      continue;
    }

    // Cutoff has passed and OptimoRoute never confirmed success — explicit failure or a
    // stop that just never got closed out; either way, no tiffin went out.
    let skipError: string | undefined;
    let skipped = false;
    try {
      // skipDelivery()'s cutoff lock exists to stop a customer self-service-cancelling
      // too late — it must not block this reconciliation, which by construction (the
      // cutoffPassed gate above) only ever runs once that cutoff has already passed.
      await skipDelivery(row.delivery.publicId, actorId, { bypassCutoffLock: true });
      skipped = true;
    } catch (e) {
      // Already paused/cancelled/skipped by something else in the meantime — the
      // completion is still recorded above, just nothing left to flip.
      skipError = e instanceof Error ? e.message : "Unknown error";
    }

    const reason =
      optimoStatus === "failed"
        ? `OptimoRoute reported delivery failed${note ? `: ${note}` : ""}`
        : "Cutoff passed with no delivery confirmation from OptimoRoute";
    await db.insert(orderActivities).values({
      orderId: row.order.id,
      deliveryId: row.delivery.id,
      type: "route_completed",
      note: `${reason}${skipError ? ` (skip not applied: ${skipError})` : ""}`,
      createdBy: actorId,
    });

    outcomes.push({
      deliveryPublicId: row.delivery.publicId,
      customerName: row.order.fullName,
      optimoStatus,
      action: skipped ? "skipped" : "skip_failed",
      skipError,
      tiffinUnits: trip.units,
      coverage: trip.coverage,
    });
  }

  if (outcomes.length) publishAnalyticsLive();
  return { date, outcomes, ambiguous, pendingCount, unmatched };
}

import { eq } from "drizzle-orm";
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { db } from "./db/client";
import { organization } from "./db/schema";

// Proxy defaults to the Node.js runtime as of Next 16 (setting `export const
// runtime` here throws — the option isn't available for proxy files), so a
// real DB query below is fine. We still do an OPTIMISTIC cookie-presence gate
// for the session check; the authoritative `getSession` role checks live in
// the dashboard layout and pages.
// Better Auth session cookie: `${prefix}.session_token` (default prefix
// "better-auth"; `__Secure-` prefixed when cookies are secure / in production).
const SESSION_COOKIES = ["better-auth.session_token", "__Secure-better-auth.session_token"];

// /api is private by default. Only these prefixes are reachable without a
// session cookie: Better Auth's own handler, cron (self-auths via CRON_SECRET
// bearer inside the route), and the SES feedback webhook (self-auths by
// verifying the SNS message signature). Add a prefix here to make it public.
const PUBLIC_API = ["/api/auth", "/api/cron", "/api/webhooks"];

// Prefixes that never carry a URL-segment clientCode: the console, the API,
// the customer account area, and the (auth) route group's own pages (all
// single-segment, e.g. /login, /signup — none of these are ever a tenant's
// client code). Resolution is skipped for these paths.
const RESOLUTION_EXEMPT = ["/api", "/dashboard", "/me", "/login", "/signup", "/lock", "/verify-email", "/forgot-password", "/set-password"];

// Cross-origin allowlist, comma-separated env. Empty = same-origin only
// (browsers block cross-origin by default — this stays locked until set).
const CORS_ORIGINS = (process.env.CORS_ORIGINS ?? "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

function corsHeaders(origin: string | null): Headers {
  const h = new Headers();
  if (origin && CORS_ORIGINS.includes(origin)) {
    h.set("Access-Control-Allow-Origin", origin);
    h.set("Vary", "Origin");
    h.set("Access-Control-Allow-Credentials", "true");
    h.set("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
    h.set("Access-Control-Allow-Headers", "content-type,authorization");
    h.set("Access-Control-Max-Age", "86400");
  }
  return h;
}

function unauthorized(): NextResponse {
  const body = { type: "about:blank", title: "Unauthorized", status: 401, detail: "Authentication required" };
  return new NextResponse(JSON.stringify(body), {
    status: 401,
    headers: { "content-type": "application/problem+json" },
  });
}

export async function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const hasSession = SESSION_COOKIES.some((name) => request.cookies.has(name));

  // Never trust an incoming x-realm-org-id — only this function is allowed to
  // set it. Strip it unconditionally before any resolution logic runs, so
  // every downstream branch forwards either nothing or a value we resolved.
  request.headers.delete("x-realm-org-id");

  const onApi = pathname.startsWith("/api");
  const onDashboard = pathname.startsWith("/dashboard");
  const resolutionExempt = RESOLUTION_EXEMPT.some((p) => pathname === p || pathname.startsWith(`${p}/`));

  // Set on the forwarded request when a URL-segment/default org resolves, so
  // NextResponse.next() below can carry it through via the `request.headers`
  // forwarding mechanism (Task 4 reads it on the Node side).
  let resolvedOrgId: string | undefined;

  if (!resolutionExempt) {
    const segment = pathname.split("/")[1] || null;
    const [org] = segment
      ? await db.select({ id: organization.id }).from(organization).where(eq(organization.clientCode, segment)).limit(1)
      : [];
    if (org) {
      resolvedOrgId = org.id;
    } else {
      // A visitor-picked franchise (location popup, ip-api-detected or manual)
      // is stored as a plain `franchise` cookie holding clientCode, not org id
      // — it's readable/settable from the client, unlike x-realm-org-id.
      const pickedCode = request.cookies.get("franchise")?.value ?? null;
      const [picked] = pickedCode
        ? await db.select({ id: organization.id }).from(organization).where(eq(organization.clientCode, pickedCode)).limit(1)
        : [];
      if (picked) {
        resolvedOrgId = picked.id;
      } else {
        const [fallback] = await db
          .select({ id: organization.id })
          .from(organization)
          .where(eq(organization.isDefaultLocation, true))
          .limit(1);
        if (fallback) {
          resolvedOrgId = fallback.id;
        } else if (pathname !== "/locations") {
          return NextResponse.redirect(new URL("/locations", request.url));
        }
      }
    }
  }

  if (resolvedOrgId) request.headers.set("x-realm-org-id", resolvedOrgId);
  const forwardedRequest = { request: { headers: request.headers } };

  if (onApi) {
    const origin = request.headers.get("origin");
    const cors = corsHeaders(origin);
    // Preflight carries no cookies — answer before the session gate.
    if (request.method === "OPTIONS") return new NextResponse(null, { status: 204, headers: cors });

    const isPublic = PUBLIC_API.some((p) => pathname === p || pathname.startsWith(`${p}/`));
    if (!isPublic && !hasSession) {
      const res = unauthorized();
      cors.forEach((v, k) => res.headers.set(k, v));
      return res;
    }
    const res = NextResponse.next(forwardedRequest);
    cors.forEach((v, k) => res.headers.set(k, v));
    return res;
  }

  // /me (customer) shares this presence-only gate with /dashboard; the role
  // split (customer vs staff/admin) is decided by the (customer) layout below.
  // Segment-boundary match, not a bare prefix: "/me".startsWith would also
  // catch "/menu" (public) and wrongly force it through the login gate.
  const onGuarded = ["/dashboard", "/me"].some((p) => pathname === p || pathname.startsWith(`${p}/`));
  if (onGuarded && !hasSession) {
    const loginUrl = new URL("/login", request.nextUrl.origin);
    // Keep ?month=&sub= so post-login lands back on the same calendar month.
    const returnTo = `${pathname}${request.nextUrl.search}`;
    loginUrl.searchParams.set("callbackUrl", returnTo);
    return NextResponse.redirect(loginUrl);
  }
  const res = NextResponse.next(forwardedRequest);
  // Protected pages must never sit in the browser's bfcache — otherwise after
  // sign-out the Back button restores the rendered dashboard without re-hitting
  // this gate. no-store makes the browser re-request → redirect to /login.
  if (onGuarded) res.headers.set("Cache-Control", "no-store, must-revalidate");
  return res;
}

export const config = {
  // Was scoped to /dashboard, /me, /api only. Broadened to everything (minus
  // static assets) so the URL-segment org resolver above also runs on public
  // customer-facing routes, not just the guarded ones.
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt|.*\\.(?:svg|json|png|ico|jpg|jpeg|webp|woff|woff2|txt|xml)$).*)",
  ],
};
